ns:RegisterQuestData({
[29547] = { ["id"] = 29547, ["name"] = "The King's Command", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 29547 }, ["series"] = { 29548, 31732, 31733 }, ["description"] = "Greetings, <class>. I have been asked to assemble a team for a high priority mission. Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn. I will be waiting in the King's war room.", ["objectivesText"] = "Find Grand Admiral Jes-Tereth in the war room at Stormwind Keep in Stormwind City .", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 0, ["flags"] = 0 } } },
[29548] = { ["id"] = 29548, ["name"] = "The Mission", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 371, ["storyline"] = { 29548 }, ["series"] = { 29547, 31732, 31733 }, ["description"] = "Well, you heard the King. Admiral Taylor's last transmission came from somewhere in the southern seas. We will begin our search from the air! Locating the Prince - the White Pawn - is of critical priority. The Skyfire is fueled, supplied, and ready to depart. She and her crew idle in the sky just north of the harbor. Make your last preparations, then meet Admiral Rogers on the deck. We will depart without delay.", ["objectivesText"] = "Report to Admiral Rogers on The Skyfire. Progress: Ah, a veteran of the Cataclysm campaigns! Good, I could use more experienced hands.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 15799, 15800, 15801, 29926, 29929, 29933, 29936, 29937, 29940, 29942, 29944, 35888, 35889, 35890, 35891, 35892, 35893, 35894, 35895, 59414, 59415, 59416, 59417, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 1, ["flags"] = 0 } } },
[29552] = { ["id"] = 29552, ["name"] = "Critical Condition", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29552 }, ["description"] = "We may have won the first battle, but a critical task still remains. Dozens of Skyfire pilots were shot down during the initial aerial battle. Without medical aid, their condition will deteriorate over time, until they finally perish. We are their only hope for survival. Go into the orchard and revive as many pilots as you can find. We will leave no one behind.", ["objectivesText"] = "Revive 6 Wounded Pilots in Paw'don Glade. You can also use healing spells or bandages to revive them. Progress: We will remember all the brave Alliance soldiers who fell today. Though they can no longer continue, we carry the fight onward.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 90384, 90385, 90386, 90387, 90388, 90389 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 8, ["flags"] = 0 } } },
[29553] = { ["id"] = 29553, ["name"] = "The Missing Admiral", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29553 }, ["series"] = { 29555 }, ["description"] = "Alright. According to the clues you found, that was Anduin's ship, and Admiral Taylor was the captain. And Admiral Taylor 's last entry says he was going to fight off the hozen and protect the vessel after the shipwreck. The locals say these hozen sometimes take prisoners, and I didn't see Taylor's corpse anywhere among the wreckage. So you'll probably find Taylor at the hozen encampment to the northeast. Get going, we have no time to lose!", ["objectivesText"] = "Find Admiral Taylor .", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 19, ["flags"] = 0 } } },
[29555] = { ["id"] = 29555, ["name"] = "The White Pawn", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29555 }, ["series"] = { 29553 }, ["description"] = "Alright, soldier. I've got a critical mission for you. Get down to the coastline south of here - in the cove there you'll find a wrecked Alliance vessel. I need you to search it and find out if it was the ship that was carrying Anduin. Then, recover the Captain's Log and see if it has any information on where we can find him. Since the log is from a military ship, it'll be written using a cipher - take it to Nodd Codejack afterwards. He's keeping watch on the wreck from the other end of the cove.", ["objectivesText"] = "Search the Wreck of the Vanguard in Jade Forest for clues about its cargo, and recover the Encoded Captain's Log . Progress: Well?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 73410, 89603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 18, ["flags"] = 0 } } },
[29556] = { ["id"] = 29556, ["name"] = "Hozen Aren't Your Friends, Hozen Are Your Enemies", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29556 }, ["description"] = "We've located an Alliance wreck to the south. Unfortunately, the locals have informed us that it's currently being scavenged by a group of creatures called \"hozen.\" By pillaging our wrecked ships, these creatures have already shown that they aren't friendly. We can't have them taking spoils from our ships, stealing our supplies, and worse, potentially capturing or killing any survivors. Get down there and take them out! When you're done, meet up with Nodd Codejack , our SI:7 agent in the area.", ["objectivesText"] = "Kill 14 Hozen at the Wreck of the Vanguard. Progress: These Hozen don't act right. Have you dealt with them?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 17, ["flags"] = 0 } } },
[29558] = { ["id"] = 29558, ["name"] = "The Path of War", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29558 }, ["series"] = { 29559, 29560, 29562, 29759 }, ["description"] = "I see you want to save your friend. I can help you, if you will help me. First of all, it should be obvious that the fewer the Slingtail roaming around, the easier it will be to escape. Kill the hozen guards around us, and we will be one step closer to freedom.", ["objectivesText"] = "Kill 12 Slingtail Treeleapers or Slingtail Mudseers . Progress: You fight well, foreigner.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 20, ["flags"] = 0 } } },
[29559] = { ["id"] = 29559, ["name"] = "Freeing Our Brothers", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29559 }, ["series"] = { 29558, 29560, 29562, 29759 }, ["description"] = "You may be an outsider, but you and I have a common enemy in the hozen. Many members of my tribe are trapped in cages nearby. I have also seen your... Alliance... soldiers as well. I cannot leave without freeing my brethren, just as you cannot leave yours. The Slingtail hold the keys to those cages. Find the keys and free our friends.", ["objectivesText"] = "Free 6 Jinyu Prisoners or Alliance Prisoners. Progress: Are they freed?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74260, 81022, 81023, 81024, 81025, 81026, 81027, 81028, 81029, 81030 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 21, ["flags"] = 0 } } },
[29560] = { ["id"] = 29560, ["name"] = "Ancient Power", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29560 }, ["series"] = { 29558, 29559, 29562, 29759 }, ["description"] = "Hozen skulls are prized tokens among my village. We use them to perform ceremonial rites, and the older the skull, the more potent its magic. Luckily for us, the hozen are careless, filthy beasts. They leave the skulls of their dead scattered among their huts and campfires. Collect these skulls for me, and I will reward you handsomely.", ["objectivesText"] = "Collect 8 Ancient Hozen Skulls . Progress: The skulls are precious to my tribe. How many have you collected?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74033 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 22, ["flags"] = 0 } } },
[29562] = { ["id"] = 29562, ["name"] = "Jailbreak", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29562 }, ["series"] = { 29558, 29559, 29560, 29759 }, ["description"] = "Without healing, your friend Taylor will die. My village is just east of here, in the middle of the large lake. I will take Taylor myself, but the fighting is most dangerous in that direction. I need you to help clear a path through the hozen, so that I may run safely into my village. Can you do this?", ["objectivesText"] = "Kill 10 Slingtail Fishrippers Progress: Our conflict with the hozen goes back many generations.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 24, ["flags"] = 0 } } },
[29578] = { ["id"] = 29578, ["name"] = "Defiance", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29578 }, ["series"] = { 29576 }, ["description"] = "The damn mogu hit us out of nowhere! Anyone they don't kill on sight is being dragged away into the woods. This is the only safehouse, and its all I can do to hold the door. What do you say, friend? Are you willing to stand up and fight for the weak?", ["objectivesText"] = "Kill 8 Gormali Raiders and 8 Gormali Incinerators in Nectarbreeze Orchard. Progress: Don't worry - they won't get through me.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 72578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 30, ["flags"] = 0 } } },
[29579] = { ["id"] = 29579, ["name"] = "Rally the Survivors", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29579 }, ["description"] = "The people of this village are simple farmers - not fighters like you and I. Still, they are stubbornly defending their homes as best they can. Search the village for anyone still on their feet and tell them to rally here at Hanae's place.", ["objectivesText"] = "Speak with 5 Nectarbreeze Farmers around Nectarbreeze Orchard and send them to the safehouse. Progress: Please tell me some still live...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 31, ["flags"] = 0 } } },
[29580] = { ["id"] = 29580, ["name"] = "Orchard-Supplied Hardware", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29580 }, ["description"] = "They may not be weaponmasters, but many of these farmers can wield a simple hoe or a rake as an extension of their own will. That mastery coupled with the right motivation could muster a force capable of standing against the mogu. If you can bring back some tools from the orchard, I'll distribute them to anyone willing to fight.", ["objectivesText"] = "Retrieve 6 Orchard Tools from Nectarbreeze Orchard. Progress: Were there any tools left?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 72133 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 32, ["flags"] = 0 } } },
[29585] = { ["id"] = 29585, ["name"] = "Spitfire", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29585 }, ["description"] = "We've tended these orchards and made cider from their nectar for generations. In that time, we've learned a special trick for putting out fires in a pinch. <Hanae pushes a jug of cider into your hand.> The cider itself - when mixed with crushed gingerleaf and saliva - quickly becomes sticky and viscous. Perfect for smothering flames. Please, while you're out there, try to get the flames under control. I've already mixed in the gingerleaf, just swig and spit.", ["objectivesText"] = "Use the Nectarbreeze Cider to put out 12 fires around Nectarbreeze Orchard.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 20802, 72578, 84243, 84244, 84245, 84246, 84247, 84248, 84249, 84250, 88709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 33, ["flags"] = 0 } } },
[29586] = { ["id"] = 29586, ["name"] = "The Splintered Path", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29586 }, ["series"] = { 29587 }, ["description"] = "First... before the war-cries... we heard the trees. Groaning, creaking, and finally crashing down as the mogu cut their way through the woods. They were making the return trip easier... They're dragging our friends back down that path, to the ruins west of the village! Those ruins have been empty for years - our children play there. Why would the mogu come back to them now?", ["objectivesText"] = "Follow the path of fallen trees from the northwest corner of Nectarbreeze Orchard and find the mogu raiders camp.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 34, ["flags"] = 0 } } },
[29587] = { ["id"] = 29587, ["name"] = "Unbound", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29587 }, ["series"] = { 29586 }, ["description"] = "Can you see them, $p? Farmers from the orchard, tied up and under inspection. Being hauled off in chains. The mogu value strength above all else. Anyone deemed fit for work will be sent to toil under their cruel whips. As for the others, well... Let's not waste any more time.", ["objectivesText"] = "Set 10 Captured Nectarbreeze Farmers free in Camp Gormal.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 63799, 63800, 63801, 63802, 63803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 35, ["flags"] = 0 } } },
[29611] = { ["id"] = 29611, ["name"] = "The Art of War", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29611 }, ["series"] = { 29612, 29690, 31765, 31766, 31767, 31768, 31769, 31853 }, ["description"] = "Lok'tar ogar, <race>. I am Nazgrim. You are hereby ordered to present yourself to Garrosh Hellscream at Grommash Hold immediately. By his decree, all in service to the Horde are to swear an oath of allegiance to their new Warchief. Do not keep him waiting, <race>.", ["objectivesText"] = "Speak to General Nazgrim in Grommash Hold Progress: Blood and thunder, <race>.", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["rewardItems"] = { 59039 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 1, ["flags"] = 0 } } },
[29612] = { ["id"] = 29612, ["name"] = "The Art of War", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 29612 }, ["series"] = { 29611, 29690, 31765, 31766, 31767, 31768, 31769, 31853 }, ["description"] = "Lok'tar Ogar, old friend. It has been too long since last we spoke. It is good to see that you emerged safely from the depths of Vashj'ir. Warchief Hellscream has stationed me here in Grommash Hold. By his decree, all in service to the Horde are to swear allegiance to their new Warchief. You would do well not to keep him waiting, <name>.", ["objectivesText"] = "Speak to General Nazgrim in Grommash Hold in Orgrimmar . Progress: Blood and thunder, <name>!", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["rewardItems"] = { 59039 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 0, ["flags"] = 0 } } },
[29618] = { ["id"] = 29618, ["name"] = "The High Elder", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29618 }, ["series"] = { 29617 }, ["description"] = "How strange, to have such a foreign-looking <class> visiting our temple. Are you here to study? You... you look very strong. You wouldn't have any trouble getting accepted into the monastery. You should talk to the High Elder, up on the balcony above.", ["objectivesText"] = "Speak with High Elder Cloudfall at the Tian Monastery in the Jade Forest .", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["rewardItems"] = { 21100, 21746 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 10, ["flags"] = 0 } } },
[29619] = { ["id"] = 29619, ["name"] = "A Courteous Guest", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29619 }, ["series"] = { 29620 }, ["description"] = "I heard, I heard! The High Elder wants you to train with us! There's going to be a banquet for us, the trainees... and you should probably bring a gift, as a sign of courtesy. The oranges in the grove south of the temple are extra-sweet right now. Bring some back, for the banquet.", ["objectivesText"] = "Gather 8 Ripe Oranges from the orange groves south of Tian Monastery. Progress: Are you ready for the banquet? I can't wait.", ["rewardGold"] = 98000, ["rewardXP"] = 83000, ["rewardItems"] = { 72589 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 11, ["flags"] = 0 } } },
[29620] = { ["id"] = 29620, ["name"] = "The Great Banquet", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29620 }, ["series"] = { 29619 }, ["description"] = "The banquet should be starting any time now. Go find the High Elder and pay your respects. I'll be right behind you.", ["objectivesText"] = "Speak with High Elder Cloudfall at the banquet grounds in the Tian Monastery. Progress: We will move on to the training soon enough, young <class>. First, we must talk, and drink, and eat. Though I must say, I admire your discipline.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 12, ["flags"] = 0 } } },
[29622] = { ["id"] = 29622, ["name"] = "Your Training Starts Now", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29622 }, ["series"] = { 29623, 29624, 29625, 29639 }, ["description"] = "< Xiao does not look up from his bowl.> Hey, new <guy/lady>! Glad to see you survived the banquet! Trial One: Complete! < Xiao eats noisily.> You'd better speak up with Instructor Xann . He'll be expecting you for your daily exercises. <He continues eating. You suspect that he is done talking to you.>", ["objectivesText"] = "Report to Instructor Xann at the Tian Monastery in the Jade Forest .", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 13, ["flags"] = 0 } } },
[29623] = { ["id"] = 29623, ["name"] = "Perfection", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29623 }, ["series"] = { 29622, 29624, 29625, 29639 }, ["description"] = "Perfection can be achieved through repetition. Every single student in the training arena below will eventually perfect his or her form... assuming they don't give up first. This is a fact. I encourage you to join them, <name>. As an honorary guest of the monastery, you are not required to perform the requisite 10,000 daily strikes. Simply follow the leader's example for a few minutes.", ["objectivesText"] = "Perform 12 practice strikes in the Monastery Training Arena by following the leader's example. Progress: I, too, once trained in this very arena. Times were simpler then.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 14, ["flags"] = 0 } } },
[29624] = { ["id"] = 29624, ["name"] = "Attention", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29624 }, ["series"] = { 29622, 29623, 29625, 29639 }, ["description"] = "Your next test also involves concentration and attention. I want you to practice your abilities on the training bags in the pit below. The bags are hung in groups of two. When I call out \"Left\", attack the bag on the left. When I call out \"Right\", attack the bag on the right. If you fail to follow my simple directions, this task will become much harder. Now beat on those practice bags until they burst, <name>.", ["objectivesText"] = "Destroy 2 Training Bags . Follow Instructor Xann 's instructions to determine which bags to attack. Progress: What are you waiting for?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80731, 80732, 80733, 80734, 80735, 80736, 80737, 80738, 80739 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 15, ["flags"] = 0 } } },
[29626] = { ["id"] = 29626, ["name"] = "Groundskeeper Wu", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29626 }, ["series"] = { 29627 }, ["description"] = "We don't have many rules here, but we do have one particular rule that is worth remembering. If you want to eat... < Xiao 's stomach grumbles audibly.> ...you have to work. Groundskeeper Wu can give you your chores for the day. He's in the market, to the west.", ["objectivesText"] = "Report to Groundskeeper Wu at the Tian Monastery in the Jade Forest .", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 16, ["flags"] = 0 } } },
[29627] = { ["id"] = 29627, ["name"] = "A Proper Weapon", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29627 }, ["series"] = { 29626 }, ["description"] = "First things first, though. A proper trainee needs a proper weapon. And a scrupulous trainee builds his own... or at least gathers the materials. The switches which grow nearby should suffice for any respectable weapon. You'll also need to shop for black walnut extract to treat the wood. While you're there, get some ale, for... <Wu pauses.> ...well, you know what ale is for.", ["objectivesText"] = "Obtain 6 Rattan Switches from the area around the market in the Tian Monastery. Purchase a vial of Black Walnut Extract from June Whiteblossom. Purchase 3 Triple-Bittered Ales from Brewmaster Lei Kanglei. Progress: <Wu looks at you expectantly.>", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 72926, 72954, 72979 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 17, ["flags"] = 0 } } },
[29628] = { ["id"] = 29628, ["name"] = "A Strong Back", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29628 }, ["series"] = { 29629, 29630, 29646 }, ["description"] = "Some of our trainees have... larger-than normal appetites. We have occasionally had difficulty supplying enough food for all of them. In times like these, we have to ask for help. A kindly older woman, who lives in a small house to the northwest, has agreed to make some stew for our trainees. All you need to do is go and get it.", ["objectivesText"] = "Obtain a Boiling Cauldron from Mother Wu in the Waxwood Forest, then return to Groundskeeper Wu in the Tian Monastery. Progress: She really is a nice woman. And an excellent cook. The best cook in the world, actually.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 18, ["flags"] = 0 } } },
[29629] = { ["id"] = 29629, ["name"] = "A Steady Hand", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29629 }, ["series"] = { 29628, 29630, 29646 }, ["description"] = "The black walnut extract you purchased from Miss Whiteblossom is but one of many extracts we keep in stock for various applications. Blushleaf extract can be gathered from the flowers in the Waxwood Forest to the west. Several units can be extracted from one flower, but only those with calm nerves and steady hands can remove all of the extract from one flower.", ["objectivesText"] = "Obtain 80 vials of Blushleaf Extract from Blushleaf Clusters in the Waxwood Forest. Progress: It is said that the ancient herbalism masters were able to remove 20 vials of extract from each blossom.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 73193 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 19, ["flags"] = 0 } } },
[29630] = { ["id"] = 29630, ["name"] = "And a Heavy Fist", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29630 }, ["series"] = { 29628, 29629, 29646 }, ["description"] = "The greenwood sprites in the Waxwood Forest to the west pose no direct threat to us, this is true. However, their numbers have increased as of late, as have their wily antics. Part of our duty as wardens of this forest is to maintain the balance. Your duty is to do so by returning these sprites to the earth.", ["objectivesText"] = "Slay 10 Greenwood Tricksters in the Waxwood Forest. Progress: Very recently, I was walking in the Waxwood, when one of these sprites got on all fours behind my knees, evading my notice. Soon afterward, a second sprite approached me from the front, shoving me forcefully in the chest. Unaware of the first sprite, I stepped backwards, only to stumble on his prostrate form and fall, embarrassingly, onto my backside. So yes, I have a vested interest in this assignment.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80740, 80741, 80742, 80743, 80744, 80745, 80746, 80747, 80748 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 20, ["flags"] = 0 } } },
[29631] = { ["id"] = 29631, ["name"] = "Burning Bright", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29631 }, ["description"] = "Might I ask a favor of you, trainee <name>? Before I came to the monastery, I was a stranger to battle. During my time as a trainee, I performed adequately, but I was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am expected to protect this perimeter at all costs. I can handle greenwood sprites, but the tigers in the western Waxwood are something different altogether. Would you mind taking care of them for me?", ["objectivesText"] = "Slay 6 Waxwood tigers. Progress: Please, do not speak of our arrangement with others. My cowardice shames me.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29632] = { ["id"] = 29632, ["name"] = "Becoming Battle-Ready", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29632 }, ["description"] = "Alright, <race>. I'd like to see what you're really made of. You'll find my pupils all over the monastery. Challenge them to fights. Push them to their limits. They have been instructed to do the same to you. Win or lose, you both will come out of the fight stronger.", ["objectivesText"] = "Defeat 8 Tian Pupils in sparring matches at the Tian Monastery. Progress: You may be a hero in your own lands, but here, you must prove your worth.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 21, ["flags"] = 0 } } },
[29633] = { ["id"] = 29633, ["name"] = "Zhi-Zhi, the Dextrous", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29633 }, ["series"] = { 29634, 29635, 29636, 29637, 29647 }, ["description"] = "Upon the hills to my right, you will find a hozen named Zhi-Zhi . He, too, won enough sparring matches to move up the ranks. I think he will provide you with more of a challenge. Challenge him, and try to defeat him.", ["objectivesText"] = "Defeat Zhi-Zhi at the Tian Monastery. Progress: Zhi-Zhi 's style is different than that of most pandaren monks. He and his kind tend to have more... energy... than us.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 22, ["flags"] = 0 } } },
[29634] = { ["id"] = 29634, ["name"] = "Husshun, the Wizened", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29634 }, ["series"] = { 29633, 29635, 29636, 29637, 29647 }, ["description"] = "The jinyu are long-standing allies of the pandaren, and we welcome any of their kind into our monastery. Husshun , one of their elder shaman, is one of our newest trainees. His skills as a monk are mediocre at best, but he is still a fierce combatant. He should provide you with the challenge that you deserve.", ["objectivesText"] = "Challenge and defeat Husshun at the Tian Monastery. Progress: I do not know why he decided to take the monastic path so late in life. It is not my place to ask. Such questions fall under the responsibility of our Spirit-Sage.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 23, ["flags"] = 0 } } },
[29635] = { ["id"] = 29635, ["name"] = "Xiao, the Eater", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29635 }, ["series"] = { 29633, 29634, 29636, 29637, 29647 }, ["description"] = "You may have already met my best student, Xiao , at the banquet tables. I personally would have graduated him several times over, but Instructor Xann insists that he needs more discipline. If you ask me, discipline means very little if you win every fight you enter. I'm curious to see if Xiao can keep his streak alive against you.", ["objectivesText"] = "Challenge and defeat Xiao at the Tian Monastery. Progress: Young Xiao has a great future in martial arts. I wish you luck in your upcoming match.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 88690, 88691, 88692, 88693, 88694, 88695, 88696, 88697, 88698 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 24, ["flags"] = 0 } } },
[29636] = { ["id"] = 29636, ["name"] = "A Test of Endurance", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29636 }, ["series"] = { 29633, 29634, 29635, 29637, 29647 }, ["description"] = "I have taught you everything that I can, <name>. It is time you spoke with Instructor Myang . The fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait. Farewell, <name>, and best of luck on the remainder of your training.", ["objectivesText"] = "Report to Instructor Myang on the western side of the Tian Monastery.", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 25, ["flags"] = 0 } } },
[29637] = { ["id"] = 29637, ["name"] = "The Rumpus", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29637 }, ["series"] = { 29633, 29634, 29635, 29636, 29647 }, ["description"] = "Master Stone Fist has trained you in the art of one-on-one combat. Now you learn the art of one-on-many. How does fifty sound? Lower yourself into the Ring of Inner Focus below, then, when you're ready, set off this firework. My assistants will come at you, several at a time. All you need to do is survive.", ["objectivesText"] = "Set off the Monastery Fireworks in the Ring of Inner Focus, then survive the Rumpus for two minutes. Progress: Good luck, <name>.", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 73369, 84251, 84252, 84253, 84254, 84255, 84256, 84257, 84258, 84259, 84260 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 26, ["flags"] = 0 } } },
[29639] = { ["id"] = 29639, ["name"] = "Flying Colors", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29639 }, ["series"] = { 29622, 29623, 29624, 29625 }, ["description"] = "You have passed every test we prepared for you, <name>. It is now time for you to move on to bigger and better things. ...but not before another banquet. The High Elder will be waiting for you at the banquet grounds to celebrate your graduation from our monastery.", ["objectivesText"] = "Report to High Elder Cloudfall at the Tian Monastery in the Jade Forest .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80789, 80793, 80798, 80799, 80800, 80801, 80802, 80803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 27, ["flags"] = 0 } } },
[29646] = { ["id"] = 29646, ["name"] = "Flying Colors", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29646 }, ["series"] = { 29628, 29629, 29630 }, ["description"] = "Well, I've done all that I can with you. Sounds like the others have, too. High Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate your departure. Not that we're happy you're leaving... he just enjoys celebrations.", ["objectivesText"] = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80798, 80799, 80800, 80801, 80802, 80803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 28, ["flags"] = 0 } } },
[29647] = { ["id"] = 29647, ["name"] = "Flying Colors", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29647 }, ["series"] = { 29633, 29634, 29635, 29636, 29637 }, ["description"] = "The Rumpus was your final test. You have mastered the disciplines taught at this monastery. Just as your training began with a banquet, so shall it end. High Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.", ["objectivesText"] = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80798, 80799, 80800, 80801, 80802, 80803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 29, ["flags"] = 0 } } },
[29670] = { ["id"] = 29670, ["name"] = "Maul Gormal", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29670 }, ["description"] = "Thanks to you, there's a small militia of farmers hiding nearby. Hanae said something about giving them \"liquid courage\" which, I'm pretty sure, means they're sauced and ANGRY. The mogu think they can walk all over us - we'll give them a fight that will open their eyes. Follow the trail through the ruins and down to the beach. Find their leader. When you engage him, we'll be there to back you up.", ["objectivesText"] = "Kill Subjugator Gormal in Camp Gormal. Progress: We are ready to fight the mogu leader whenever you are.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80778, 80779, 80780, 80781, 80782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 36, ["flags"] = 0 } } },
[29690] = { ["id"] = 29690, ["name"] = "Into the Mists", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29690 }, ["series"] = { 29611, 29612, 31765, 31766, 31767, 31768, 31769, 31853 }, ["description"] = "<Nazgrim fills his lungs with sea air.> You smell that, <name>? It's the smell of our home, the lands our kind have bled and died to preserve. And listen... you hear that? It's the sound of peace and safety - a haven we've carved, where our enemies fear to tread. Remember these things. You won't experience them again anytime soon. We have ourselves a war to win. Now go get settled, we're shovin' off!", ["objectivesText"] = "Speak to General Nazgrim on Hellscream's Fist.", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 10, ["flags"] = 0 } } },
[29694] = { ["id"] = 29694, ["name"] = "Regroup!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29694 }, ["series"] = { 29765, 29804, 31774 }, ["description"] = "They have an airbase! I have underestimated this Alliance Captain for the last time. So many good warriors lost... There must have been a few survivors who were able to bail during the crash. We need every able-bodied fighter we can get. Find as many survivors as you can in the forest below, and I will investigate the wreckage itself. Rally everyone together at the nearby village for a counter-attack.", ["objectivesText"] = "Rescue Shademaster Kiryn , Rivett Clutchpop , Shokia , and Sergeant Gorrok from Honeydew Glade. Progress: Did you find any survivors?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 73861, 90330, 90332, 90333, 90334, 90335, 90337 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 17, ["flags"] = 0 } } },
[29716] = { ["id"] = 29716, ["name"] = "The Double Hozen Dare", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29716 }, ["series"] = { 29715, 29723 }, ["description"] = "There is a witch in the woods but no one believes me. She turned my friend Shin into jade! We were all so scared we tried to run back but she sicced her big jade monsters on us. A bunch of my friends tried to get away by climbing trees. Can you help me save my friends?", ["objectivesText"] = "Rescue 6 Scared Pandaren cubs . Progress: Where is Shin? I didn't see Shin.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 37, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 51, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 47, ["flags"] = 0 } } },
[29717] = { ["id"] = 29717, ["name"] = "Down Kitty!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29717 }, ["description"] = "I tried to fight one of the jade tigers in the woods but they were too scary. They stare at you and you turn to a jade statue! Honest truth! Chen's sister's friend Ni heard it from Kai's mom. I want to be brave like you though. Can you show me how to beat up those jade tigers?", ["objectivesText"] = "Destroy 8 Jade Guardians . Progress: Wow! You are tough!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 82984, 88704, 88705, 88706, 88707, 88708 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 60, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 56, ["flags"] = 0 } } },
[29723] = { ["id"] = 29723, ["name"] = "The Jade Witch", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29723 }, ["series"] = { 29715, 29716 }, ["description"] = "The Jade Witch must still have Shin. I... I can't do it! I don't want to see the witch. Can you please go talk to her and see if she has Shin? You're an adult, I don't think she would try to turn you into jade.", ["objectivesText"] = "Defeat the Jade Witch.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 82984, 86199 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 59, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 55, ["flags"] = 0 } } },
[29725] = { ["id"] = 29725, ["name"] = "SI:7 Report: Fire From the Sky", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29725 }, ["description"] = "Yeah, we found Amber, she's alive, and all that. That's about where the good news stops though. Let's see if I can pick up where ol' Rell left off...", ["objectivesText"] = "Listen to Sully's report. Progress: I'm not done with the report yet, <name>. Settle down.", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 31, ["flags"] = 0 } } },
[29726] = { ["id"] = 29726, ["name"] = "SI:7 Report: Hostile Natives", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29726 }, ["description"] = "I... I can tell you what happened next! We continued north, into the forest...", ["objectivesText"] = "Listen to Little Lu 's report.", ["rewardXP"] = 111000, ["rewardItems"] = { 82984 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 32, ["flags"] = 0 } } },
[29727] = { ["id"] = 29727, ["name"] = "SI:7 Report: Take No Prisoners", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29727 }, ["description"] = "The final leg of our journey took us west, to a large hozen village. We set up a small camp in the mountains, outside of their line of sight...", ["objectivesText"] = "Listen to Amber Kearnen 's report. Progress: Please, allow me to finish.", ["rewardGold"] = 392000, ["rewardXP"] = 166000, ["rewardItems"] = { 72238, 80768, 80769, 80770, 80771, 80772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 33, ["flags"] = 0 } } },
[29730] = { ["id"] = 29730, ["name"] = "Scouting Report: Hostile Natives", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29730 }, ["description"] = "I bet I know your first question: \"What the ook happened to Sergeant Gorrok?\" Don't worry, don't worry. He's totally alive. Not dead or anything. < Riko shuffles uncomfortably.> Well, we THINK he's alive, but he ALSO might be very, very dead. < Riko looks into your eyes for approval.> Fine! Let me tell you exactly what happened.", ["objectivesText"] = "Listen to Riko 's report.", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 37, ["flags"] = 0 } } },
[29731] = { ["id"] = 29731, ["name"] = "Scouting Report: On the Right Track", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29731 }, ["description"] = "MOST of what Riko said is true. We didn't dare pursue Gorrok - the Horde's numbers here are far too few. Our forces can only sustain so many losses, and frankly, we don't know how powerful that witch really is. Let me pick up where the hozen left off...", ["objectivesText"] = "Listen to Kiryn's report. Progress: If I may continue, please?", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 38, ["flags"] = 0 } } },
[29733] = { ["id"] = 29733, ["name"] = "SI:7 Report: Lost in the Woods", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29733 }, ["series"] = { 30458 }, ["description"] = "<Rell coughs heavily before speaking.> Please, <name>. You need to hear what we've been through. The whole damned Alliance needs to hear what we've been through. There may not be much time left.", ["objectivesText"] = "Listen to Rell's report. Progress: <Rell doesn't look too good. He should probably save his energy.>", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 30, ["flags"] = 0 } } },
[29743] = { ["id"] = 29743, ["name"] = "Monstrosity", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29743 }, ["description"] = "It's plain to see that this statue and the surrounding ruins are of ancient origin. Clearly, this land has a deep history, which means it could not have been born of the cataclysm. And yet these waters have been explored for ages now, with no record of anything here but open sea. Perhaps if you were to sketch the pieces of this broken statue, you might shed light on the continent's origins.", ["objectivesText"] = "Collect sketches of each piece of the ancient statue .", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29745] = { ["id"] = 29745, ["name"] = "The Sprites' Plight", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29745 }, ["series"] = { 29744, 29747, 29748, 29749, 29751, 31482 }, ["description"] = "<Living statues rampage through the woods. For now, they seem content in pummeling the forest sprites into splinters, but if they continue any further the pandaren will have more than just missing jade to worry about.>", ["objectivesText"] = "Slay 10 Stonebound Destroyer the Woods of the Lost and discover their source.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 5, ["flags"] = 0 } } },
[29747] = { ["id"] = 29747, ["name"] = "Break the Cycle", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29747 }, ["series"] = { 29744, 29745, 29748, 29749, 29751, 31482 }, ["description"] = "<Mogu conjurers call forth hapless spirits from beyond, forcing them into statues. It seems that destroying the statues alone will not be enough to break the cycle.>", ["objectivesText"] = "Kill 8 Shan'ze Spiritbinders in the Terrace of Ten Thunders.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 6, ["flags"] = 0 } } },
[29748] = { ["id"] = 29748, ["name"] = "Simulacrumble", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29748 }, ["series"] = { 29744, 29745, 29747, 29749, 29751, 31482 }, ["description"] = "<The shattered remains of an ancient mogu statue. This one looks like it never animated before it was broken. Whatever dark magic the mogu are employing here, it seems to make the brittle statues significantly tougher. Better to destroy them while they are still vacant. A good old-fashioned kick should do the job.>", ["objectivesText"] = "Kick 6 Vacant Destroyers in the Terrace of Ten Thunders.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 7, ["flags"] = 0 } } },
[29749] = { ["id"] = 29749, ["name"] = "An Urgent Plea", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["requiredRaces"] = { 6, 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29749 }, ["series"] = { 29744, 29745, 29747, 29748, 29751, 31482 }, ["description"] = "<Your mind is racked with a howl. Beneath it, a wispy voice is barely audible, as if from far away.> Please... help... heart of the ruins... a ritual... conjuring... ...should not be here... My staff... on the altar... take it. Please hurry.", ["objectivesText"] = "Recover the Staff of Pei-Zhi and interrupt the mogu ritual in the center of the Terrace of Ten Thunders. Progress: Spirit-binding! How can the mogu have been allowed to resume such a disgusting practice?! And now here I am, the product of a half-failed conjuring... <The spirit fumes for a moment, then turns to you.> What century is this?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74258, 84261, 84262, 84263, 84264, 84265, 84266 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 8, ["flags"] = 0 } } },
[29750] = { ["id"] = 29750, ["name"] = "Vessels of the Spirit", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29750 }, ["description"] = "The Spiritclaws are a sect of mogu assassin-priests who, at the height of the mogu empire, were the most elite and most feared of the emperor's troops. All have mastered a deathblow which ensnares the spirit of the enemy, trapping it in a jade bottle for delivery to a Spiritbinder. If you encounter any Spiritclaws further ahead in the ruins, take note: their belts hang with a cursed weight. Relieve them of their burden and bring the bottles back to me.", ["objectivesText"] = "Recover 8 Spirit Bottles from Shan'ze Spiritclaws in the Terrace of Ten Thunders. Progress: To think the mogu have continued training the Spiritclaws for all these years... Did you get the bottles?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74763 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 9, ["flags"] = 0 } } },
[29751] = { ["id"] = 29751, ["name"] = "Ritual Artifacts", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29751 }, ["series"] = { 29744, 29745, 29747, 29748, 29749, 31482 }, ["description"] = "So many spirits held in captivity here... I can feel them everywhere. Even the walls are a cage for the long-dead. <name>, we cannot simply break the sorcery over this place - doing so would release countless agonized souls to wander the earth. They will need a beacon, something to guide them. With your help, I can create a tan-chao: a bridge from this world to the heavens. For this ritual, I'll need a bowl, a candle, and a jade cong . You should be able to find them all within the ruins.", ["objectivesText"] = "Bring Pei-Zhi a Chipped Ritual Bowl , a Pungent Ritual Candle , and a Jade Cong from the Terrace of Ten Thunders. Progress: Have you found the items we need for the ritual? We cannot guide these spirits back without them.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74760, 74761, 74762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 10, ["flags"] = 0 } } },
[29752] = { ["id"] = 29752, ["name"] = "The Wayward Dead", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29752 }, ["description"] = "The process of mass conjuring, as the mogu are doing here, is not without byproduct. Some spirits arrive too distraught or unruly to be harnessed, so they are confined and left to wander until their desperation leaves them more malleable. I suspect the mogu have such a holding area somewhere nearby, likely guarded by spiritclaws. Please, take my staff again and use it to collect these wayward spirits. You needn't fight them - present the staff and they should be drawn in.", ["objectivesText"] = "Use the Staff of Pei-Zhi to absorb 10 Wayward Ancestors in the Terrace of Ten Thunders. Progress: We mustn't forsake the wayward dead.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74771 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 11, ["flags"] = 0 } } },
[29753] = { ["id"] = 29753, ["name"] = "Back to Nature", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29753 }, ["description"] = "I'm afraid I have another favor to ask, <name>. The bottles you recovered contain neither the spirits of mogu ancestors nor recently slain foes; they contain spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to fuel their simulacra. This complicates our task, for I cannot take the beasts with me through the bridge. Take the bottles west to Tideview Thicket and smash them to return the spirits to nature. Some may be blind with rage and will need to be subdued.", ["objectivesText"] = "Throw Spirit Bottles on the ground in Tideview Thicket to release 8 Beast Spirits. Progress: Do not fear for the spirits of the beasts - they will find peace here.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74808 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 12, ["flags"] = 0 } } },
[29754] = { ["id"] = 29754, ["name"] = "To Bridge Earth and Sky", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29754 }, ["series"] = { 29755 }, ["description"] = "We are ready to open the tan-chao and guide all of these spirits back to peace. If I may, I would have your assistance once more. The mogu will surely sense the ritual taking place and will do everything in their power to halt it. I need only a few moments without interference, and once the path is open it will surge too greatly to be closed. If you are willing to help one more time, please accompany me to the ritual site.", ["objectivesText"] = "Protect Pei-Zhi during his ritual at the Terrace of Ten Thunders.", ["rewardGold"] = 98000, ["rewardXP"] = 138000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 14, ["flags"] = 0 } } },
[29755] = { ["id"] = 29755, ["name"] = "Pei-Back", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29755 }, ["series"] = { 29754 }, ["description"] = "<Ancestral spirits stream into the tan-chao, Pei-Zhi 's bridge to freedom. One final chamber lingers in the ruins, just north of the tan-chao. The air above crackles with foul energy. Shan Jitong is already at work.>", ["objectivesText"] = "Confront Shan Jitong and rescue Pei-Zhi at the Seat of the Spirit Waker in the Terrace of Ten Thunders.", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 80695, 80696, 80697, 80698, 80699, 80700, 80701, 80702, 80703 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 15, ["flags"] = 0 } } },
[29756] = { ["id"] = 29756, ["name"] = "A Humble Offering", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29756 }, ["description"] = "I'm almost ready for the ritual, there's just one more thing we need: An offering. Relax, I don't mean a sacrifice. Just a bit of food. There are sure to be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. Please bring some.", ["objectivesText"] = "Gather 10 Tidemist Caps from Tideview Thicket. Progress: Even the dead know hunger.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 75214 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 13, ["flags"] = 0 } } },
[29759] = { ["id"] = 29759, ["name"] = "Kung Din", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29759 }, ["series"] = { 29558, 29559, 29560, 29562 }, ["description"] = "I hope you are capable of this next task, for our lives depend on it. There is only one key that will unlock our chains. Unfortunately, the key hangs around the neck of the hozen's pet tiger, Kung Din. They keep the tiger in the great pit to the north. The only way to retrieve the key will be to kill the beast.", ["objectivesText"] = "Obtain the Slingtail Key by slaying Kung Din. Progress: Did you find him?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79753, 90365, 90366, 90367, 90368, 90369, 90370, 90371, 90372, 90373 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 23, ["flags"] = 0 } } },
[29762] = { ["id"] = 29762, ["name"] = "Family Heirlooms", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29762 }, ["description"] = "We recently lost a fierce battle against the hozen at Moonwater Retreat. We evacuated as many of our people as we could, but still, there were many we could not save. We have no tokens of our lost over which to send our prayers. If someone could go and retrieve heirlooms from the dead bodies, we could properly lay them to rest, and move on. It would mean so much to us if you could do this, <name>.", ["objectivesText"] = "Collect 8 Pearlfin Heirlooms from dead Pearlfin Villagers in Moonwater Retreat. Progress: We still grieve for our fallen brothers.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79811 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 28, ["flags"] = 0 } } },
[29765] = { ["id"] = 29765, ["name"] = "Cryin' My Eyes Out", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29765 }, ["series"] = { 29694, 29804, 31774 }, ["description"] = "I coulda taken out da whole lot of 'em, mon. Shot 'em one by one, den played dead when dey be gettin' close. Fell for it every time, dey did - well almost every time... One of 'em finally got wise. Called my bluff. Before I knew it, dey was usin' my eyes as marbles. Ran off with my goods an' left me here ta die, da savages... Help me, mon. Lemme die wit my dignity intact.", ["objectivesText"] = "Collect Zin'Jun 's belongings from the Hozen Groundpounders. If you lose Zin'Jun , speak to him at the Ascent of Swirling Winds. Progress: You got me goods, mon?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74160, 74161, 74162, 74163 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 10, ["flags"] = 0 } } },
[29804] = { ["id"] = 29804, ["name"] = "Seein' Red", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29804 }, ["series"] = { 29694, 29765, 31774 }, ["description"] = "I was just about ta curl up an' die, mon. Now, dis! Snuff an' me go way back. Oh, da memories... No way I can face Snuff in da afterlife without avengin' his death first, mon! Dese hooligans be led by one named Konk . We gotta sniff him out an' den snuff him out - for Snuff!", ["objectivesText"] = "Kill Konk .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 83671, 83672, 83673, 83674, 83675, 83676, 83677, 83678, 83679, 90295, 90296, 90297, 90298, 90299, 90300, 90301, 90302, 90303 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 11, ["flags"] = 0 } } },
[29815] = { ["id"] = 29815, ["name"] = "Forensic Science", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29815 }, ["series"] = { 29696, 29827 }, ["description"] = "These creatures are everywhere - and very hostile! We'll need to deal with them before any more Alliance show up. This one's taken quite a beating, but I've still made some determinations about its anatomy. With the proper reagents, I'll be able to fashion a poison that should be quite effective against this species. In fact, I'll just need to modify a bit of the poison I have with me. Go and find me some viscous chlorophyll down by the water. Any semi-sentient flora should do.", ["objectivesText"] = "Collect 8 Viscous Chlorophyll . Progress: I hope you were successful. Our survival here may depend on it.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74621 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 18, ["flags"] = 0 } } },
[29821] = { ["id"] = 29821, ["name"] = "Missed Me By... That Much!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29821 }, ["series"] = { 31112 }, ["description"] = "Listen, <pal/toots>. I sent out a coupla supply drones from the gunship, and they've all been lost or crashed. Almost all, that is. One of 'em buzzed right through the camp here and crashed out by them waterfalls. How 'bout you see what you can do about bringin' the contents of that crate back here, hmm? We're all outta drones, but my rocket boots might yet come in handy... or footy, as the case may be. Hah! I just kill me...", ["objectivesText"] = "Find the missing supply crate at Serenity Falls. Provided item:", ["rewardXP"] = 111000, ["rewardItems"] = { 84157 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 20, ["flags"] = 0 } } },
[29822] = { ["id"] = 29822, ["name"] = "Lay of the Land", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29822 }, ["series"] = { 31121, 31132, 31134 }, ["description"] = "Curse these furry pests! Kill one, and two more rise in its place... Nothing has changed, <name>. Orders are orders, no matter how few of us stand and regardless of the odds. I have plans to make and problems to solve. I want you to get out there and learn the lay of the land. Don't return until you have something useful to report. And silence that yammering fool while you're out there! Dismissed!", ["objectivesText"] = "Visit the Shrine of the Sun, the Shrine of the Moon, and Kill Dook Ookem .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 22, ["flags"] = 0 } } },
[29823] = { ["id"] = 29823, ["name"] = "Scouting Report: The Friend of My Enemy", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29823 }, ["description"] = "We weren't only looking for Alliance, you know. We were also looking for those snooked-up, tik-flikklin' jinyu! Well, we found 'em all right...", ["objectivesText"] = "Listen to Riko 's report. Progress: Riko wishes you were a bit more patient, <name>.", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 39, ["flags"] = 0 } } },
[29824] = { ["id"] = 29824, ["name"] = "Scouting Report: Like Jinyu in a Barrel", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29824 }, ["description"] = "With our leader turned to jade, our hozen guide disappeared, and a prisoner of war in tow, there was only one thing that Kiryn and I could do: March into our enemy's territory and deliver some vengeance. Want to know how it went?", ["objectivesText"] = "Listen to Shokia 's report. Progress: I'm not quite done yet, <name>.", ["rewardGold"] = 392000, ["rewardXP"] = 221000, ["rewardItems"] = { 80768, 80769, 80770, 80771, 80772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 40, ["flags"] = 0 } } },
[29827] = { ["id"] = 29827, ["name"] = "Acid Rain", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29827 }, ["series"] = { 29696, 29815 }, ["description"] = "Since you've been gone, more and more of these creatures are approaching our camp. They appear to be amassing for a major assault! We're going to have to take some drastic measures if we hope to see tomorrow. Here, take my poisoned throwing stars and figure out a way to thin out their numbers.", ["objectivesText"] = "Using the Recovered Gyrocopter, kill 25 Hozen Gutrippers and 25 Hozen Nibstabbers . Progress: Well, <name>? Do we live to see another day?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 90304, 90305, 90306, 90307, 90308, 90309, 90310, 90311, 90312 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 19, ["flags"] = 0 } } },
[29865] = { ["id"] = 29865, ["name"] = "The Silkwood Road", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29865 }, ["description"] = "West of here is the Silkwood Road. It has fallen into shadow as the spiders there have turned to a more evil and gluttonous path. I would face these villains myself but someone has to defend the noodle shop from... um... dangers and such. Go, hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some of my epic tales of heroism. I'll also pay you.", ["objectivesText"] = "Defeat 8 Silkwood Stalkers . Progress: The silkwood stalkers are not in balance with nature. Predators are one thing but these creatures kill for pleasure. Harmony must be restored.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80704, 80705, 80706, 80707, 80708, 80709, 80710, 80711, 80712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 53, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 49, ["flags"] = 0 } } },
[29866] = { ["id"] = 29866, ["name"] = "The Threads that Stick", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29866 }, ["description"] = "Ah, welcome traveler. I have need of your services! Syra Goldendraft was looking for some silk. Personally I hate silk as it always gets stuck in my fur. I really want to impress her though. If you bring me some silk from the Silkwood to the west of here I will gladly pay you for your help.", ["objectivesText"] = "Gather 7 Pristine Silk Strands . Progress: Did you find the Silkwood?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 75023 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 52, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 48, ["flags"] = 0 } } },
[29872] = { ["id"] = 29872, ["name"] = "Lin Tenderpaw", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29872 }, ["series"] = { 29981 }, ["description"] = "Lin is more talented than she thinks she is. Strong of fist but weak of spirit. With more confidence, she could be better than all of us. Perhaps she will find the surety she needs on her trip into the west. She's probably on her way to Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the Valley.", ["objectivesText"] = "Find Lin Tenderpaw .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29877] = { ["id"] = 29877, ["name"] = "A Poor Grasp of the Basics", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29877 }, ["description"] = "Virmen - they no just eat our food. They trying to start farms of their own. The problem is... well, they ookin' dumb. You no believe Muno? Last night, they break into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows planted in ground. They was WATERING them. They was trying to GROW WHEELBARROWS. Please, while you out there, unbury our stuff.", ["objectivesText"] = "Unearth 7 pieces of farm equipment. Progress: Man, those virmen is dumb.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 2, ["flags"] = 0 } } },
[29879] = { ["id"] = 29879, ["name"] = "Swallowed Whole", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29879 }, ["series"] = { 29935, 29936, 29941, 31167 }, ["description"] = "Now, back to your dilemma. I believe you can help your people build relations with our hozen, as my people have. The trail behind me will lead you to a body of water the hozen use to gather the fish that feeds them. Around this time every year, fearsome beasts call those waters home and many hungry hozen are lost to them. If you were to rescue some of the victims and gather some fish, perhaps you will be regarded more favorably.", ["objectivesText"] = "Free 5 hozen from the Engorged Crocolisks , and gather 5 Speckled Trout from Lake Kittitata. Progress: Wikket got slickies... for me!?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 75202, 86216 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 28, ["flags"] = 0 } } },
[29881] = { ["id"] = 29881, ["name"] = "The Perfect Color", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29881 }, ["description"] = "As you have seen, this grove is abundant with beautiful pink petals. As each petal ages, the tone deepens and fades. If you would be so kind, I am in need of a few petals that have freshly fallen. Only the ones that have just fallen will have precisely the right color I am after. From it I can forge an ink that will be breathtaking. Can you help me?", ["objectivesText"] = "Gather 8 Freshly Fallen Petals . Progress: There is only a small window of time after each petal falls that it may be used to achieve the perfect hue.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 75219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 57, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 53, ["flags"] = 0 } } },
[29882] = { ["id"] = 29882, ["name"] = "Quill of Stingers", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29882 }, ["description"] = "To achieve perfect paint strokes, one must have the right tools. My own have fallen into disrepair, their bristles becoming as unmanageable as hozu hair. Have you seen the wasps throughout the Arboretum? Their stingers can be fashioned into quills that provide just the right level of sharpness in each line. Could you gather some for me please?", ["objectivesText"] = "Gather 6 Wasp Stingers from Orchard Wasps. Progress: Have you been able to acquire some stingers? I would normally ask a monk for help with this but they all seem to be elsewhere at the moment.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 75221, 80713, 80714, 80715, 80716, 80717, 80718, 80719, 80720, 80721 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 56, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 52, ["flags"] = 0 } } },
[29883] = { ["id"] = 29883, ["name"] = "The Pearlfin Situation", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29883 }, ["description"] = "I've been thinking. We are cut off from support and a long way from home. Although these Pearlfin jinyu mistrust our presence, they do not appear to be hostile. If we could convince them that we are their friends, an alliance between our races could prove extremely valuable. <name>, you must go speak to the jinyu around the village. Convince their leaders that we are not to be feared, and that we only wish for peace.", ["objectivesText"] = "Speak to Elder Lusshan , Pearlkeeper Fujin , Instructor Sharpfin , and Ot-Temmdo at Pearlfin Village. Progress: If we can win over the jinyu, they may allow us to stay.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 25, ["flags"] = 0 } } },
[29885] = { ["id"] = 29885, ["name"] = "Road Rations", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29885 }, ["description"] = "We do not have time to wait around for the Admiral to recover. Sully and I are planning to search for Anduin to the north, but we'll need supplies for our journey. The lake here is teeming with wildlife, which we have received permission to hunt. Go and gather some supplies while Sully and I finalize our preparations.", ["objectivesText"] = "Collect 6 Tortoise Flanks . Progress: Time is short. Each hour we delay, the White Pawn may move further away. Where are the supplies I asked for?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 73368, 80240, 83097 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 26, ["flags"] = 0 } } },
[29887] = { ["id"] = 29887, ["name"] = "The Elder's Instruments", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29887 }, ["description"] = "Oh dear, oh dear... The Elder mustn't find out! I must have left the Elder's ceremonial instruments behind during the escape. But... Moonwater Retreat is crawling with hozen by now! What sort of Pearlkeeper am I, to have lost them so carelessly? <The old jinyu buries his face into his hands.> Stranger, could you find it in your heart to help me?", ["objectivesText"] = "Collect the Waterspeaker's Staff , Ceremonial Robe, Jade Crown , and Rosewood Beads from Slingtail Stickypaws. Progress: The Elder is a Waterspeaker. He speaks to the waters, and they answer.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79807, 79808, 79809, 79810 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 27, ["flags"] = 0 } } },
[29888] = { ["id"] = 29888, ["name"] = "Seek Out the Lorewalker", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29888 }, ["series"] = { 29889, 31130 }, ["description"] = "I see that you and your people are desperate to find your Prince Anduin. I know someone who may be able to help you, a pandaren Lorewalker who knows this land better than anyone. I cannot guarantee what kind of reception you will receive, but he will almost certainly be as curious about you as you are of him! The Lorewalker lives in the forest to the southwest. Tell him that the Pearlfin have sent you.", ["objectivesText"] = "Search for Lorewalker Cho at the Dreamer's Pavilion in the Jade Forest .", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 38, ["flags"] = 0 } } },
[29889] = { ["id"] = 29889, ["name"] = "Borrowed Brew", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29889 }, ["series"] = { 29888, 31130 }, ["description"] = "A delicious smell wafts out from the bottle on the table. A little taste couldn't hurt, right?", ["objectivesText"] = "Taste the mouthwatering brew .", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 39, ["flags"] = 0 } } },
[29890] = { ["id"] = 29890, ["name"] = "Finding Your Center", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29890 }, ["description"] = "The dream brew is complete! This time, when you drink it, you must embrace the visions you see from a state of inner focus. Follow me to my pagoda, and I will teach you how to achieve the inner calm that we pandaren value so much. Your troubled mind will present you with many distractions, but just remember to stay centered!", ["objectivesText"] = "Meditate with Lorewalker Cho at the pagoda at the Dreamer's Pavilion in the Jade Forest .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80763, 80764, 80765, 80766, 80767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 44, ["flags"] = 0 } } },
[29891] = { ["id"] = 29891, ["name"] = "Potency", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29891 }, ["description"] = "To make the Dream Brew, we will need several ingredients. First, to improve its strength, I will need an ingredient from a fearsome creature, the legendary Mist Horror. It is said that this creature only appears where the fog is deepest. North and east of here, you will find smaller Mist Creepers roaming the swamps. Kill these creatures until the Mist Horror appears, and then bring me its heart.", ["objectivesText"] = "Kill Mist Creepers until a Mist Horror appears, then collect a Mist Horror Heart . Progress: The mists seem to have a mind of their own, do they not?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76129 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 41, ["flags"] = 0 } } },
[29892] = { ["id"] = 29892, ["name"] = "Body", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29892 }, ["description"] = "A brew's body is an important and often overlooked factor. To create the perfect consistency, I will need pristine eyes from the Bog Crocolisks to the east. Take care. The creatures are quite vicious.", ["objectivesText"] = "Collect 5 Pristine Crocolisk Eyes from Bog Crocolisks. Progress: Watch your step in the swamp, my new friend.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 15689, 35818, 35820, 35821, 35822, 74577, 74578, 74579, 76107 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 42, ["flags"] = 0 } } },
[29893] = { ["id"] = 29893, ["name"] = "Hue", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29893 }, ["description"] = "The most distinguishing feature of the Dream Brew is its iridescent, dream-like color. To the east, you will find Glittering Amberflies. I will need their wings to create the final luminescent color of the brew. Take this knife and use it to collect 8 wings.", ["objectivesText"] = "Collect 8 Amberfly Wings . Progress: Have you collected all the ingredients? It is almost time to make the Dream Brew.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76115, 76128 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 43, ["flags"] = 0 } } },
[29894] = { ["id"] = 29894, ["name"] = "Spirits of the Water", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29894 }, ["description"] = "Our war against the hozen rages without end, and the future of our tribe is uncertain. This is why our waterspeaker has decided to seek wisdom from the waters. Elder Lusshan is waiting. Please deliver the instruments so that they may begin.", ["objectivesText"] = "Speak to Elder Lusshan and witness the waterspeaking ceremony. Progress: <The Elder's eyes are glazed over. His vision is cast inward, toward the wisdom he has gained.>", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 548, ["name"] = "The Jade Forest, The Waterspeaking Ceremony", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 29, ["flags"] = 0 } } },
[29898] = { ["id"] = 29898, ["name"] = "Sacred Waters", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29898 }, ["description"] = "I appreciate you coming all this way to save me, but Ren is gravely injured. The old pandaren had no reason to help me, yet still he risked his life to save my own. Before the fever set in, he mentioned that there are healing waters in the cave just down the hill. It is dangerous, but I will do anything to help my friend. Will you help me retrieve the waters?", ["objectivesText"] = "Collect healing waters from the four Sacred Bowls in the Den of Sorrow. Progress: Perhaps I could bring some of these healing waters back to Stormwind with me.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 45, ["flags"] = 0 } } },
[29899] = { ["id"] = 29899, ["name"] = "Rest in Peace", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29899 }, ["description"] = "The spirits... the cavedwellers... they howl in agony... Trapped... in this world... cannot move... to the next. I... will go mad... listening... to their cries... Please...go...put them to rest.", ["objectivesText"] = "Kill 6 Tortured Spirits .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 46, ["flags"] = 0 } } },
[29900] = { ["id"] = 29900, ["name"] = "An Ancient Legend", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29900 }, ["description"] = "My father has dedicated his life to studying the Vale of Eternal Blossoms. The Vale is a mythical place, sealed after the Pandaren revolution twelve thousand years ago. We know so little about it! My father followed a trail of clues to the cave down the hill, seeking a very old poem known as the Song of the Vale , but he is in no condition to retrieve it. It is guarded by some sort of ancestor spirit. If you are heading that way anyway, would you mind bringing it back to him?", ["objectivesText"] = "Retrieve the Song of the Vale from the Den of Sorrow. Progress: Did you... find the scroll?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79875, 80749, 80750, 80751, 80752, 80753, 80754, 80755, 80756, 80757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 47, ["flags"] = 0 } } },
[29901] = { ["id"] = 29901, ["name"] = "Anduin's Decision", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29901 }, ["series"] = { 29903, 29904, 29905 }, ["description"] = "You have done all you can for the Prince's friends. You completed your mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 agents will be eager to have the boy safe in their custody. It is time to return home.", ["objectivesText"] = "Tell Anduin that it is time to return home. Progress: What? You lost the boy?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 48, ["flags"] = 0 } } },
[29903] = { ["id"] = 29903, ["name"] = "A Perfect Match", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29903 }, ["series"] = { 29901, 29904, 29905 }, ["description"] = "Elder Lusshan and I agree that the best path forward will be to work together. We will share with the Pearlfin our superior military knowledge and weaponry. In return, they will be a powerful ally should we again encounter the Horde. Take this crate of equipment and weapons. I need you to go around the village and equip the jinyu with weapons befitting their skills.", ["objectivesText"] = "Speak to Pearlfin Aqualytes and arm them with the proper equipment. Progress: The jinyu are skilled in different ways. It is up to us to find their strengths.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 34, ["flags"] = 0 } } },
[29904] = { ["id"] = 29904, ["name"] = "Bigger Fish to Fry", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29904 }, ["series"] = { 29901, 29903, 29905 }, ["description"] = "I've prepared a team of bright young Pearlfin trainees who need field experience. Take them northeast, into the Bamboo Wilds, and kill any wildlife that you find. Don't bring them back until they're fit for battle.", ["objectivesText"] = "Train the Pearlfin Adepts by killing 24 wildlife in the Bamboo Wilds. Progress: How are those trainees looking?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 35, ["flags"] = 0 } } },
[29905] = { ["id"] = 29905, ["name"] = "Let Them Burn", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29905 }, ["series"] = { 29901, 29903, 29904 }, ["description"] = "Advance scouts report that the hozen at the Slingtail Pits are amassing with reinforcements from their tribes to the north. Our forces are gathered for battle on the ridge to the northwest. They are just waiting for you. Now is the time to show them what we are made of. Now is the time to destroy them indefinitely.", ["objectivesText"] = "Kill 15 Grookin Reinforcements or Slingtail Recruits.", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 84105 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 36, ["flags"] = 0 } } },
[29906] = { ["id"] = 29906, ["name"] = "Carp Diem", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29906 }, ["description"] = "Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut , is the shrewd mastermind behind their attacks. He is organizing their movements at the great pit at the hozen camp to the northwest. Strike now and show him no mercy, <name>, for he will do the same.", ["objectivesText"] = "Kill Chief Gukgut .", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 80788, 80789, 80790, 80791, 80792, 80793, 80794, 80795, 80796, 80797 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 37, ["flags"] = 0 } } },
[29907] = { ["id"] = 29907, ["name"] = "Chen and Li Li", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29907 }, ["series"] = { 29908, 29909, 29911, 29912, 29940, 32018, 32019 }, ["description"] = "My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going. That farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li? <race>? Would you like to share the road with us?", ["objectivesText"] = "Follow Chen Stormstout to Pang's Stead. Progress: Yes?", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 89551, 89553, 89564, 89565 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 0, ["flags"] = 0 } } },
[29908] = { ["id"] = 29908, ["name"] = "A Seemingly Endless Nuisance", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 433, ["storyline"] = { 29908 }, ["series"] = { 29907, 29909, 29911, 29912, 29940, 32018, 32019 }, ["description"] = "I apologize for the state of things around here. The virmen - those rabbity creatures, down the hill - have been pushing further and further into my family's farm, and our crops - which are normally bigger, and more delicious, by the way - have been suffering because of it. I'm no soldier... but you might be! Would you mind pushing some of these virmen off of our land?", ["objectivesText"] = "Slay 8 Snagtooth Spotters, Tool-Grabbers, or Troublemakers. Then slay 18 Snagtooth Pesterlings .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81769, 81770, 81771, 81772, 81773, 81774, 81775, 81776, 81777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 433, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 1, ["flags"] = 0 } } },
[29909] = { ["id"] = 29909, ["name"] = "Low Turnip Turnout", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29909 }, ["series"] = { 29907, 29908, 29911, 29912, 29940, 32018, 32019 }, ["description"] = "Your help here is appreciated, <name>. I'd like to give you another job, if you're interested. My son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day. Would you go down there and see what's going on?", ["objectivesText"] = "Find Ang Thunderfoot .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 3, ["flags"] = 0 } } },
[29910] = { ["id"] = 29910, ["name"] = "Rampaging Rodents", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29910 }, ["description"] = "I went off this morning to watch my papa fight the virmen. When I came back, the farm was full of marmots! I don't want to kill them, but we need to get rid of them. Hey, I know! We can close the holes! Fill in their holes with dirt, so they can't come out in our farm anymore.", ["objectivesText"] = "Move 6 Plump Marmots off of Thunderfoot Farm, and fill in 6 Marmot Holes . Progress: The marmots won't be happy when you try to fill in their holes.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 43004, 88370 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 5, ["flags"] = 0 } } },
[29911] = { ["id"] = 29911, ["name"] = "Practically Perfect Produce", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29911 }, ["series"] = { 29907, 29908, 29909, 29912, 29940, 32018, 32019 }, ["description"] = "Here, <name>. My father will be wanting this. Thank you, again, for helping with the virmen.", ["objectivesText"] = "Bring the Crate of Fresh Crops to Pang Thunderfoot . Progress: Do I smell turnips?", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 76110 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 6, ["flags"] = 0 } } },
[29912] = { ["id"] = 29912, ["name"] = "The Fabulous Miss Fanny", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29912 }, ["series"] = { 29907, 29908, 29909, 29911, 29940, 32018, 32019 }, ["description"] = "Most of these vegetables will be sold, but I'd like to keep some for my family. Specifically, my nephew Liang needs some to feed to his pigs. Unfortunately, the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to have to ask Miss Fanny to help us out. Bring some of the food we've gathered to Miss Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to Liang's ranch.", ["objectivesText"] = "Bring Ang's Giant Pink Turnip , Ang's Summer Watermelon , and Pang's Extra-Spicy Tofu to Miss Fanny, and ask her to deliver them. The food must land on Thunderfoot Ranch. Progress: Not now, neighbor. I need to scrounge up some food for these pigs.", ["rewardGold"] = 77000, ["rewardXP"] = 97000, ["rewardItems"] = { 75256, 75258, 75259 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 7, ["flags"] = 0 } } },
[29913] = { ["id"] = 29913, ["name"] = "The Meat They'll Eat", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29913 }, ["series"] = { 29914, 29915 }, ["description"] = "I told you earlier, my pigs are picky eaters. They need to eat meat to grow strong, but they don't like mutton, they don't like yak, and I'm not about to feed them any pig meat. They do, however, eat meat off of the mushan beasts, and they're also quite partial to turtle. Both creatures can be found in abundance to the west. My skills as a hunter are admittedly quite weak. Can you help out a young rancher and his pigs?", ["objectivesText"] = "Obtain 4 Mushan Shoulder Steaks and 80 Turtle Meat Scraps . Progress: It hurts my ears to hear their hungry squeals. Once you've been a pig rancher for a while, you can distinguish hungry squeals from regular squeals.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 75275, 75276, 88010, 88011, 88012, 88013, 88014, 88015, 88016, 88017, 88018 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 8, ["flags"] = 0 } } },
[29914] = { ["id"] = 29914, ["name"] = "Back to the Sty", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29914 }, ["series"] = { 29913, 29915 }, ["description"] = "I try to keep an eye on my stock, but every once in a while some of them sneak away. With all the confusion these virmen are causing, I may have let my guard down for a few moments, and some of my pigs escaped. Care to look for them? I'd start by looking down the hill, to the west.", ["objectivesText"] = "Find Jian , Ling , and Smelly . Progress: Have you found them? There should be three missing, I think.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 75271, 75272, 75273 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 9, ["flags"] = 0 } } },
[29915] = { ["id"] = 29915, ["name"] = "A Neighbor's Duty", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29915 }, ["series"] = { 29913, 29914 }, ["description"] = "I'm not the only one having trouble with his stock, it seems. One of Francis' sheep has wandered over to my ranch, for the third time this week. I'm beginning to think he needs help tending to his flock. You should check up on him, neighbor. And bring this poor little thing with you.", ["objectivesText"] = "Bring the Wayward Lamb to Francis the Shepherd Boy . Progress: Oh... you have one of my... my lambs?", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 76100 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 10, ["flags"] = 0 } } },
[29916] = { ["id"] = 29916, ["name"] = "Piercing Talons and Slavering Jaws", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29916 }, ["description"] = "First the hawks came. You've probably seen some of them circling up above. The wolves came shortly after. I think they smelled my weakness. I'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts. Can... can you help, <sir/ma'am>?", ["objectivesText"] = "Kill 5 Thieving Plainshawks and 6 Thieving Wolves . Progress: I wish I were brave enough to fight them, but...", ["rewardGold"] = 77000, ["rewardXP"] = 97000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 11, ["flags"] = 0 } } },
[29917] = { ["id"] = 29917, ["name"] = "Lupello", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29917 }, ["description"] = "I've been thinking... the wolves might stop attacking if we kill their pack leader. We call him Lupello , and he patrols the opposite riverbank. <Francis' concentration is broken by another attack. Perhaps you should go deal with Lupello yourself.>", ["objectivesText"] = "Slay Lupello . Progress: What will Master Shang say when he finds out?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 12, ["flags"] = 0 } } },
[29918] = { ["id"] = 29918, ["name"] = "A Lesson in Bravery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29918 }, ["description"] = "<Master Shang speaks to his shepherd boy.> Francis, you need to show bravery! You have everything it takes to make a great shepherd, except the courage to face your fears! <He looks over to you.> You, stranger. You helped the rest of my family. Francis is like a second son to me. Show my apprentice what it means to lack fear. Use this rope to lasso and defeat one of the great white hawks above us. <Shang points to the sky, looks at Francis, and leaves.>", ["objectivesText"] = "Use the Rancher's Lariat to lasso and defeat a Great White Plainshawk . Progress: You lack fear. I can sense it in your heart.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 75208, 81824, 81825, 81826, 81827, 81828 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 13, ["flags"] = 0 } } },
[29919] = { ["id"] = 29919, ["name"] = "Great Minds Drink Alike", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29919 }, ["description"] = "Hello again, <name>. What is this, the fourth time we've run into one another already? Say... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?", ["objectivesText"] = "Escort Chen Stormstout and Li Li to the brewery in the southwest.", ["rewardGold"] = 51000, ["rewardXP"] = 64000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 14, ["flags"] = 0 } } },
[29920] = { ["id"] = 29920, ["name"] = "Getting Permission", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29920 }, ["series"] = { 29993, 29995 }, ["description"] = "My love, Lo, tried to get permission to marry me from the pandriarchs. Though they have passed beyond, their favor would carry a lot of weight. Thing is, they are spirits, and none of the gifts or tributes we brought impress them. To win their favor they claimed that either Lo or a champion must defeat them in single combat. Lo is a good man, but not a fighter. Would you be our champion?", ["objectivesText"] = "Challenge and defeat Pandriarch Goldendraft , Pandriarch Windfur , and Pandriarch Bramblestaff . Progress: Each of the pandriarchs earned their reputation in life and retained them afterward. I can't even imagine how you will defeat them.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80758, 80759, 80760, 80761, 80762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 58, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 54, ["flags"] = 0 } } },
[29922] = { ["id"] = 29922, ["name"] = "In Search of Wisdom", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29922 }, ["description"] = "Lorewalker Cho came by and asked for you while you were gone. He needs your assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did not say. Speak to Kitemaster Ut-Nam . He would be happy to send you there.", ["objectivesText"] = "Speak to Kitemaster Ut-Nam and get a ride to Dawn's Blossom.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 49, ["flags"] = 0 } } },
[29925] = { ["id"] = 29925, ["name"] = "All We Can Spare", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29925 }, ["description"] = "Alright, I called in every favor I could. Here's what we got. Cho must be on to something big! Lemme know when you're ready to go see him - I got a ride all prepared for ya.", ["objectivesText"] = "Deliver the Scavenged Jade to Lorewalker Cho at Emperor's Omen. Speak with Toya in Dawn's Blossom for a ride. Progress: Ah, hello again, <name>! You received my message, then?", ["rewardGold"] = 24500, ["rewardXP"] = 28000, ["rewardItems"] = { 76483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 61, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 57, ["flags"] = 0 } } },
[29926] = { ["id"] = 29926, ["name"] = "Calamity Jade", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29926 }, ["description"] = "You ever seen a shale spider, <class>? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\" A few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys. You get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.", ["objectivesText"] = "Slay 12 Greenstone Nibblers and 6 Greenstone Gorgers at the Greenstone Quarry.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 63, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 59, ["flags"] = 0 } } },
[29927] = { ["id"] = 29927, ["name"] = "Mann's Man", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29927 }, ["series"] = { 29929, 29930 }, ["description"] = "<For once, the foreman lowers her voice.> Look, this ain't easy... I got another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice as stupid. Says the boys need him around for \"moral support.\" <Mann sneers.> What about my moral support?! What am I gonna do if that idiot dies?! Please... keep an eye out for him. Tell him to come home. <Her eyes soften before she turns away.>", ["objectivesText"] = "Locate Hao Mann at the Greenstone Quarry.", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 64, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 60, ["flags"] = 0 } } },
[29928] = { ["id"] = 29928, ["name"] = "I Have No Jade And I Must Scream", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29928 }, ["description"] = "Our whole jade supply line has fallen apart. The mines are a death trap, morale is historically low, and - as if that weren't bad enough - the mason's quarter has been overrun by wood sprites! Now even the plants are out to ruin me! You need jade so badly, you can follow the road southwest to the mason's quarter and get it from those glorified chopsticks yourself.", ["objectivesText"] = "Recover 15 Chunks of Jade from Puckish Sprites around the Greenstone Mason's Quarter. Progress: <Mann looks at you expectantly, eyes wide and nostrils flared.>", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 62, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 58, ["flags"] = 0 } } },
[29929] = { ["id"] = 29929, ["name"] = "Trapped!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29929 }, ["series"] = { 29927, 29930 }, ["description"] = "<Hao struggles against the rubble with all his might.> HNNNGHHH!! Let me guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a little--HNNGGHHH!!--cave-in to keep ol' Hao down. Some o' the boys, on the other hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine. Really.", ["objectivesText"] = "Free 8 Greenstone Miners in the Greenstone Quarry.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 65, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 61, ["flags"] = 0 } } },
[29930] = { ["id"] = 29930, ["name"] = "What's Mined Is Yours", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29930 }, ["series"] = { 29927, 29929 }, ["description"] = "Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time. I should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her. Now, I ain't never met no <race> t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.", ["objectivesText"] = "Board the jade cart and ride with Hao back to Emperor's Omen. Progress: Well? Where's Hao? Don't tell me you couldn't find him...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80783, 80784, 80785, 80786, 80787 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 66, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 62, ["flags"] = 0 } } },
[29931] = { ["id"] = 29931, ["name"] = "The Serpent's Heart", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29931 }, ["series"] = { 29932, 29997, 30011, 30495 }, ["description"] = "You've done great here, kid. Thanks to you, we have quite a bit of extra jade, and I know just the someone who could use it. My friend Foreman Raike is running the great statue project at the Serpent's Heart. Bring a shipment of extra jade to him, and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.", ["objectivesText"] = "Speak to Foreman Raike at the Serpent's Heart in the Jade Forest .", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 67, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 63, ["flags"] = 0 } } },
[29932] = { ["id"] = 29932, ["name"] = "The Temple of the Jade Serpent", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29932 }, ["series"] = { 29931, 29997, 30011, 30495 }, ["description"] = "You've done us a huge favor here, traveler. Now that we have enough jade to complete the statue, we should send word of our progress to Yu'Lon, the Jade Serpent. When you arrive, speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent. If you wish to speed your journey, speak to Kitemaster Shoku. I'm sure he can spare an extra kite for you.", ["objectivesText"] = "Speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent. Speak to Kitemaster Shoku for a kite ride to the temple. Progress: Yes?", ["rewardItems"] = { 74030 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 69, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 65, ["flags"] = 0 } } },
[29935] = { ["id"] = 29935, ["name"] = "Orders are Orders", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29935 }, ["series"] = { 29879, 29936, 29941, 31167 }, ["description"] = "Hmm, maybe wikket not so bad after all! Other baldskins not nice to hozen. Hozen take this from bad wikkets! All wikket loot goes to Kah Kah - Chief's orders! Here, wikket. You take it. Kah Kah will want to meet new hozen friend. His camp south at Grookin Hill.", ["objectivesText"] = "Bring the Alliance Orders to Chief Kah Kah at Grookin. Provided item:", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["rewardItems"] = { 85507, 88019, 88020, 88021, 88022, 88023, 88024, 88025, 88026, 88027, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 29, ["flags"] = 0 } } },
[29936] = { ["id"] = 29936, ["name"] = "Instant Messaging", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29936 }, ["series"] = { 29879, 29935, 29941, 31167 }, ["description"] = "Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen. Dook Ookem wanted to be chief, but good wikket grook him good - big gift to Kah Kah. Hozen has gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.", ["objectivesText"] = "Use the Hellscream's Fist Signal Flare near Chief Kah Kah at Grookin Hill.", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["rewardItems"] = { 76305, 80763, 80764, 80765, 80766, 80767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 31, ["flags"] = 0 } } },
[29937] = { ["id"] = 29937, ["name"] = "Furious Fowl", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29937 }, ["series"] = { 29939 }, ["description"] = "So these guys like fish, huh? Well how about we finish what you started and make them LOVE us? I've still got some explosive powder from the wreck, just need something to attract the fish. Guts is sure to do the trick - never fails. I saw some birds flyin' around south of town. Well? Whatcha waitin' for?", ["objectivesText"] = "Collect 6 Fistfuls of Bird Guts from Bloodtalons in Dookin' Grounds. Progress: You didn't touch that stuff with your hands did ya?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76225 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 33, ["flags"] = 0 } } },
[29939] = { ["id"] = 29939, ["name"] = "Boom Bait", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29939 }, ["series"] = { 29937 }, ["description"] = "There. I've plastered your bird guts over my explosives. I call 'em Gut Bombs , patent pending. Since you made friends with these fellas, how about you do the honors? Just light the fuse and throw 'em down by the shoreline!", ["objectivesText"] = "Use the Gut Bombs at Murky Bank and collect 5 Exploded Slickies . Progress: I have yet to face a crisis that couldn't be fixed with dynamite.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76260, 76262 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 35, ["flags"] = 0 } } },
[29940] = { ["id"] = 29940, ["name"] = "Taking a Crop", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29940 }, ["series"] = { 29907, 29908, 29909, 29911, 29912, 32018, 32019 }, ["description"] = "Alright, fine. I DON'T have everything under control here. I spent all morning fighting off virmen. I managed to clear them off of my property, but they got away with some of my crops. They took them down to the river, to the south. I have no idea what they're doing with them, but it's probably not eating them. If my father wants his delivery now, I'm going to need some help getting those crops back. Could you help me out?", ["objectivesText"] = "Obtain 5 Stolen Turnips and 5 Stolen Watermelons . Progress: If my father wants his vegetables, I'm going to need your help.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76297, 76298, 81796, 81797, 81798, 81799, 81800, 81801, 81802, 81803, 81804, 88371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 555, ["name"] = "Valley of the Four Winds, Thunderfoot Fields", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 4, ["flags"] = 0 } } },
[29941] = { ["id"] = 29941, ["name"] = "Beyond the Horizon", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29941 }, ["series"] = { 29879, 29935, 29936, 31167 }, ["description"] = "I recognize all you've managed to do here, <class>. My report to the Warchief will include an account of your deeds. But there's no time to rest! This land must be charted and prepared for Horde settlement. I've already selected an away team to do just that. Find them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide. You'll be staying here with me. We have preparations to make.", ["objectivesText"] = "Speak to Shokia , Sergeant Gorrok , Shademaster Kiryn , and Chief Kah Kah Progress: Has the away team been dispatched, <name>?", ["rewardGold"] = 74000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 32, ["flags"] = 0 } } },
[29942] = { ["id"] = 29942, ["name"] = "Silly Wikket, Slickies are for Hozen", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29942 }, ["description"] = "You think hozen crazy, wikket? Wait til you see hozen with no slickies! Not enough slickies for hozen and wikkets. Snappers! Hozen hate them ookin' snappers. Wikkets can eat all the snappers! < Eekle Eekle points to the south.>", ["objectivesText"] = "Collect 4 Snapper Steaks from the Murky Bank Progress: Wikket grook all them ookin' snappers?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76420 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 36, ["flags"] = 0 } } },
[29943] = { ["id"] = 29943, ["name"] = "Guerrillas in our Midst", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29943 }, ["series"] = { 29966, 30015 }, ["description"] = "Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, <name>. But there's another side of this coin. We'd be naive to think the child was left alone. Any Alliance scum within sight of this land must be searching desperately for their precious princeling. You and I are going to scour the area and root out his would-be rescuers.", ["objectivesText"] = "Kill 8 Alliance Infiltrators near the Scenic Overlook. Progress: I love the sound of screaming Alliance in the morning.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80749, 80750, 80751, 80752, 80753, 80754, 80755, 80756, 80757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 43, ["flags"] = 0 } } },
[29944] = { ["id"] = 29944, ["name"] = "Leaders Among Breeders", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29944 }, ["series"] = { 29946, 29949, 29950 }, ["description"] = "Before any kegs are tapped, we have work to do. These virmen are no different than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits they resemble. Sure, we could kill every last virmen we find, but what's the point in needless bloodshed? Let's just take out their alphas, and they'll slow down with their... reproduction.", ["objectivesText"] = "Slay Aiyu the Skillet , Jinanya the Clawblade , and Frenzyhop . Progress: The virmen here have strange habits. Stranger names.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88375 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 17, ["flags"] = 0 } } },
[29945] = { ["id"] = 29945, ["name"] = "Yellow and Red Make Orange", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29945 }, ["series"] = { 29947 }, ["description"] = "Uncle Chen says we're going to help this guy out with his virmen problem. Fine by me! I LOVE messing with virmen. Here's the plan: we're going to paint some turnips orange, and then we'll try to convince the virmen that they're carrots. This can only end in comedy. I'll gather turnips. You find something that we can use to make edible orange paint.", ["objectivesText"] = "Obtain 10 Meadow Marigolds and 40 Vials of Animal Blood . Progress: You have the stuff ready for the paint? I went ahead and gathered some turnips.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76334, 76335, 88377 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 15, ["flags"] = 0 } } },
[29946] = { ["id"] = 29946, ["name"] = "The Warren-Mother", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29946 }, ["series"] = { 29944, 29949, 29950 }, ["description"] = "We've dealt with the alpha males. Now, the alpha female. Virmen aren't terribly selective when it comes to breeding, but most broods will still have a dominant mother figure. She's usually bigger, meaner, and tougher than anyone else in the brood. You know, I wouldn't mind testing my skills against a warren-mother. Mind if I fight alongside you?", ["objectivesText"] = "Defeat Chufa , the Twitchheel Warren-Mother. Progress: Ready when you are, <name>. You go ahead. I'll meet you down there.", ["rewardGold"] = 102000, ["rewardXP"] = 161000, ["rewardItems"] = { 76337, 76370 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 18, ["flags"] = 0 } } },
[29947] = { ["id"] = 29947, ["name"] = "Crouching Carrot, Hidden Turnip", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29947 }, ["series"] = { 29945 }, ["description"] = "Uncle Chen's still got his eye on me, which means I won't be wandering off any time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into the Twisted Warren and deliver them for me. It should be pretty simple. Just toss the vegetables in front of virmen, then watch their reaction when they find out it's really a turnip!", ["objectivesText"] = "Toss Orange-Colored Turnips in front of 12 Twitchheel Hoarders. Progress: Go, torment those virmen, <name>!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76337, 76370, 88376, 88377 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 16, ["flags"] = 0 } } },
[29948] = { ["id"] = 29948, ["name"] = "Thieves to the Core", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29948 }, ["description"] = "You and that Chen fellow are good people, helpin' out with the virmen like you are. I don't like to ask for favors, but I ain't gonna turn 'em away, either. While you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last night. Probably usin' em for pillows, knowin' how they are.", ["objectivesText"] = "Recover 6 Stolen Sacks of Hops from the Twisted Warren. Progress: I done told those virmen to stay off my land.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76337, 76370 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 19, ["flags"] = 0 } } },
[29949] = { ["id"] = 29949, ["name"] = "Legacy", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29949 }, ["series"] = { 29944, 29946, 29950 }, ["description"] = "I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.", ["objectivesText"] = "Have a drink with Chen, Li Li , and Mudmug.", ["rewardGold"] = 10200, ["rewardXP"] = 32000, ["rewardItems"] = { 16025, 29329, 29330, 29332, 61049, 61050, 61051 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 20, ["flags"] = 0 } } },
[29950] = { ["id"] = 29950, ["name"] = "Li Li's Day Off", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29950 }, ["series"] = { 29944, 29946, 29949 }, ["description"] = "Uncle Chen asked me not to get into any fights while he was away... but that doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without stopping every forty-seven steps for another rest! You want to come with me? I'll bet there's all kinds of cool places we can visit, not too far away from here.", ["objectivesText"] = "Bring Li Li to the Silken Fields, New Cifera, and Huangtze Falls. Progress: You ready to go out yet?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76350, 76973 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 21, ["flags"] = 0 } } },
[29951] = { ["id"] = 29951, ["name"] = "Muddy Water", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29951 }, ["description"] = "While you're just hangin' around, I might as well get you involved in my whole beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff together and wait. You probably heard - I like to use the muddy water from the riverbanks, to the south. Would you mind fillin' up this flask with that water and bringin' it back? I'll start gettin' the hops and barley all ready.", ["objectivesText"] = "Use Mudmug's Vial to gather muddy water. Progress: I knowed you for a friend as soon as I seen you.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 3714, 76356, 76362, 81778, 81779, 81780, 81781, 81782, 81783, 81784, 81785, 81786 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 22, ["flags"] = 0 } } },
[29952] = { ["id"] = 29952, ["name"] = "Broken Dreams", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29952 }, ["description"] = "Yes, I found the Stormstout Brewery... although I didn't exactly get the warm reception I expected. <Chen pours himself a mug of ale.> Do you want to hear the story?", ["objectivesText"] = "Speak with Chen Stormstout and listen to his story. Progress: ...", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 556, ["name"] = "Valley of the Four Winds, Mudmug's Place", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 23, ["flags"] = 0 } } },
[29966] = { ["id"] = 29966, ["name"] = "Burning Down the House", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29966 }, ["series"] = { 29943, 30015 }, ["description"] = "Look, <name>! These Alliance dogs built a camp up on the ridge. Here, take my grog. Let's make a fire they can see from Stormwind! For the Horde!", ["objectivesText"] = "Use Nazgrim's Grog to destroy the Alliance Camp atop the Scenic Overlook.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76336 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 44, ["flags"] = 0 } } },
[29967] = { ["id"] = 29967, ["name"] = "Boom Goes the Doonamite!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29967 }, ["series"] = { 29968 }, ["description"] = "It's an emergency! Looks like you stirred up a hornet's nest killin' all them fish-folk. They're conductin' a full-on counterattack on Grookin Hill! I was hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work right away! Meet me on the east side of the fort, and bring yer throwin' arm!", ["objectivesText"] = "Speak to Rivett east of Grookin Hill. Use his Methane Grenades to fend off the Jinyu attack. Progress: I think these methane-grenades are gunna impact the environment, if ya know what I mean...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80788, 80789, 80790, 80791, 80792, 80793, 80794, 80795, 80796, 80797 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 42, ["flags"] = 0 } } },
[29968] = { ["id"] = 29968, ["name"] = "Green-ish Energy", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29968 }, ["series"] = { 29967 }, ["description"] = "One word: Methane! We're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world. That, and I ran out of blasting powder... So, I need your help, <name>. No, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself. You gather up some wood for an outhouse - I'm thinking long-term here!", ["objectivesText"] = "Gather 7 Green Branches in the Dookin' Grounds Progress: Gotta watch out for the wet ones...whewee!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76333 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 41, ["flags"] = 0 } } },
[29981] = { ["id"] = 29981, ["name"] = "Stemming the Swarm", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29981 }, ["series"] = { 29872 }, ["description"] = "I'm not from here. I've never even BEEN here before today. But even I can tell you that something's wrong. That wall over there was built to keep mantid off of pandaren lands. Now, the mantid are sending their winged scouts over the top, as if the wall wasn't even there! The only reason those spindly scouts aren't dying is because they're attacking farmers, not soldiers. They wouldn't stand a chance against someone like you.", ["objectivesText"] = "Slay 14 Ik'thik mantid in Stoneplow. Progress: If the flying mantid troops have always been able to fly over, why haven't they before now?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 49, ["flags"] = 0 } } },
[29982] = { ["id"] = 29982, ["name"] = "Evacuation Orders", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29982 }, ["series"] = { 29983, 29984 }, ["description"] = "A few farmers remain in the fields... some perilously close to the crumbling wall. I don't want any farmers pretending to be heroes. We will take care of this mantid swarm, and then they can return to their homes. My Shado-Pan are too busy defending this town to organize evacuations. You want to prove yourself useful? Get those farmers out of harm's way.", ["objectivesText"] = "Evacuate the Blacksoil Family, the Spadepaw Family, the Greentill Family, and the Marlfur Family.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88019, 88020, 88021, 88022, 88023, 88024, 88025, 88026, 88027 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 50, ["flags"] = 0 } } },
[29983] = { ["id"] = 29983, ["name"] = "The Hidden Master", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29983 }, ["series"] = { 29982, 29984 }, ["description"] = "We should be able to handle the defense of Stoneplow from here on out. <The Watch Commander motions towards Lin Tenderpaw.> Lin here is searching for someone she calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue for you. Go north.", ["objectivesText"] = "Find Master Bruised Paw in the Valley of the Four Winds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 51, ["flags"] = 0 } } },
[29984] = { ["id"] = 29984, ["name"] = "Unyielding Fists: Trial of Bamboo", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29984 }, ["series"] = { 29982, 29983 }, ["description"] = "We will start with a test: The Trial of Bamboo. Your friend Lin failed this test. Follow me, and listen carefully to my instructions.", ["objectivesText"] = "Speak with Master Bruised Paw , then successfully strike the Stack of Bamboo Reeds 3 times. Progress: If you cannot pass this test, then there is probably no reason to continue our training.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 52, ["flags"] = 0 } } },
[29985] = { ["id"] = 29985, ["name"] = "They Will Be Mist", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29985 }, ["series"] = { 29986, 29987, 29988, 29989 }, ["description"] = "The mist in this forest is a constant nuisance - one which I'm glad to hand off to trainees like you. Strange creatures lurk in the mist between these trees, and they must constantly be pushed back. Consider this part of your training.", ["objectivesText"] = "Slay 12 Mist Incarnations .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 53, ["flags"] = 0 } } },
[29986] = { ["id"] = 29986, ["name"] = "Fog Wards", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29986 }, ["series"] = { 29985, 29987, 29988, 29989 }, ["description"] = "Trainee. Several wards surround us, hidden in the woods near my home. They are quite effective at dispersing the mist, but they require constant upkeep. You will find one to the north, one to the west, and one to the south. Find these wards and light them.", ["objectivesText"] = "Light the Northern Fog Ward, the Western Fog Ward, and the Southern Fog Ward. Progress: See if you can light one of the wards while one of the mist incarnations is nearby.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81814, 81815, 81816, 81817, 81818 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 54, ["flags"] = 0 } } },
[29987] = { ["id"] = 29987, ["name"] = "Unyielding Fists: Trial of Wood", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29987 }, ["series"] = { 29985, 29986, 29988, 29989 }, ["description"] = "You have progressed in your training, I think. Come with me, and we will attempt the Trial of Wood.", ["objectivesText"] = "Speak with Master Bruised Paw , then successfully strike the Stack of Wooden Blocks 4 times. Progress: I'm prepared, <name>. Are you?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 56, ["flags"] = 0 } } },
[29988] = { ["id"] = 29988, ["name"] = "A Taste For Eggs", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29988 }, ["series"] = { 29985, 29986, 29987, 29989 }, ["description"] = "I can sense your anxiety, but you are not ready yet. Your training must continue before you perform the final test. As for your task... I need you to fetch me some eggs. Yes, eggs. The marshland atop the hills to the east is home to a number of birds, all of which are generally peaceful in nature. You should have no trouble gathering enough eggs to last me several weeks.", ["objectivesText"] = "Obtain 10 Emperor Tern Eggs , 4 Whitefisher Crane Eggs , and 1 Hornbill Strider Egg . Progress: How is your egg hunt going?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76501, 76503, 76516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 57, ["flags"] = 0 } } },
[29989] = { ["id"] = 29989, ["name"] = "Unyielding Fists: Trial of Stone", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29989 }, ["series"] = { 29985, 29986, 29987, 29988 }, ["description"] = "You have accomplished much in the short time you have been here, <name>. I would not normally offer this test so soon... but I feel that you're ready. It is time you attempted the Trial of Stone.", ["objectivesText"] = "Speak with Master Bruised Paw , then successfully strike the Stack of Stone Blocks 5 times. Progress: This test will be trying. You will test the strength of your fists against the strength of stone. Steel yourself, <name>. Not literally, of course. Unless you normally wear steel gloves... in which case, you may literally steel yourself.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 81760, 81761, 81762, 81763, 81764, 81765, 81766, 81767, 81768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 58, ["flags"] = 0 } } },
[29990] = { ["id"] = 29990, ["name"] = "Training and Discipline", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29990 }, ["description"] = "I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, <name>. I'm not going to let it slip away. Still, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me. Oh, and if you run into the others, maybe you should tell them where the Hidden Master is...", ["objectivesText"] = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 59, ["flags"] = 0 } } },
[29992] = { ["id"] = 29992, ["name"] = "Tenderpaw By Name, Tender Paw By Reputation", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 29992 }, ["description"] = "I'd like to go tell Xiao, Kang, and the others that I've found the hidden master, but now he won't let me leave! He says I have to pass that test of bamboo first. <Lin whispers:> How'd you do that, by the way? It looks like, for the time being, I'm stuck here practicing my punches against this rock. And my knuckles are about to cave in. If you could gather some jademoon leaves, I could prepare an ointment and at least numb some of this pain.", ["objectivesText"] = "Gather 18 Jademoon Leaves . Progress: Ow! Ow! Ow!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 55, ["flags"] = 0 } } },
[29993] = { ["id"] = 29993, ["name"] = "Find the Boy", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29993 }, ["series"] = { 29920, 29995 }, ["description"] = "Have you seen my son, Lo? He was here a moment ago and I told him we were leaving today. I'm sure he's off trying to woo that young Syra Goldendraft. That is the very reason we need to leave! No son of mine is going to run off with a Goldendraft! I'm going to search around here for them. I do keep catching those two sneaking off to the Arboretum. Any chance you could head out there and look for them?", ["objectivesText"] = "Speak with Inkmaster Wei .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 54, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 50, ["flags"] = 0 } } },
[29995] = { ["id"] = 29995, ["name"] = "Shrine of the Dawn", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29995 }, ["series"] = { 29920, 29993 }, ["description"] = "The \"children\" you seek are not actually children but grown pandaren, despite what their elders might claim. Their love will not be held in check by the feuds of their families. You will find both Syra and Lo at the Shrine of the Dawn, ever seeking an answer to their dilemma amongst the pandriarchs of old.", ["objectivesText"] = "Search the Shrine of the Dawn for Syra Goldendraft .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 55, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 51, ["flags"] = 0 } } },
[29997] = { ["id"] = 29997, ["name"] = "The Scryer's Dilemma", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29997 }, ["series"] = { 29931, 29932, 30011, 30495 }, ["description"] = "Since you were so helpful at the mines, would you be willing to help us with a small problem here at the temple? Wise Mari has been complaining recently of a disturbance in his temple. The water sprites have gotten quite playful recently, and made off with his ceremonial staff. If you could help him, I would be most grateful. I may even put in a word with the Jade Serpent for you. Just follow the path to the north.", ["objectivesText"] = "Kill Water Fiends to recover Wise Mari 's Staff. Progress: The pools are clouded. I will need my staff to calm the spirits and speak to the water.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76725 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 70, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 66, ["flags"] = 0 } } },
[29998] = { ["id"] = 29998, ["name"] = "The Librarian's Quandary", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 29998 }, ["series"] = { 30001, 30002, 30004 }, ["description"] = "Lorewalker Stonestep is in charge of the entire temple library. Lately, something has been troubling him and his work. With thousands of ancient tomes to be transcribed, I can't afford to have him distracted. Would you follow the path south to the library and see what ails him?", ["objectivesText"] = "Speak to Lorewalker Stonestep in the temple library.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 72, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 68, ["flags"] = 0 } } },
[30001] = { ["id"] = 30001, ["name"] = "Moth-Ridden", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30001 }, ["series"] = { 29998, 30002, 30004 }, ["description"] = "Moths have infested the library. Moths! Any librarian worth his letters knows that moths are the most dangerous threat to paper, second only to bookworms. As it turns out, my assistants are a useless bunch of insect-fearing cowards. Please, you MUST help me get rid of the moths immediately! The works of a thousand pandaren storytellers depend on you!", ["objectivesText"] = "Kill 8 Dappled Moths . Progress: I can see the moths eating the pages from here!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 74, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 70, ["flags"] = 0 } } },
[30002] = { ["id"] = 30002, ["name"] = "Pages of History", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30002 }, ["series"] = { 29998, 30001, 30004 }, ["description"] = "The worst possible thing has happened, <race>. We. Have. Bookworms . This is a critical situation. All Bookworms in the library must be eradicated at once to prevent their spread. We must squash this problem, literally! Please examine the infested books in the library and squash any Bookworms that you find.", ["objectivesText"] = "Search through the library books for infestations, then squash 12 Bookworms .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80722, 80723, 80724, 80725, 80726, 80727, 80728, 80729, 80730 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 73, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 69, ["flags"] = 0 } } },
[30004] = { ["id"] = 30004, ["name"] = "Everything In Its Place", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30004 }, ["series"] = { 29998, 30001, 30002 }, ["description"] = "You have helped us more than you can ever imagine, <name>. I do not know what I would do if our precious scrolls were ever to be lost. Please return to the Elder Sage Rain-Zhu and tell him that the library is in order.", ["objectivesText"] = "Speak to Elder Sage Rain-Zhu at the Temple of the Jade Serpent in Jade Forest.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 75, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 71, ["flags"] = 0 } } },
[30005] = { ["id"] = 30005, ["name"] = "Lighting Up the Sky", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30005 }, ["series"] = { 29999, 30000 }, ["description"] = "Do you like fireworks, <sir/miss>? I love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty! I think there are still some old launchers lying around the temple. Would you go set off some big fireworks for me? It would make me so happy!", ["objectivesText"] = "Set off 8 fireworks.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 77, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 73, ["flags"] = 0 } } },
[30011] = { ["id"] = 30011, ["name"] = "A New Vision", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30011 }, ["series"] = { 29931, 29932, 29997, 30495 }, ["description"] = "Please tell the Elder Sage Rain-Zhu that I will begin my work at once.", ["objectivesText"] = "Speak to Elder Sage Rain-Zhu near the courtyard in the Temple of the Jade Serpent in the Jade Forest .", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 71, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 67, ["flags"] = 0 } } },
[30015] = { ["id"] = 30015, ["name"] = "Dawn's Blossom", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30015 }, ["series"] = { 29943, 29966 }, ["description"] = "Blood and Thunder! My axe hungers! We won't return to Orgrimmar until every last Alliance is purged from this land. I will train these natives myself, if I have to. One way or another, this land will be made ready for Horde settlement. In the meantime, their chief gave me this to pass on to you - a map and a message in some fancy script. Do what you must, but be quick about it. War is brewing...", ["objectivesText"] = "Speak with Lorewalker Cho in Dawn's Blossom. Speak to the flightmaster in Grookin Hill for passage. Provided item:", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["rewardItems"] = { 76761 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 45, ["flags"] = 0 } } },
[30028] = { ["id"] = 30028, ["name"] = "Grain Recovery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30028 }, ["description"] = "Since you are heading south, can you try to recover some of the grain that these thieves made off with? We saw birds and sprites running off with entire bags of our best bulk stock into the fields east and south of here.", ["objectivesText"] = "Bring 8 Sacks of Grain to Grainlord Kai . Progress: Between birds and sprites we are never going to meet our quota to the Stormstout Brewery.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 77033 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 40, ["flags"] = 0 } } },
[30029] = { ["id"] = 30029, ["name"] = "Wee Little Shenanigans", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30029 }, ["series"] = { 30032, 30047, 30049, 30051, 30073, 30074, 30172 }, ["description"] = "So... we bought some cheap grains in bulk. It turned out the grain was infested with sprites. I HATE sprites. With their wee beady eyes and constant smiling. I would like to resolve this quietly. Can I buy your services to discretely eliminate some of these grain thieves?", ["objectivesText"] = "Kill 8 Tricky Maizers . Progress: Oh good, they didn't turn you into a frog yet. I saw them do that once you know.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 84329, 84330, 84331, 84332, 84333 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 36, ["flags"] = 0 } } },
[30030] = { ["id"] = 30030, ["name"] = "Out of Sprite", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30030 }, ["description"] = "Just to be clear, what happened was an accident. What I did, I did for INDUSTRY! There was no way I could have known that a sprite invasion would happen at any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" formula. Now not only do they have a big sprite leading them, but he's one angry beast. If I pay you, will you take him out?", ["objectivesText"] = "Defeat Cornan the Barley Barbarian. Progress: Oh why? Why did I have to tamper with the natural order of things? All I wanted was to make these grains grow faster and more numerous.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 37, ["flags"] = 0 } } },
[30032] = { ["id"] = 30032, ["name"] = "The Quest for Better Barley", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30032 }, ["series"] = { 30029, 30047, 30049, 30051, 30073, 30074, 30172 }, ["description"] = "Looking for sweet grain? My father once mentioned a malted cave barley that sounds about right. If you are willing to brave the peril, there is an ancient cave at the base of the Winds' Edge south of here. There is even an old lift my father made when he would travel into the jungle. In the cave is a bush as old as my family. From that bush you can pluck a grain so sweet it will humble your senses. Just watch out for its guardians.", ["objectivesText"] = "Find the Malted Cave Barley at the base of the Winds' Edge. Progress: That jungle sounds spooky.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 77034, 81787, 81788, 81789, 81790, 81791, 81792, 81793, 81794, 81795 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 39, ["flags"] = 0 } } },
[30046] = { ["id"] = 30046, ["name"] = "Chen's Resolution", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30046 }, ["description"] = "You know what? I don't have to take this. I'll show that Uncle Gao what it means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients I've never even used before. I'm Chen Stormstout , and I'm the best brewer alive.", ["objectivesText"] = "Meet up with Chen Stormstout at Halfhill.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 24, ["flags"] = 0 } } },
[30050] = { ["id"] = 30050, ["name"] = "Gardener Fran and the Watering Can", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30050 }, ["description"] = "You want me to just GIVE you some hops? Pfshh! This is the third time today some little <race> like you has come up to me asking for food! You want food? Then you'd better work! <She shoves a watering can into your hand.> Now go water my plants!", ["objectivesText"] = "Listen to Gardener Fran 's orders and water 60 of her vegetables. You can water plants while mounted. Progress: Water my plants you lazy <class>!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 77281, 81844, 81845, 81846, 81847, 81848, 81849, 81850, 81851, 81852, 81853 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 29, ["flags"] = 0 } } },
[30051] = { ["id"] = 30051, ["name"] = "The Great Water Hunt", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30051 }, ["series"] = { 30029, 30032, 30047, 30049, 30073, 30074, 30172 }, ["description"] = "Look at it, <name>: the Gilded Fan. I heared lots of good things about the water they got here. Lots of bad things, too. No sayin' what kind of water Chen's gonna be needin', so what say we make him a little sampler platter? Come on, let's get movin'. We'll go scoop up some water together.", ["objectivesText"] = "Guide Mudmug to Swirling Pools within the Gilded Fan, and help him collect 30 pawfuls of Gladewater. If you become separated from Mudmug , you can find him next to the giant banana in the Gilded Fan. Progress: That Stormstout feller says that he's the best brewer that ever was. Might be true, couldn't tell ya one way or the 'nother as of yet.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81839, 81840, 81841, 81842, 81843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 33, ["flags"] = 0 } } },
[30052] = { ["id"] = 30052, ["name"] = "Weed War", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30052 }, ["description"] = "You want some hops? I've got plenty in the shed out back. I'll gladly share some with you... if you'll help me weed my field. Now \"hop\" to it! Get it?", ["objectivesText"] = "Pull 100 weeds from Gai Lan 's field. You can pull weeds while mounted.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 43352, 71153, 89686 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 28, ["flags"] = 0 } } },
[30054] = { ["id"] = 30054, ["name"] = "Enough is Ookin' Enough", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30054 }, ["description"] = "Virmen, they bite too much. They bite Mung-Mung 's carrot. They bite Mung-Mung 's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung 's tail and foot. Enough is ookin' enough. You fight way better than Mung-Mung does. Bring back their bitey teeth. Then we see who does the biting.", ["objectivesText"] = "Obtain 100 Virmen Teeth. Progress: You bring back those teeth, and maybe Mung-Mung will have some hops for you.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 77379 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 30, ["flags"] = 0 } } },
[30055] = { ["id"] = 30055, ["name"] = "Stormstout's Hops", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30055 }, ["series"] = { 30053 }, ["description"] = "All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.", ["objectivesText"] = "Return to Chen Stormstout in Halfhill.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 31, ["flags"] = 0 } } },
[30056] = { ["id"] = 30056, ["name"] = "The Farmer's Daughter", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30056 }, ["series"] = { 30057 }, ["description"] = "Brave <class>, you could not have arrived at a better time. My daughter is missing! I've got a suspicion that the virmen took her down into that stinking little warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from fighting them off all morning. Could you look for her?", ["objectivesText"] = "Find Mina Mudclaw .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 26, ["flags"] = 0 } } },
[30057] = { ["id"] = 30057, ["name"] = "Seeing Orange", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30057 }, ["series"] = { 30056 }, ["description"] = "Those virmen... they make me do horrible, horrible, silly things. All involving carrots. I couldn't tell you how many carrots they threw at me. Let's not waste any more time. Get me out of here!", ["objectivesText"] = "Bring Mina Mudclaw back home to her father.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81751, 81752, 81753, 81754, 81755, 81756, 81757, 81758, 81759 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 27, ["flags"] = 0 } } },
[30069] = { ["id"] = 30069, ["name"] = "No Plan Survives Contact with the Enemy", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30069 }, ["description"] = "Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at least. Rell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin and Taylor, but it's getting hot in there and he needs support. Fight yer way through these dogs and find Rell!", ["objectivesText"] = "Kill 6 Garrosh'ar Grunts and 6 Garrosh'ar Gear-Greasers . Progress: This place is crawling with Horde soldiers - we can't advance on their leader with so many at our backs.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 4, ["flags"] = 0 } } },
[30070] = { ["id"] = 30070, ["name"] = "The Fall of Ga'trul", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30070 }, ["series"] = { 31745 }, ["description"] = "Alright <lad/lass>. We've taken enough jabs at this warlock army... now it's time to cut off the head. Ga'trul 's back there, in that big ol' temple ruin. Give him a good what-for, and the Horde will have lost its last stake here in Pandaria.", ["objectivesText"] = "Slay Ga'trul .", ["rewardGold"] = 294000, ["rewardXP"] = 166000, ["rewardItems"] = { 90338, 90339, 90340, 90341, 90342, 90343, 90344, 90345, 90346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 15, ["flags"] = 0 } } },
[30073] = { ["id"] = 30073, ["name"] = "The Emperor", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30073 }, ["series"] = { 30029, 30032, 30047, 30049, 30051, 30074, 30172 }, ["description"] = "We have everything we need. It's time to start brewing. Pay attention, <name>... you might learn a thing or two.", ["objectivesText"] = "Stand by and help Chen Stormstout with his brew. Progress: It takes more than three seconds to make beer, <name>. Even when your name is Chen Stormstout .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 42, ["flags"] = 0 } } },
[30074] = { ["id"] = 30074, ["name"] = "Knocking on the Door", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30074 }, ["series"] = { 30029, 30032, 30047, 30049, 30051, 30073, 30172 }, ["description"] = "Now, onward to the Stormstout Brewery! It's high time that I was reunited with the rest of the Stormstouts... and what better way to reunite than over a few mugs of ale? You know where the brewery is, right? Just follow this road to the west. You can't miss it. Of course, you're free to share the road with us - we'll be leaving any moment now.", ["objectivesText"] = "Meet up with Chen Stormstout at the entrance of the Stormstout Brewery.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 43, ["flags"] = 0 } } },
[30078] = { ["id"] = 30078, ["name"] = "Cleaning House", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30078 }, ["series"] = { 30075, 30085, 31327 }, ["description"] = "That's it, <name>. I've had enough of this. If somebody doesn't do SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much family history - and beer - in there to risk wasting. So... we're going to break in through the back door. You, Li Li, Mudmug, and me. It's gonna be a brawl in there. Let me know when you're ready.", ["objectivesText"] = "Defeat Eddy , Jooga , and the Fizzy Yellow Alemental . Progress: Let's do this.", ["rewardGold"] = 306000, ["rewardXP"] = 193000, ["rewardItems"] = { 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 47, ["flags"] = 0 } } },
[30080] = { ["id"] = 30080, ["name"] = "Finding Yi-Mo", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30080 }, ["series"] = { 30082, 30091 }, ["description"] = "My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair hit the town, he took it harder than most. He sat around for days refusing to eat, just staring off into the horizon. Now he's wandered off toward the cliffs northeast of here, where the thunderbirds nest and hunt. Please, <class>, will you look for him?", ["objectivesText"] = "Look for Yi-Mo Longbrow somewhere northeast of Zhu's Watch. Progress: <Yi-Mo lets out a long sigh.>", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 17, ["flags"] = 0 } } },
[30082] = { ["id"] = 30082, ["name"] = "Cheer Up, Yi-Mo", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30082 }, ["series"] = { 30080, 30091 }, ["description"] = "Ever since this storm began, I've just been... tired. Not physically... no. It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels when a mate leaves them for someone with a rounder belly, but I've never had a mate so how would I know? How can I claim to know anything? I'm worthless to everyone but these thunderbirds. At least they'll have a good meal out of me. <Yi-Mo sighs deeply and continues staring off into the sky. It doesn't look like he's going anywhere.>", ["objectivesText"] = "Bring Yi-Mo Longbrow back to Zhu's Watch.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 81440, 81441, 81442, 81443, 81444, 81445, 81446, 81447, 81448 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 18, ["flags"] = 0 } } },
[30083] = { ["id"] = 30083, ["name"] = "Securing the Province", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30083 }, ["description"] = "With our grip on the province loosening, saurok from the wilds have already moved in to the cave just north of town. Most of our hunters are face-down in their own tears, so the saurok just walk in here like they own the place and grab whatever they want! I want to send a message that Zhu's Watch is not to be crossed. Will you be my messenger?", ["objectivesText"] = "Kill 10 Wildscale Saurok or Wildscale Herbalists in Zhu Province. Progress: We cannot let the saurok walk all over us anymore.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 81512, 81513, 81514, 81515, 81516, 86220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30084] = { ["id"] = 30084, ["name"] = "Borderlands", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30084 }, ["description"] = "Bonfires are surprisingly effective at discouraging beasts from wandering out of the wilds. We have three along the border to the southwest which we normally keep lit at all times. Nobody's been there for days, though, and the fires must be out by now. It's only a matter of time before the wilds creep back in and overtake the land we have kept safe for centuries. Please, re-ignite the bonfires. They are critical in keeping the province safe, and they are memorials to the founders of our way of life.", ["objectivesText"] = "Light the Memorial Flame of Zhu, Memorial Flame of Rin, and Memorial Flame of Po along the southwest border of Zhu Province. Progress: Zhu warned against the dangers of trying to conquer the wilds, and asked only that we contain them. The bonfires honor his wishes and his spirit.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 78928 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30088] = { ["id"] = 30088, ["name"] = "Why So Serious?", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30088 }, ["description"] = "Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still sad... We try another old hozen remedy - this time, we go back even further than gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at parties. Ken-Ken got woodworking to do - you bring him teeth! Not yours; big ones, like a panther would have! Oh, and some paint! Mei might know where to find.", ["objectivesText"] = "Collect 18 Huge Panther Fangs and 1 Jar of Pigment from Zhu Province. Progress: < Ken-Ken is hard at work carving something out of tree bark.> This gonna be great, you'll see.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 78941, 78942, 88053, 88054, 88055, 88056, 88057, 88058, 88059, 88060, 88061, 88580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 20, ["flags"] = 0 } } },
[30089] = { ["id"] = 30089, ["name"] = "Apply Directly to the Forehead", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30089 }, ["description"] = "Well... THAT was unexpected! Come to think of it, now Ken-Ken remember why hozen use mask in the first place... A legend about the Monkey King says he used a mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then they buried mask--with all his sadness--in the ground. We should use the mask on more pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT. Let's do this, <name>!", ["objectivesText"] = "Use Ken-Ken's Mask to cure 8 Despondent Wardens of Zhu in Zhu's Watch. Progress: This must be the emperor's sad coming back! That is some oooold sad. Ken-Ken bet pandaren sad get stronger with age, too, like pandaren booze.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79021, 81467, 81468, 81469, 81470, 81471, 81472, 81473, 81474, 81475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 21, ["flags"] = 0 } } },
[30090] = { ["id"] = 30090, ["name"] = "Zhu's Despair", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30090 }, ["description"] = "Hmm... Is that Yi-Mo kid over there? < Ken-Ken squints against the increasing torrents of rain.> It is! He's at the well, and he's not lookin' so good. Ken-Ken got a bad feeling about this...", ["objectivesText"] = "Exorcise the Sha of Despair energy from Yi-Mo Longbrow in Zhu's Watch.", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 79057, 88580, 89112 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 22, ["flags"] = 0 } } },
[30091] = { ["id"] = 30091, ["name"] = "Tears of Pandaria", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30091 }, ["series"] = { 30080, 30082 }, ["description"] = "All of this started with our ponds. In a single day, all of the water retreated down into the earth. When there was no more water in the ponds, it began to fall from the sky. Despite endless torrents of rain, the ponds do not fill. It's as if the land itself thirsts and cannot be quenched. Now the ponds birth horrific manifestations of despair. Elementals made of water from the sky and salt from the earth; the tears of Pandaria.", ["objectivesText"] = "Kill 12 Weeping Horrors in Zhu Province. Progress: I don't know why this is happening, but I can say for certain that those elementals were the start of it all.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30117] = { ["id"] = 30117, ["name"] = "Stoneplow Thirsts", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30117 }, ["description"] = "Excuse me... <name>? Did I hear your name correctly? I've come from Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the Stormstout Brewery is all boarded up! It looks like your handsome friend there - no, not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town in need?", ["objectivesText"] = "Deliver a cask of The Emperor to Loon Mai at Stoneplow in the Valley of the Four Winds . Progress: Greetings, <class>.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 81393 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 48, ["flags"] = 0 } } },
[30123] = { ["id"] = 30123, ["name"] = "Skitterer Stew", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30123 }, ["description"] = "Leza has a fever. No mother in labor should have a fever. Mama Bramblestaff once told me that Skitterer Stew could heal almost any illness. Let us put this knowledge to the test. Gather some intact skitterer glands for me while I get the herbs we'll need and I'll whip up a batch.", ["objectivesText"] = "Gather 5 Intact Skitterer Glands . Progress: Even the jungle air is alive with danger.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 78911 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 1, ["flags"] = 0 } } },
[30124] = { ["id"] = 30124, ["name"] = "Blind Them!", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30124 }, ["description"] = "These sunwalkers are a tiresome lot. I need soldiers with horde blood in their veins and honor in their hearts. Not some pacifist sun spirit filth. The Alliance are here, $p. Followed us no doubt, or somehow tracked the same visions Leza had that led us here. It doesn't matter. I don't want them to know how divided we are at the moment. Go kill their scout south of here before it can report back. Hellscream's eyes upon you.", ["objectivesText"] = "Kill the Darnassian Outrider . Progress: Sentinels. Bah! I remember a time when these creatures were the terror of the trees, hunting any <race> or tauren that dared enter their wood in search of food or shelter.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 2, ["flags"] = 0 } } },
[30127] = { ["id"] = 30127, ["name"] = "Threat from Dojan", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30127 }, ["series"] = { 30128, 30129, 30131, 30132, 30163, 30464 }, ["description"] = "Mogu? They seem like the elves, ancient and an over developed sense of entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not \"visiting\" this world. We are here. We are staying. Teach them this lesson. Quell their numbers in the ruins south and west of here. Break their amassing forces before they decide to attack. Learn what you can of how these creatures fight, and how they die.", ["objectivesText"] = "Kill 6 Dojani Reclaimers and 8 Dojani Surveyors , and 4 Dojani Enforcers .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 84281, 84282, 84283, 84284, 84285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 3, ["flags"] = 0 } } },
[30128] = { ["id"] = 30128, ["name"] = "The Pools of Youth", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30128 }, ["series"] = { 30127, 30129, 30131, 30132, 30163, 30464 }, ["description"] = "The mogu found the Pools of Youth! Mama Bramblestaff used to tell me old stories about those. During the mogu empire they would use the waters to extend life. Thing is those stories never ended well for some reason. As if the waters were cursed. Either way, we should investigate. There is a good chance those waters might help Leza. It looks like the Pools of Youth are on the northwestern side of the ruins.", ["objectivesText"] = "Recover water from the Pools of Youth. Progress: Leza's pain is immense. Only powers beyond my own can save her and the baby now.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 78934, 81537, 81538, 81539, 81540, 81541 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 6, ["flags"] = 0 } } },
[30129] = { ["id"] = 30129, ["name"] = "The Mogu Agenda", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30129 }, ["series"] = { 30127, 30128, 30131, 30132, 30163, 30464 }, ["description"] = "Mogu don't often gather in numbers like this. We should find out what they are up to. I thought I heard someone shouting orders near the center of the ruins. We should probably see if he has information.", ["objectivesText"] = "Recover the Dojani Orders . Progress: The mogu once ruled as emperors, subjugating all races they encountered. It would seem these particular mogu have aspirations of reliving the past.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 78917 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 5, ["flags"] = 0 } } },
[30130] = { ["id"] = 30130, ["name"] = "Herbal Remedies", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30130 }, ["description"] = "Kang's remedy isn't working. There is something else at work here. A power deep beneath the soil. It is sapping us of hope, hitting us with depression and despair. Kang tells me this land has lotus plants. I might be able to make a tea that would hopefully lend Leza some strength. Please, $p, search the ruins south and west of here for lotus leaves. I will pay you for your efforts.", ["objectivesText"] = "Find 20 Imperial Lotus Leaves . Progress: I've been punched, stabbed, thrown off of a cliff, hit in the face by someone's mace, hit in the face by my own mace, and fell off the elevator at Thunder Bluff on more than one occasion. None of that pain sounds even half as bad as what Leza is going through. I hope this tea helps...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 78918, 88532 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 4, ["flags"] = 0 } } },
[30132] = { ["id"] = 30132, ["name"] = "Going West", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30132 }, ["series"] = { 30127, 30128, 30129, 30131, 30163, 30464 }, ["description"] = "Leza now walks with the ancestors of this strange land. I must look now to the living. Kor has led a group of our scouts west deeper into the jungle. I sent a scout of my own to investigate the crane temple. Please, $p, seek out my scout, get their report, then meet up with Kor and lend what aid you can to him. We will join you as quickly as we are able.", ["objectivesText"] = "Find the Sunwalker Scout near the Crane Temple. Progress: War. It always comes down to war.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 79745, 84281, 84282, 84283, 84284, 84285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 52, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 8, ["flags"] = 0 } } },
[30133] = { ["id"] = 30133, ["name"] = "Into the Wilds", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30133 }, ["description"] = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. They should be told of what happened here. If you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker .", ["objectivesText"] = "Locate the missing Zhu's Watch Courier in the northern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79825 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 23, ["flags"] = 0 } } },
[30163] = { ["id"] = 30163, ["name"] = "For the Tribe", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30163 }, ["series"] = { 30127, 30128, 30129, 30131, 30132, 30464 }, ["description"] = "We fell back to the refuge when the mogu attacked but lost a number of our people along the way. Travel west and north of here and look for any captives you can rescue that could help us in our fight. Leave any Alliance you find to their fate.", ["objectivesText"] = "Rescue 8 Dawnchaser Captives .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 57198, 57215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 54, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 10, ["flags"] = 0 } } },
[30164] = { ["id"] = 30164, ["name"] = "The Stoneplow Convoy", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30164 }, ["series"] = { 30174, 30241 }, ["description"] = "I tried to save as many of the Stoneplow envoys as I could but these \"mantid\" dragged many of them off into the jungle. These are civilians in need of our help. Please take the herbs you gathered earlier. I've infused them with what gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as you can.", ["objectivesText"] = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys . Progress: A sunwalker's first duty is to preserve and protect life.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79163, 84291, 84292, 84293, 84294, 84295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 57, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 13, ["flags"] = 0 } } },
[30172] = { ["id"] = 30172, ["name"] = "Barreling Along", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30172 }, ["series"] = { 30029, 30032, 30047, 30049, 30051, 30073, 30074 }, ["description"] = "No, no, no, don't you worry about pickin' 'em up. I can hold these here barrels. I may not be the handsomest pandaren, or the smartest, or any fun to be around in the slightest, but I'm stronger than a mushan beast. I'mma just need you to lead the way.", ["objectivesText"] = "Lead Mudmug back to Halfhill. If you become separated from Mudmug , you can find him next to the giant banana in the Gilded Fan. Progress: Where's Mudmug ?", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5489, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 557, ["name"] = "Valley of the Four Winds, Chen's Masterpiece", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5489, ["name"] = "Valley of the Four Winds", ["orderIndex"] = 34, ["flags"] = 0 } } },
[30174] = { ["id"] = 30174, ["name"] = "For Family", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30174 }, ["series"] = { 30164, 30241 }, ["description"] = "Kor should have caught up by now. He said he was going to secure the Ruins of Korja east of here and meet us to help with the mantid threat. He may need help against Groundbreaker Brojai . Could you assist him? Kang and I will follow shortly.", ["objectivesText"] = "Search for Kor Bloodtusk. Progress: This land claims so much.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81449, 81450, 81451, 81452, 81453, 81454, 81455, 81456, 81457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 58, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 15, ["flags"] = 0 } } },
[30175] = { ["id"] = 30175, ["name"] = "The Mantid", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30175 }, ["description"] = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that. Now they are preparing to hit Stoneplow. Please, <class>, destroy some of these beasts before they get sufficient numbers to flank our home. If my cousin, Ambassador Len , is still alive and at our convoy he should be able to reward you for your help.", ["objectivesText"] = "Kill 10 Ik'thik Precursors .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81458, 81459, 81460, 81461, 81462, 81463, 81464, 81465, 81466, 83707, 83708, 83709, 83710, 83711, 83712, 83713, 83714, 83715, 87399, 95373 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 14, ["flags"] = 0 } } },
[30178] = { ["id"] = 30178, ["name"] = "Into the Wilds", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30178 }, ["description"] = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. They should be told of what happened here. If you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker .", ["objectivesText"] = "Locate the missing Zhu's Watch Courier in the southern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 79825 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 25, ["flags"] = 0 } } },
[30181] = { ["id"] = 30181, ["name"] = "Mushan Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30181 }, ["description"] = "Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on probably. A fine trophy. If you are lookin' to test your mettle as a big game hunter, start with them.", ["objectivesText"] = "Kill 15 Dustback Mushans . Progress: They didn't send ya' runin' did they?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81854, 81855, 81856, 81857, 81858, 81859, 90542, 90545, 90622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 16, ["flags"] = 0 } } },
[30182] = { ["id"] = 30182, ["name"] = "Fox Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30182 }, ["series"] = { 30183 }, ["description"] = "So, when I was scouting east of here I saw a collection of foxes. That's what I first learned to hunt when back on the Wandering Isle. If you want to see the challenge a young pandaren hunter faced when growing up, head east and face off against a bunch of foxes. They tend to be clever and cunning so be on your guard.", ["objectivesText"] = "Kill 15 Sly Foxes . Progress: I used to go on fox hunts with my father. If he could see me now! Hunting in Pandaria!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 10592, 64403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 19, ["flags"] = 0 } } },
[30183] = { ["id"] = 30183, ["name"] = "Stalker Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30183 }, ["series"] = { 30182 }, ["description"] = "Tigers! No matter what land I go to I hear about these big fanged beasts. And yet I haven't had a chance to hunt any of them. Let's go hunt some tigers. I'll go east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near those mushan.", ["objectivesText"] = "Kill 15 Gorge Stalkers . Progress: What's your count up to?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 84320, 84321, 84322, 84323, 84324, 84325, 84326, 84327, 84328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 17, ["flags"] = 0 } } },
[30184] = { ["id"] = 30184, ["name"] = "Mushan Mastery: Darkhide", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30184 }, ["description"] = "My boy here is a talented hunter... in training. Let's show him an old 'Nessy style hunt shall we? I saw a mighty big mushan east of here with a hide dark as night. It looked like it had taken down a number of hunters in its day. If you want a big game hunt, go try an' take it on.", ["objectivesText"] = "Obtain Darkhide's Head . Progress: Puttin' the \"big\" into \"Big Game Hunter.\"", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79058, 81854, 81855, 81856, 81857, 81858, 81859, 90542, 90545, 90622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 18, ["flags"] = 0 } } },
[30185] = { ["id"] = 30185, ["name"] = "Tortoise Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30185 }, ["series"] = { 30186 }, ["description"] = "Granted, tortoises are not big game but they can be mean game. They also work as the perfect bait for bigger game! Gotcher found some ol' tablets sayin' that the Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the waters as it were. Well ah mean to see me what's down in that water. Gather up some fresh tortoise shells and meet me at the pit. Let's see if ol' legends be true.", ["objectivesText"] = "Gather 5 Intact Tortoise Shells . Progress: I've always been livin' in me father's shadow. But after today, folks are gonna remember the name of Nesingwary, Jr.!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79059 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 20, ["flags"] = 0 } } },
[30186] = { ["id"] = 30186, ["name"] = "Parental Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30186 }, ["series"] = { 30185 }, ["description"] = "If them tablets were correct, all ay got ta do is a small dance ritual and the big thing o' the deep will be summoned. When it comes out, we'll get 'em and show me pop we are both true big game hunters like him.", ["objectivesText"] = "Destroy Torjar's Bane . Progress: Now that is how ya big game hunt.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81819, 81820, 81821, 81822, 81823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 558, ["name"] = "Valley of the Four Winds, Stormstout Brewery & The Hidden Master & Nesingwary's Safari", ["orderIndex"] = 21, ["flags"] = 0 } } },
[30229] = { ["id"] = 30229, ["name"] = "The Greater Danger", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30229 }, ["description"] = "I apologize for my harsh words earlier. Dezco might have been right to wait and move west with a unified strength. The mogu hit us hard when we were searching the ruins west of here. They ambushed us using summoning portals and some dark magics. I haven't seen such evil sorcery used since Outland. We need a respite. Head west, kill their summoners, cut their supply line.", ["objectivesText"] = "Kill 8 Korjani Reclaimers.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 55, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 12, ["flags"] = 0 } } },
[30269] = { ["id"] = 30269, ["name"] = "Unsafe Passage", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30269 }, ["description"] = "As we say at the temple: \"Never fight a tiger with a hozen on your back.\" We will deal with the sha, but first we must see to the more immediate... nuisance. <Koro slams the writhing saurok HARD against the stone.> Groups of refugees from the temple are heading for a camp to the north, but they're being ambushed by saurok. Help me see the next group to the camp and we'll figure out our next move from there.", ["objectivesText"] = "Help Koro Mistwalker escort a group of refugees from the Temple of the Red Crane to Crane Wing Refuge. Speak with Koro first to begin.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 25, ["flags"] = 0 } } },
[30270] = { ["id"] = 30270, ["name"] = "Blinding the Riverblades", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30270 }, ["description"] = "\"A hooded falcon catches no quarry.\" This is one of the first mantras we teach young monks at the temple. It means that even a foe as swift and lethal as a falcon can be neutralized by depriving its senses. The saurok have scouts all over the region acting as eyes for their raiding parties. It's time we put their eyes out, don't you think?", ["objectivesText"] = "Kill 8 Riverblade Pathstalkers in the areas surrounding Crane Wing Refuge.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 27, ["flags"] = 0 } } },
[30271] = { ["id"] = 30271, ["name"] = "Sha Can Awe", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30271 }, ["series"] = { 30272, 30273, 30376, 30695 }, ["description"] = "The sha have the mysterious ability to evoke powerful, often overwhelming, emotional responses in their victims. As we fled the temple, senior members of the Crane Wing order stayed behind to cover our escape. They are no doubt being subjected to intense emotional trauma, and I fear they are not all strong enough to resist falling into despair. $p, we have to show them there is still hope! Show them that despair CAN be defeated!", ["objectivesText"] = "Kill sha near 10 Hopeless Monks or Acolytes to inspire them. Progress: Look for Crane Wing pandaren who are falling to despair and slay sha near them while I support you!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 29, ["flags"] = 0 } } },
[30272] = { ["id"] = 30272, ["name"] = "Striking the Rain", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30272 }, ["series"] = { 30271, 30273, 30376, 30695 }, ["description"] = "Now as for that \"striking the rain\" part... well, sometimes you have to. \"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the eye.\" There seems to be no end to the sha pouring out of the temple. But in order to see beyond the veil of despair, you must carve through it. With any luck, you'll find a sun behind the clouds...", ["objectivesText"] = "Kill 18 Haunts of Despair at the Temple of the Red Crane. Progress: We shouldn't press further into the temple before clearing out some of the sha presence outside.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 31, ["flags"] = 0 } } },
[30273] = { ["id"] = 30273, ["name"] = "In the House of the Red Crane", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30273 }, ["series"] = { 30271, 30272, 30376, 30695 }, ["description"] = "\"Broken are the bodies wherein hopeless hearts reside - the blight of despair strikes forth from inside.\" This was the last piece of wisdom the Red Crane imparted to me, just hours before the Sha outbreak. It makes sense now... $p, when the Sha attacked, they broke forth from the temple's basement... All of his teachings - the very Way of the Crane itself... it's all been preparation for facing the Sha of Despair . The Red Crane has been expecting this conflict for centuries!", ["objectivesText"] = "Enter the basement of the Temple of the Red Crane and defeat the Sha of Despair .", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 81485, 81486, 81487, 81488, 81489, 81490, 81491, 81492, 81493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 35, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 32, ["flags"] = 0 } } },
[30274] = { ["id"] = 30274, ["name"] = "The Arcanic Oubliette", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30274 }, ["description"] = "An Alliance member? Here? Elune be praised. My team has encountered a snag. We opened a portal to this land using some ancient scrolls we had found that predated Azshara's rule. Unfortunately, the coordinates provided on the tablets were warded and the portal that meant to take us to our destination landed us in this oubliette. We have been trapped here for days, and it is slowly leaching our energies to power itself. Can you find the nearby shackles that bind the oubliette and disable them?", ["objectivesText"] = "Find and disable the 3 Oubliette Shackles.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 0, ["flags"] = 0 } } },
[30349] = { ["id"] = 30349, ["name"] = "Threat from Dojan", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30349 }, ["description"] = "While you were at the ruins dusting off tablets for my father I lost five scouts to wandering mogu patrols. These creatures apparently have little interest in peace and are about as trustworthy as the Horde. They are too numerous and we are too weak, however. Go to the ruins west of here and cull the mogu numbers. They won't be expecting a <class>.", ["objectivesText"] = "Kill 6 Dojani Reclaimers , 8 Dojani Surveyors , and 4 Dojani Enforcers .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 84281, 84282, 84283, 84284, 84285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 5, ["flags"] = 0 } } },
[30356] = { ["id"] = 30356, ["name"] = "Sever Their Supply Line", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30356 }, ["series"] = { 30354, 30359, 30360, 30363, 30445, 30465 }, ["description"] = "The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing in reinforcements and supplies. What is worse, they are sending their captives through these portals. Go to the Ruins of Korja and destroy as many of these Korjan Reclaimers as you can find.", ["objectivesText"] = "Kill 8 Korjan Reclaimers .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 47, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 13, ["flags"] = 0 } } },
[30357] = { ["id"] = 30357, ["name"] = "The Stoneplow Convoy", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30357 }, ["description"] = "Help me, $p. These poor pandaren are in need of healing, and my powers are weakened. I did find an old tome in my collection that allowed me to convert the herbs you collected earlier into a healing poultice. Use this on the injured pandaren and it should get them back on their feet.", ["objectivesText"] = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys . Progress: These mantid are a much bigger threat than I think even the pandaren give them credit for.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79163, 84291, 84292, 84293, 84294, 84295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 49, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 15, ["flags"] = 0 } } },
[30363] = { ["id"] = 30363, ["name"] = "Going on the Offensive", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30363 }, ["series"] = { 30354, 30356, 30359, 30360, 30445, 30465 }, ["description"] = "Ha! So my father just wasted twenty years of our lives on a fool's errand! I'm taking charge. When Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it. I want you to look for my scout. I sent her to investigate the Crane Temple but she hasn't returned. Get her report and rendezvous with us at the Sentinel Basecamp further west.", ["objectivesText"] = "Get Incursion Sentinel's Report. Progress: Did you find the scout?", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 79332 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 43, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 9, ["flags"] = 0 } } },
[30376] = { ["id"] = 30376, ["name"] = "Hope Springs Eternal", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 376, ["storyline"] = { 30376 }, ["series"] = { 30271, 30272, 30273, 30695 }, ["description"] = "The Shado-Pan are likely dealing with similar outbreaks elsewhere in Pandaria. Seek out Loon Mai , the Shado-Pan Watch Commander in Stoneplow on the western end of the Valley of the Four Winds . Let him know that we have the situation here under control; the Shado-Pan need not send any aid. Quite the opposite, in fact - I will be sending many of my followers on pilgrimage, to bring a message of hope to those in need. Thank you again, $p. Farewell.", ["objectivesText"] = "Speak with Loon Mai in Stoneplow.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 34, ["flags"] = 0 } } },
[30384] = { ["id"] = 30384, ["name"] = "Blind Them!", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30384 }, ["description"] = "Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not long before you arrived. I don't know how he got here but I can guarantee you he isn't alone. They never are. Kill the sunwalker scout before he reports our position.", ["objectivesText"] = "Kill the Sunwalker Scout .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 3, ["flags"] = 0 } } },
[30445] = { ["id"] = 30445, ["name"] = "The Waters of Youth", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30445 }, ["series"] = { 30354, 30356, 30359, 30360, 30363, 30465 }, ["description"] = "She is headstrong, my little Lyalia . I should have known she would try to challenge the Lord Reclaimer. Since her mother died, I forsook much of the time I should have spent with her in search of immortality, insisting that we could live forever, together. And now my obsession has cost my little Lyalia her life. Please, $p, when she wakes, tell her I love her.", ["objectivesText"] = "Give Vaeldrin's message to Lyalia .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81449, 81450, 81451, 81452, 81453, 81454, 81455, 81456, 81457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 51, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 17, ["flags"] = 0 } } },
[30457] = { ["id"] = 30457, ["name"] = "Call Out Their Leader", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 390, ["storyline"] = { 30457 }, ["series"] = { 31254, 31255 }, ["description"] = "Clearly, you are a hero come to aid us. Slay the Bataari Tribe in the Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to appear. Dispatch him.", ["objectivesText"] = "Slay 10 Bataari Tribe Members in the Kun-Lai Pass until the Bataari Fire-Warrior appears. Then kill him. Progress: If the war leader of the yaungol is slain, surely our village will be saved and the refugees will be able to return to their farms.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 84537, 84538, 84539, 84540, 84541, 84542, 90467, 90468, 90623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 0, ["flags"] = 0 } } },
[30460] = { ["id"] = 30460, ["name"] = "Hit Medicine", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30460 }, ["series"] = { 30509, 30510, 30511, 30513, 30515 }, ["description"] = "Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to the northwest. Take this liniment. It is a powerful medicine that has been passed down in my family over the generations. Use the dit da jow to heal the injured warriors if you do not have healing powers of your own to use on them.", ["objectivesText"] = "Use the Dit Da Jow or your own healing to aid 8 Injured Binan Warriors . Progress: There are yet more injured warriors in need of aid, <class>.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79819 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 2, ["flags"] = 0 } } },
[30461] = { ["id"] = 30461, ["name"] = "Into the Wilds", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30461 }, ["description"] = "Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here. The temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", ["objectivesText"] = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 24, ["flags"] = 0 } } },
[30462] = { ["id"] = 30462, ["name"] = "Into the Wilds", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30462 }, ["description"] = "Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here. The temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", ["objectivesText"] = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 26, ["flags"] = 0 } } },
[30465] = { ["id"] = 30465, ["name"] = "Going on the Offensive", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30465 }, ["series"] = { 30354, 30356, 30359, 30360, 30363, 30445 }, ["description"] = "Ha! So my father just wasted twenty years of our lives on a fool's errand! I'm taking charge. When Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it. We are pressing westward and could use your help. Meet us at the Sentinel Basecamp further west when you are ready.", ["objectivesText"] = "Speak with Lyalia at the Sentinel Basecamp in the Krasarang Wilds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 44, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 10, ["flags"] = 0 } } },
[30468] = { ["id"] = 30468, ["name"] = "Enraged Vengeance", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30468 }, ["description"] = "<The Swordmistress does not look well. There's a darkness to her eyes uncharacteristic of the pandaren.> I don't think I've ever been as... as furious as now. What betrayal! I fought them off when they attacked, killed a few here, but Merchant Shi is too much of a coward to let me go and finish the job! You, do it for me. Kill them. Kill them all.", ["objectivesText"] = "Kill 15 Enraged Jinyu. Progress: Are they dead?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 84528, 84529, 84530, 84531, 84532, 84533, 84534, 84535, 84536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 3, ["flags"] = 0 } } },
[30469] = { ["id"] = 30469, ["name"] = "Repossession", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30469 }, ["description"] = "Of course, the first priority is finding my son. But, if we save ourselves only to starve, then what have we accomplished, in the end? Please, I need you to recover some of the supplies that the Jinyu took from our caravan.", ["objectivesText"] = "Collect 8 Stolen Supplies . Progress: Have you found the supplies?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30480] = { ["id"] = 30480, ["name"] = "The Ritual", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30480 }, ["series"] = { 30496, 30828, 30855, 30967 }, ["description"] = "From the moment I first rose from the river, I knew I was destined to be Waterspeaker. I was taught many rituals, and have performed all of them, save one. There was one, an extremely ancient one, that we were told to call upon if our people ever turned against us. This must have happened in our people's distant past, because we haven't needed to use it in our village's memory. I suppose now is the time to do so.", ["objectivesText"] = "Speak with Waterspeaker Gorai , and then complete the Ritual. Progress: That... was not what I expected.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 13444, 13446, 19182, 52615, 52664, 55126, 57329, 57330, 57331 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 6, ["flags"] = 0 } } },
[30484] = { ["id"] = 30484, ["name"] = "Gauging Our Progress", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30484 }, ["series"] = { 30499 }, ["description"] = "The time for war is at hand, <name>! We've been training these natives non-stop since you left, and I believe they're as good as they're going to get. See for yourself. Check in with the others and return with your findings. We must rely on our enemy being somehow... even less prepared.", ["objectivesText"] = "Check in with Shademaster Kiryn, Rivett Clutchpop, Shokia, and Riko. Progress: How is our combat training coming along?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80013, 80014, 80015, 80061 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 76, ["flags"] = 0 } } },
[30485] = { ["id"] = 30485, ["name"] = "Last Piece of the Puzzle", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30485 }, ["series"] = { 30500, 31303, 31362 }, ["description"] = "These hozen are behaving most unnaturally, <name>. Marching in formation? In armor? This troubles me. We must discuss it at another time, however. I have come to ask for your assistance. The ancient fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to remember. My meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.", ["objectivesText"] = "Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook. Speak with Mishi for transportation.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80071 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 77, ["flags"] = 0 } } },
[30487] = { ["id"] = 30487, ["name"] = "Comin' Round the Mountain", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30487 }, ["series"] = { 30683, 30684, 30795, 30796, 30829, 31306 }, ["description"] = "The mountain pass is very dangerous. You need much luck to survive. Nephew Bentnail will show you the way. Perhaps today is a lucky day to travel though. Wind blows from the east; this is good sign. Grummles always travel best when east wind blows. Climb in the cart when you are ready to leave.", ["objectivesText"] = "Escort the cart and guides safely up Neverest Mountain.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 39, ["flags"] = 0 } } },
[30488] = { ["id"] = 30488, ["name"] = "The Missing Muskpaw", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30488 }, ["series"] = { 30491, 30492, 30808, 31456, 31457 }, ["description"] = "What the heck are you supposed to be? A <class>? Never heard of one of them. You here to help or to steal my yaks? Look, if yer' insistin' on helpin' out, go find my boy. He got himself grabbed by a bunch of sprites and probably doesn't even know we lost the ranch. They dragged him off to Pranksters' Hollow south east of here. Go rescue him an' I'll see about giving you a reward of some sort.", ["objectivesText"] = "Find Muskpaw Jr. in Pranksters' Hollow.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 31, ["flags"] = 0 } } },
[30489] = { ["id"] = 30489, ["name"] = "Fresh Needle Scent", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30489 }, ["description"] = "Say, if you really are here to help, I could use me some needles off them sprites in Pranksters' Hollow. The grummles don't believe in luck they can't smell. They'll pay better for yaks that have that fresh needle scent.", ["objectivesText"] = "Gather 100 Pungent Sprite Needles . Progress: Mmm. Nothing like the fresh scent of needle.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 79952 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30491] = { ["id"] = 30491, ["name"] = "At the Yak Wash", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30491 }, ["series"] = { 30488, 30492, 30808, 31456, 31457 }, ["description"] = "Look, my father is crazy. I love him, but he's crazy. These yaungol managed to completely obliterate our ranch and scattered our yaks every which way. If I know my father though, he's going to try to go head to head with the yaungol to get the yaks back. Can you help us round up some of the yaks so my father doesn't do anything stupid? Just ride them over to the Yak Wash so we can clean them up and sell them to the grummles.", ["objectivesText"] = "Bring 6 Escaped Yaks to the Wash Entrance at Lao & Son's Yak Wash. Progress: The grummles always insist they have better luck with cleaned yaks. As long as they pay more I'm not going to argue. We need the gold. Now more than ever.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 32, ["flags"] = 0 } } },
[30492] = { ["id"] = 30492, ["name"] = "Back in Yak", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30492 }, ["series"] = { 30488, 30491, 30808, 31456, 31457 }, ["description"] = "I wasn't lying about your reward. Here, take these washed yaks to the grummle caravan master Eightcoins. You can find him at the Grummle Bazaar west of here. He'll credit us and give you a delivery fee. He may be short, but he is our biggest customer. Return to me if you lose the yaks. More often than not they just come right back here anyway. Once they've been cleaned that is.", ["objectivesText"] = "Bring the Washed Yaks to Lucky Eightcoins at the Grummle Bazaar in Kun-Lai Summit . Return to Muskpaw Jr. if you lose your yaks.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82574, 82575, 82576, 82577, 82578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 34, ["flags"] = 0 } } },
[30495] = { ["id"] = 30495, ["name"] = "Love's Labor", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30495 }, ["series"] = { 29931, 29932, 29997, 30011 }, ["description"] = "Can I trouble you for another favor? We're way behind schedule, and this jade shipment is the last we need to finish the great statue. I've got my hands full, so could you run this ore over to the other foremen? Historian Dinh , Surveyor Sawa , and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is directing production at the top of the statue. We're on a deadline, so make sure you do it fast! Time's a wasting!", ["objectivesText"] = "Deliver the jade to Historian Dinh , Surveyor Sawa , Kitemaster Shoku , and Taskmaster Emi . Progress: Did you deliver the jade in time?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80773, 80774, 80775, 80776, 80777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 68, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 64, ["flags"] = 0 } } },
[30496] = { ["id"] = 30496, ["name"] = "The Waterspeaker's Staff", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30496 }, ["series"] = { 30480, 30828, 30855, 30967 }, ["description"] = "There is great dissent in Inkgill, <race>. Elder Shai Hu drank the sha-corrupted waters of the mere, and forced the others to do the same. When I protested, Orachi of the town guard confiscated my ritual staff and banished me. Now, I am not only an exile, I am unable to speak with the waters that once gave me guidance! I am not a fighter. But if you are, perhaps you can recover my staff from Orachi? He is in town to our north.", ["objectivesText"] = "Recover Waterspeaker Gorai 's Stolen Inkgill Ritual Staff from Orachi in Inkgill Mere. Progress: Have you found the staff?", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 81385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 4, ["flags"] = 0 } } },
[30498] = { ["id"] = 30498, ["name"] = "Get Back Here!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30498 }, ["description"] = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume. I was made to understand that your presence was urgently required, so I took the liberty of arranging your passage. Speak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", ["objectivesText"] = "Report to Admiral Taylor in Pearlfin Village. Provided item:", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["rewardItems"] = { 86068 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 79, ["flags"] = 0 } } },
[30499] = { ["id"] = 30499, ["name"] = "Get Back Here!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30499 }, ["series"] = { 30484 }, ["description"] = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume. I was made to understand that your presence was urgently required, so I took the liberty of arranging your passage. Speak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", ["objectivesText"] = "Return to General Nazgrim at Grookin Hill. Provided item:", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["rewardItems"] = { 86067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[30500] = { ["id"] = 30500, ["name"] = "Residual Fallout", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30500 }, ["series"] = { 30485, 31303, 31362 }, ["description"] = "Pandaria is a mystical land, traveler. It bears repeating that some of its secrets remain hidden, even to Lorewalkers. Sealing those fissures did not mend what has been broken. If the legends are true, it will take much more to release this land from the grasp of the Sha. The aggression of that battle awakened a host of living negative emotions. What you see here is likely the first of many such manifestations. For now, we can only try to diminish their presence here.", ["objectivesText"] = "Destroy 10 Sha Echoes Progress: This, it seems, is only the tip of the iceberg, <name>.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 84, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 79, ["flags"] = 0 } } },
[30502] = { ["id"] = 30502, ["name"] = "Jaded Heart", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30502 }, ["description"] = "The more powerful remnants of that horrible manifestation may be too much for you to handle on your own, <name>. I fear I'd be of little help in terms of actual combat, but I can suggest a solution. The great jade statue was soon to become a living serpent - one of our revered celestials. Its construction imbued it with special powers that may sufficiently weaken these adversaries.", ["objectivesText"] = "Use Celestial Jade Chunks to defeat 6 Sha Remnants . Progress: Do you have the jade, <name>?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80074 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 85, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 80, ["flags"] = 0 } } },
[30504] = { ["id"] = 30504, ["name"] = "Emergency Response", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30504 }, ["description"] = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict. The full extent of their destruction here we cannot yet know. Already it is... unspeakable. Nevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care. These fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", ["objectivesText"] = "Use Cho's Fireworks near General Nazgrim , Shademaster Kiryn , Shokia , and Rivett Clutchpop .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 86467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 81, ["flags"] = 0 } } },
[30506] = { ["id"] = 30506, ["name"] = "Admiral Taylor has Awakened", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30506 }, ["series"] = { 30507, 30508, 30512, 30514 }, ["description"] = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village. He has requested your presence.", ["objectivesText"] = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 3, ["flags"] = 0 } } },
