[30512] = { ["id"] = 30512, ["name"] = "Westwind Rest", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30512 }, ["series"] = { 30506, 30507, 30508, 30514 }, ["description"] = "< Admiral Taylor winces in pain.> Jade Forest was a disaster. Anduin's gone. We lost some good people. We didn't stop the Horde from advancing into the continent. But I think I've found a way to get the locals on our side. You just helped fight off some of these \"yaungol\", no? I hear yaungol sacked Westwind Rest, a local village. We've been told that two groups of survivors have camped out along the road west out of town. We help them out, maybe they'll consider siding with the Allliance.", ["objectivesText"] = "Speak with Farmhand Bo and Elder Tsulan in the Yaungol Advance. Progress: I will not rest until our people are returned and this village rebuilt.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 6, ["flags"] = 0 } } },
[30513] = { ["id"] = 30513, ["name"] = "Eastwind Rest", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30513 }, ["series"] = { 30460, 30509, 30510, 30511, 30515 }, ["description"] = "I am injured, but we can't stop here. The hozen were... unreliable. The pandaren would be much better allies. You have seen the refugees in this village, and heard of the yaungol invasion, no? Well, we've heard from the locals that Eastwind Rest, a nearby village, was destroyed by the Yaungol. Apparently some survivors have gathered along the road out of town. Go. Take the road west. Gather the survivors. We'll help them rebuild. Then, they will see the advantage of joining the Horde!", ["objectivesText"] = "Speak with Farmhand Ko and Elder Shiao in Kun Lai Summit. Progress: I will not rest until our people are returned and this village rebuilt.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 6, ["flags"] = 0 } } },
[30565] = { ["id"] = 30565, ["name"] = "An Unexpected Advantage", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30565 }, ["description"] = "Things seem to be goin' our way more and more lately, <name>. I was out doin some explorin' when I came upon this little beauty. <Sully gestures to the ballista to his right.> Problem is she's one of a set and the other one is still in pieces. I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken some of the gears and bolts. Hey, ye seem to be pretty good at handlin' the natives. Ye wouldn't mind goin' and helpin' ol'Sully out would ye?", ["objectivesText"] = "Retrieve the missing Water-Damaged Gears and Rusty Locking Bolts from the Hozen Ambushers to the East. Progress: Did ye find my missing gears and bolts?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 80176, 80177 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 80, ["flags"] = 0 } } },
[30568] = { ["id"] = 30568, ["name"] = "Helping the Cause", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30568 }, ["description"] = "Welcome back, <name>! It seems the Jinyu have taken to our training even better than I had hoped. We're in the final stages of our preparations now. I need someone to go check in with Amber, Bold Karasshi, and Mishka. See if they need any help to complete their training. You'll find Karasshi and Mishka here in Pearlfin Village. Amber is training recruits in Slingtail Pits to the northwest.", ["objectivesText"] = "Check in with Bold Karasshi, Amber Kearnen, and Mishka. Progress: Is everyone in order and ready to move?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 81, ["flags"] = 0 } } },
[30569] = { ["id"] = 30569, ["name"] = "Trouble on the Farmstead", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30569 }, ["series"] = { 30570, 30571 }, ["description"] = "I... I escaped from Farmer Chow 's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up! Please, go there and help him out. Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", ["objectivesText"] = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 12, ["flags"] = 0 } } },
[30570] = { ["id"] = 30570, ["name"] = "Trouble on the Farmstead", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30570 }, ["series"] = { 30569, 30571 }, ["description"] = "I... I escaped from Farmer Chow 's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up! Please, go there and help him... Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", ["objectivesText"] = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 10, ["flags"] = 0 } } },
[30581] = { ["id"] = 30581, ["name"] = "... and the Pot, Too!", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30581 }, ["description"] = "Sure, I'm willing to help you guys out. But we need to eat, too! I don't even have a pot to cook in! Let alone ingredients to put in it! Here's a list of the things that I need. Now get!", ["objectivesText"] = "Collect 12 Root Vegetables and 1 Cast Iron Pot . Progress: Do you have everything from the list?!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 13444, 13446, 20079, 20080, 20081, 22829, 22832, 23696, 23698, 44785, 44788, 44812, 46723, 46800, 46824, 74856, 80227, 80230, 84001, 84002, 84003, 84004, 84005, 84006, 84007, 84008, 84009, 88398 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 14, ["flags"] = 0 } } },
[30582] = { ["id"] = 30582, ["name"] = "The Late Mrs. Muskpaw", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30582 }, ["series"] = { 30804 }, ["description"] = "This well worn trinket has several markings on it confessing love and adoration from the late Mrs. Muskpaw. Perhaps Lao would like his wife's trinket back.", ["objectivesText"] = "Bring the Muskpaw Keepsake to Lao Muskpaw . Progress: Oh, and what have you there.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80241 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["startItems"] = { 80241 } },
[30583] = { ["id"] = 30583, ["name"] = "Blue Dwarf Needs Food Badly", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 379, ["storyline"] = { 30583 }, ["description"] = "Oi! We need ta' get us some food, if we're gonna survive here for long! Ye' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, at least.", ["objectivesText"] = "Collect 160 Kun-Lai Meaty Bits . Progress: Well... ya' got my meat?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80245 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 10, ["flags"] = 0 } } },
[30587] = { ["id"] = 30587, ["name"] = "Yakity Yak", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30587 }, ["description"] = "For now, the yaungol invaders seem content to steal yaks. Surveying the area, however, you notice they could easily move on the Yak Wash at any moment. Thinning their numbers may help show the yaungol that this area is protected.", ["objectivesText"] = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch. Progress: Them yak stealing, ranch smashing, bad breath yaungols gotta learn a thing or two about attacking decent folk.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 33, ["flags"] = 0 } } },
[30592] = { ["id"] = 30592, ["name"] = "The Burlap Trail: To Burlap Waystation", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30592 }, ["series"] = { 30599, 30600, 30602, 30603, 30604, 30605, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "Bad fortune for grummles today. Hozen have begun to ravage! They attack our supply line to the Serpent's Spine. Can you help? We are not fighters. We are grummles. Good fortune to those who help grummles. Go with a group of grummles to the Burlap Waystation. Keep them safe. Make sure at least one grummle survives. Grummles shall reward. Grummles always reward.", ["objectivesText"] = "Protect a group of grummles travelling to the Burlap Waystation. At least one grummle must survive. If you lose your grummles, you can search the Burlap Trail or return to One Keg and wait for the next group to leave. Progress: Good fortune to friends of grummles.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 59, ["flags"] = 0 } } },
[30593] = { ["id"] = 30593, ["name"] = "Deanimate the Reanimated", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30593 }, ["description"] = "The admiral's asked me to take care of a major problem, but my specialty's in healing, not fighting! The pandaren in the camp here have told me that something is animating the statues to the northeast at Mogujia Will you help me out, <name>? We can't afford to have a fight with an army of statues right now.", ["objectivesText"] = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 86427 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 9, ["flags"] = 0 } } },
[30594] = { ["id"] = 30594, ["name"] = "Deanimate the Reanimated", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30594 }, ["description"] = "I've got much to do here, <name>. I could use your help. There's a place to the northwest. The pandaren here call it Mogujia. Something's causing the statues there to animate, and our pandaren friends here are pretty spooked about it. If they're not dealt with soon, we might have a serious problem. We just moved in. It's not like we can afford to fight a war with an army of statues right now.", ["objectivesText"] = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 9, ["flags"] = 0 } } },
[30599] = { ["id"] = 30599, ["name"] = "A Monkey Idol", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30599 }, ["series"] = { 30592, 30600, 30602, 30603, 30604, 30605, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "Before, grummles keep hozen from ravaging by bribing with food. But now the Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained them to use their idols to get power from sacrifices. They are using them to kill grummles! You must destroy these idols! For every idol, there is a chief. Kill the chief and throw the corpse on their altar.", ["objectivesText"] = "Use the Corpses of Tak Tak , Dak Dak , and Ko Ko on their respective altars. Progress: Hozen are learning that it is most bad fortune to get sacrificed on one's own altar.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80428, 80429, 80430, 88385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 62, ["flags"] = 0 } } },
[30600] = { ["id"] = 30600, ["name"] = "No Pack Left Behind", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30600 }, ["series"] = { 30592, 30599, 30602, 30603, 30604, 30605, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "The Broketooth hozen south of here killed all of my grummles. What is worse, their packages are undelivered. Fortune frowns on a grummlepack undelivered. Please, give my grummles peace on the great trail of beyond and bring their grummlepacks to me. I will see they are delivered.", ["objectivesText"] = "Recover 8 Grummlepacks from Camp Broketooth or The Deeper. Progress: Grummles are a simple people. We are made to explore and deliver.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80307, 88397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 63, ["flags"] = 0 } } },
[30601] = { ["id"] = 30601, ["name"] = "Instant Courage", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30601 }, ["series"] = { 30999, 31459, 31460 }, ["description"] = "It is very bad fortune to travel mountain paths without a good guide. We grummles make the best guides, but many have run away. They fear the mountain pass now. Many good grummles disappear up there. Grummles are good at many things, but are not very brave. Maybe with fire lotus incense you can make them brave. Then they will show you the way.", ["objectivesText"] = "Inspire 3 Hiding Guides in Howlingwind Cavern to help you.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80308 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 36, ["flags"] = 0 } } },
[30602] = { ["id"] = 30602, ["name"] = "The Rabbitsfoot", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30602 }, ["series"] = { 30592, 30599, 30600, 30603, 30604, 30605, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "The Broketooth hozen stole our Rabbitsfoot! He was the grummle with the biggest luckydo. This is very bad fortune indeed. Please, <race>, we need our Rabbitsfoot back. We need his good fortune back. Can you search the Broketooth Outpost for him?", ["objectivesText"] = "Rescue Brother Rabbitsfoot from the Broketooth Outpost.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 60, ["flags"] = 0 } } },
[30603] = { ["id"] = 30603, ["name"] = "The Broketooth Ravage", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30603 }, ["series"] = { 30592, 30599, 30600, 30602, 30604, 30605, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "They took my luckydo! Their leader hozen here, Mo Mo, stole my rabbitsfoot. This is most bad fortune for grummles. My rabbitsfoot is a big luckydo for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is lost. Please can you get it back?", ["objectivesText"] = "Retrieve Rabbitsfoot's Luckydo from Mo Mo. Progress: Grummles named for the luckydo that gives the most fortune to specific grummle. It is most important that hozen not steal a grummle's luck.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81137 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 61, ["flags"] = 0 } } },
[30604] = { ["id"] = 30604, ["name"] = "Breaking Broketooth", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30604 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30605, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "Hozen only ravage when they think their supplies are too few for their number of mouths. Problem is, hozen always have more mouths than food. We have very few grummles these days. It is a hard thing to ask, but can you be a friend to grummles, and destroy some of the Broketooth hozen south of here? It is the only way to prevent them from destroying the landscape.", ["objectivesText"] = "Kill 8 Broketooth Chargers and 6 Broketooth Tossers .", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30605] = { ["id"] = 30605, ["name"] = "Lucky Yakshoe", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30605 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30604, 30607, 30608, 30610, 30616, 30617 }, ["description"] = "While you were gone, I saw a group of grummles coming down the Burlap Trail. It was led by my Brother Yakshoe . But then the Knucklethumps attacked. They took my brother and his grummles north. Please, $p! Save my brother. He always has bad fortune and no luck, but he is my brother. Look for him at the alter in front of Fort Silverback.", ["objectivesText"] = "Rescue Brother Yakshoe .", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88379 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 64, ["flags"] = 0 } } },
[30606] = { ["id"] = 30606, ["name"] = "Thumping Knucklethump", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30606 }, ["series"] = { 30611, 30612 }, ["description"] = "The Knucklethump hozen have new chief, the Ook of Dook. He sees fear in the west, anger in the south, hatred in the north, and yaungols in the east. And so he sets his hozen to ravage, gathering food and supplies for coming famine. They are many Knucklethumps and dangerous. Please, Luckydo, can you defeat their fighters?", ["objectivesText"] = "Slay 8 Knucklethump Smashers or Jibstabbers at Knucklethump Hole. Progress: It is sad so many hozen must die.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88080, 88081, 88082, 88083, 88084, 88085, 88086, 90623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30607] = { ["id"] = 30607, ["name"] = "Hozen Love Their Keys", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30607 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30604, 30605, 30608, 30610, 30616, 30617 }, ["description"] = "The hozen have a yeti! They call it Old Poot Poot and keep it at the back of their cave. Hozen are normally scared of yeti, but now they feed it grummles. They have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti shackles? Bad fortune for hozen if a yeti is loose in their fort.", ["objectivesText"] = "Get the Yeti Shackle Key from Cho Cho the Wicked and release Old Poot Poot . Progress: A luckydo would be wise to never travel near a yeti on a dirty yak.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 65, ["flags"] = 0 } } },
[30608] = { ["id"] = 30608, ["name"] = "The Snackrifice", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30608 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30604, 30605, 30607, 30610, 30616, 30617 }, ["description"] = "They took my grummles! Hozen don't eat grummles, but yeti do. And the Knucklethumps have a yeti. Please rescue my grummles. Cut them down or let them out of cages. Rescue them any way you can.", ["objectivesText"] = "Rescue 5 Imprisoned Grummles by cutting them down or releasing them from cages.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82532, 82533, 82534, 82535, 82536, 82537, 82538, 82539, 82540 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 66, ["flags"] = 0 } } },
[30610] = { ["id"] = 30610, ["name"] = "Grummle! Grummle! Grummle!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30610 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30604, 30605, 30607, 30608, 30616, 30617 }, ["description"] = "Now that grummles are rescued, we need to rescue our supplies. The Ook of Dook is only chief because he has supplies. Go to the Dooker Dome area north west of here. Take some grummles with you. Keep them safe and get them near supply crates. Grummles know what to do from there. Rabbitsfoot and I will meet you there.", ["objectivesText"] = "Lead 5 Packless Grummles to Supply Crates near the Dooker Dome. Progress: Grummles are good at carrying things.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 67, ["flags"] = 0 } } },
[30611] = { ["id"] = 30611, ["name"] = "Unleash The Yeti!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30611 }, ["series"] = { 30606, 30612 }, ["description"] = "Your yeti ride gave me an idea. The Ook of Dook has a pet yeti he named Chomp Chomp. He uses this yeti to scare other hozen in to making him the leader hozen. We need to get rid of that yeti. Go to Dooker Dome northwest of here and defeat some of the Cagemasters so Chomp Chomp is not tied up as much. Yakshoe and I will meet you there with lots of incense and a dirty yak.", ["objectivesText"] = "Kill 4 Cagemasters . Progress: We found a yak. Did you take out some hozen?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 68, ["flags"] = 0 } } },
[30612] = { ["id"] = 30612, ["name"] = "The Leader Hozen", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30612 }, ["series"] = { 30606, 30611 }, ["description"] = "The time has come to face the Ook of Dook . We beat him, and the hozen won't have someone telling them to ravage. Here is the plan: Yakshoe will lead Tassle in to arena and scare away Chomp Chomp . Then, you sneak in and fight the Ook of Dook while his hozen are distracted by the yeti rampaging through their home. We'll meet you back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.", ["objectivesText"] = "Enrage Chomp Chomp and then defeat the Ook of Dook .", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82541, 82542, 82543, 82544, 82545, 82546, 82547, 82548, 82549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 69, ["flags"] = 0 } } },
[30618] = { ["id"] = 30618, ["name"] = "Resupplying One Keg", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30618 }, ["description"] = "If you're looking for the best supplies in Kun-Lai you've come to the right place! Oh sure, it looks a bit empty. Don't let appearances deceive you.. Oh, who am I kidding?! Between the hozen attacks, and the sprites pillaging what few supplies we do get, my stock has dwindled to a dangerous level. If you could help me recover some of my supplies I should have enough to contribute to your journey.", ["objectivesText"] = "Recover 8 Stolen Supplies from Howlingwind Cavern. Progress: Did you manage to get some of my supplies back?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80315, 88062, 88063, 88064, 88065, 88066, 88067, 88068, 88069, 88070 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 37, ["flags"] = 0 } } },
[30619] = { ["id"] = 30619, ["name"] = "Mogu?! Oh No-gu!", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30619 }, ["description"] = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about. Where there are animated statues, there are mogu. I don't know if you've seen one before, but if you haven't... Well, let's just say mogu are bad, bad, news. While you're dealing with whatever else you're doing, you need to get the mogu behind the trouble!", ["objectivesText"] = "Kill the Mogujia Soul-Caller . Progress: Did you find him? Is he dead? No? Oh, man. Don't make me worried!", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 11, ["flags"] = 0 } } },
[30620] = { ["id"] = 30620, ["name"] = "Mogu?! Oh No-gu!", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30620 }, ["description"] = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about. Where there are animated statues, there are Mogu. I don't know if you've seen one before, but if you haven't... Well, let's just say Mogu are bad, bad, news. While you're dealing with whatever else you're doing, you need to get the Mogu behind the trouble!", ["objectivesText"] = "Kill the Mogujia Soul-Caller .", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 11, ["flags"] = 0 } } },
[30621] = { ["id"] = 30621, ["name"] = "They Stole My Luck!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30621 }, ["description"] = "My journeys through Kun-Lai have taught me two things. First, never sneak up on a sleeping yak. Second, having luck on your side is both necessary and hard to come by. The grummles believe in carrying a lucky trinket at all times. In my mind, if one trinket can sometimes bring luck, then many trinkets would guarantee it! After arriving in One Keg my lucky trinkets were stolen by those little menace sprites. I'd be truly grateful if you could retrieve them for me.", ["objectivesText"] = "Return Ji-Lu the Lucky 's Lucky Virmen's Foot , Yak Shoe, Four Winds Clover, and Gold Coin. Progress: Were you able to find my lucky trinkets? One can never have too much good luck.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80316, 80317, 80318, 80319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 38, ["flags"] = 0 } } },
[30622] = { ["id"] = 30622, ["name"] = "The Swarm Begins", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30622 }, ["series"] = { 30625, 30626 }, ["description"] = "Without the wall to protect us, we barely stand a chance. If you hadn't gathered so many people to help us, we wouldn't have a prayer. Check in with Captain Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can on the way there. If we win, we win. If we lose, we go down fighting. For Pandaria!", ["objectivesText"] = "Slay 15 Ik'thik Warriors or Ik'thik Infestors . Progress: Look at the SIZE of that thing...", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 37, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 35, ["flags"] = 0 } } },
[30623] = { ["id"] = 30623, ["name"] = "The Mantidote", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30623 }, ["description"] = "<Mei motions towards the battlefield.> You see those huge mantid commanders out there? They have a strange aura about them. It reminds me of the sadness we saw at Zhu's Watch. Perhaps... they're under the influence of the sha, too? I kept Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use it on the mantid, we can convince them to turn back.", ["objectivesText"] = "Use Ken-Ken's Mask on 5 Ik'thik Wing Commanders, then defeat the Manifestations of Fear that come out.", ["rewardXP"] = 161000, ["rewardItems"] = { 80337, 88580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 36, ["flags"] = 0 } } },
[30624] = { ["id"] = 30624, ["name"] = "It Does You No Good In The Keg", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30624 }, ["description"] = "I been thinkin'. We got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together. There's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two. They might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", ["objectivesText"] = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the night elf settlers.", ["rewardXP"] = 161000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 39, ["flags"] = 0 } } },
[30625] = { ["id"] = 30625, ["name"] = "Students No More", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30625 }, ["series"] = { 30622, 30626 }, ["description"] = "Those five students - the ones who were looking for the Hidden Master - they went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any left. There's dangerous creatures up there near the wall. If you find those students, make sure that they haven't fallen to any of them.", ["objectivesText"] = "Find the martial arts students, then help them defeat an Ik'thik Bloodrager , Egg-Matron, Tendon-Slicer, and Fearmonger.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 40, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 38, ["flags"] = 0 } } },
[30626] = { ["id"] = 30626, ["name"] = "Retreat!", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30626 }, ["series"] = { 30622, 30625 }, ["description"] = "I'm going to withdraw what few forces I have. We may have to fall back to the Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai 's to make. You go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.", ["objectivesText"] = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 41, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 39, ["flags"] = 0 } } },
[30627] = { ["id"] = 30627, ["name"] = "The Savior of Stoneplow", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30627 }, ["series"] = { 30628 }, ["description"] = "That commander speaks hastily. He has the weapon he needs to win this battle. He has YOU. \"But it's too hard,\" you might say. You would be wrong. It is not too hard. NOTHING IS TOO HARD. Go now, <name>. Go, and save Stoneplow!", ["objectivesText"] = "Speak with Miss Fanny at Stoneplow. Then, with her help, defeat the Mantid Colossus. Progress: All is lost, <name>. Pack up your things. We're headed to Halfhill.", ["rewardGold"] = 306000, ["rewardXP"] = 193000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 42, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 40, ["flags"] = 0 } } },
[30628] = { ["id"] = 30628, ["name"] = "The Gratitude of Stoneplow", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 30628 }, ["series"] = { 30627 }, ["description"] = "One last thing, <name>. Don't worry, it's not another favor. You've killed enough mantid today. We recently received a shipment of high-quality armor from Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody more deserving than you. You'll find them on the second floor of the inn, here in town.", ["objectivesText"] = "Find the Commander's Cache and collect your reward.", ["rewardXP"] = 12900, ["rewardItems"] = { 81476, 81477, 81478, 81479, 81480, 81481, 81482, 81483, 81484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376, ["questLines"] = { { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 43, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 41, ["flags"] = 0 } } },
[30648] = { ["id"] = 30648, ["name"] = "Moving On", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30648 }, ["description"] = "Your journey in this land has already proven most eventful, traveler. And mine, it appears, is destined to continue for a time. A chain of events began when your people arrived here, and while some of those happenings are traumatic to behold, I feel there must be a larger purpose behind your presence. For now it is wisest that you leave this place and explore Pandaria's other regions. Speak to me when you are ready to leave.", ["objectivesText"] = "Speak to Fei and travel to Valley of the Four Winds.", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 87, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 82, ["flags"] = 0 } } },
[30650] = { ["id"] = 30650, ["name"] = "Pandaren Prisoners", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30650 }, ["series"] = { 30596 }, ["description"] = "Look, I know the Alliance needs recruits, and there's just not enough of us here right now to make a fighting presence of this town. But I know that the yaungol over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Alliance. What do you say, <name>?", ["objectivesText"] = "Free 8 Pandaren Prisoners .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 16, ["flags"] = 0 } } },
[30651] = { ["id"] = 30651, ["name"] = "Barrels of Fun", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30651 }, ["description"] = "Oh, well now, let's have us some fun, <boyo/girly>! Those Ordo yaungol to the northwest have saved us the trouble o' havin' to make some bombs. They already have them there. Let's put their explosive barrels to good use and destroy their oil-pumpin' machines, shall we?", ["objectivesText"] = "Use Explosive Barrels found in Fire Camp Ordo to destroy the West, South, and East Oil Rigs.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80528, 88577 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 17, ["flags"] = 0 } } },
[30652] = { ["id"] = 30652, ["name"] = "In Tents Channeling", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30652 }, ["series"] = { 30660 }, ["description"] = "The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest and take out their leader. Unfortunately, his four subordinates are maintaining a fire barrier that prevents us from getting to him in the adjoining cave. Take them out and the shield will come down. You'll find them in their tents, channeling.", ["objectivesText"] = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster.", ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 18, ["flags"] = 0 } } },
