[30663] = { ["id"] = 30663, ["name"] = "The Ordo Warbringer", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30663 }, ["description"] = "You've taken the shield down at Fire Camp Ordo. Get back over there before they get that shield up again. Slay the Warbringer of the Ordo!", ["objectivesText"] = "Kill the Ordo Warbringer .", ["rewardGold"] = 306000, ["rewardXP"] = 161000, ["rewardItems"] = { 82589, 82590, 82591, 82592, 82593, 82594, 82595, 82596, 82597, 82598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 20, ["flags"] = 0 } } },
[30665] = { ["id"] = 30665, ["name"] = "The Defense of Shado-Pan Fallback", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30665 }, ["series"] = { 30670, 30690, 30699, 30723, 30724, 30750, 30991, 30994 }, ["description"] = "I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing back. We have already lost the town. A few lucky villagers may have survived, but we are pinned down here. We do not have time to entertain strangers. If you can fight, help my men defend this tower. If not, leave, for you will not survive long here.", ["objectivesText"] = "Kill 15 Sha-Infested Yaungol .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 5373 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 74, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 22, ["flags"] = 0 } } },
[30667] = { ["id"] = 30667, ["name"] = "Particular Plumage", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30667 }, ["description"] = "When the crocs started attacking, they scared a bunch of the lories out of their nests, up in that island to our northwest. I can use those lories' feathers to make some specialized lures, which will come in handy if and when I get to stop defending my brethren from these reptiles. You up for some feather hunting?", ["objectivesText"] = "Obtain 6 Emerald Tailfeathers , 6 Crimson Tailfeathers , and 6 Dusky Tailfeathers . Progress: <A bead of sweat twinkles in the fur above Tony's brow.>", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80677, 80678, 80679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30671] = { ["id"] = 30671, ["name"] = "Wisdom Has A Price", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30671 }, ["series"] = { 30666, 30668, 30669 }, ["description"] = "<Ana listens to your story, and nods.> Crocolisks attacking? I know a story about that. And I will share it with you, but first... I grow hungry. Shark meat should do the trick. You should find enough sharks in the water beneath us.", ["objectivesText"] = "Obtain 5 Shark Fillets . Progress: My hunger is great, <race>. I have been on this lagoon for several days, without food.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80810, 88035, 88036, 88037, 88038, 88039, 88040, 88041, 88042, 88043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 39, ["flags"] = 0 } } },
[30672] = { ["id"] = 30672, ["name"] = "Balance", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30672 }, ["description"] = "The story did not end happily. The Narsong crocolisk is no more. This time, however, you may have a chance to change the ending. The hozen to the south are overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - and so they attack Marista. Go now, <race>! Stop those hozen from their reckless fishing!", ["objectivesText"] = "Slay 10 Unga Fish-Getters .", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 5394, 11187, 81542, 81543, 81544, 81545, 81546, 81547, 81548, 81549, 81550, 81551 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 40, ["flags"] = 0 } } },
[30674] = { ["id"] = 30674, ["name"] = "Balance Without Violence", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30674 }, ["description"] = "Some of the fish that the Unga hozen have gathered don't seem do be dead yet. There may still be time to throw them back into the water.", ["objectivesText"] = "Throw 6 Flailing Carp into Nayeli Lagoon.", ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 41, ["flags"] = 0 } } },
[30675] = { ["id"] = 30675, ["name"] = "Buried Hozen Treasure", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["mapID"] = 418, ["storyline"] = { 30675 }, ["description"] = "The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X on a beach. Is there buried treasure somewhere on this island?", ["objectivesText"] = "Find the Buried Hozen Treasure .", ["rewardXP"] = 129000, ["rewardItems"] = { 80817, 80822, 80827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 42, ["flags"] = 0 } }, ["startItems"] = { 80827 } },
[30682] = { ["id"] = 30682, ["name"] = "Holed Up", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30682 }, ["description"] = "I can't believe you made it here! I don't know how much longer I could have stayed hidden in here. I'm sure that there are others. <class>, we have to rescue them! Then we can go to Shado-Pan Fallback. The master there will know what to do!", ["objectivesText"] = "Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong . Progress: There are survivors out there? Surely there are more, <name>?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 24, ["flags"] = 0 } } },
[30683] = { ["id"] = 30683, ["name"] = "One Traveler's Misfortune", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30683 }, ["series"] = { 30487, 30684, 30795, 30796, 30829, 31306 }, ["description"] = "Did you have to throw our supplies at them?! Why not use your weapon? Maybe fancy spells or kicks? Why the supplies?! Now we don't have enough to last us, especially with Nephew Bentnail here. His appetite is like a yeti's! You threw it, you get us more. There is wreckage down the path. Maybe you will find supplies there.", ["objectivesText"] = "Search the Abandoned Wreckage for supplies. Progress: Nephew Bentnail has already eaten two days worth of food. I hope you found us more!", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 40, ["flags"] = 0 } } },
[30684] = { ["id"] = 30684, ["name"] = "Seeker's Folly", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30684 }, ["series"] = { 30487, 30683, 30795, 30796, 30829, 31306 }, ["description"] = "I'm sure your pandaren friend has some ideas about what the mogu are after. He headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific: \"The <class> must endure the trek alone, with only <his/her> thoughts. <He/She> will honor each shrine before meeting me at the top.\" The path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", ["objectivesText"] = "Brave the path of Seeker's Folly to find Lorewalker Cho , stopping to reflect at the three shrines along the way. Progress: There are two shrines on the path below us, and one more just behind us.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 41, ["flags"] = 0 } } },
[30690] = { ["id"] = 30690, ["name"] = "Unmasking the Yaungol", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30690 }, ["series"] = { 30665, 30670, 30699, 30723, 30724, 30750, 30991, 30994 }, ["description"] = "Simply killing Kobai will accomplish nothing, as he is possessed by a particularly powerful and destructive Sha - Malevolent Fury . You will use the trap I have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take control of you. Defeat him, and we will have made a victory of this tragic situation. You can find him to the north of the retreat, where he taunts us in insane rage.", ["objectivesText"] = "Lure Kobai into the Blinding Rage Trap , steal the Mask of Malevolent Fury from him, and then defeat Malevolent Fury . Progress: Is Malevolent Fury gone?", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 81741, 88071, 88072, 88073, 88074, 88075, 88076, 88077, 88078, 88079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 76, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 25, ["flags"] = 0 } } },
[30691] = { ["id"] = 30691, ["name"] = "Misery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30691 }, ["description"] = "While you are in the water below, you should slay Nahassa , the mortbreath patriarch. He suffers. I can feel his death cries ululating up to the surface of the lagoon. Find his cave, and put him out of his misery. Not because it will solve Marista's crocolisk problem. Simply out of mercy.", ["objectivesText"] = "Put Nahassa out his misery. Progress: Please, <name>. Even the great beasts of this world have a right to die in dignity.", ["rewardXP"] = 193000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30694] = { ["id"] = 30694, ["name"] = "Tread Lightly", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30694 }, ["description"] = "My students tell me the surrounding area is littered with deadly traps, no doubt set by the saurok. Stumbling into one gets you a face full of spikes. As the saying goes: \"The Way is rife with danger - tread lightly, and with scrutiny.\" <Koro hands you a long tree branch.> Here, this is scrutiny. It should be long enough to set the traps off at a safe distance.", ["objectivesText"] = "Use \"Scrutiny\" to set off 10 Riverblade Spike Traps from a safe distance. Progress: Well, I don't see any spikes in your face. That's a good sign.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80828, 84272, 84273, 84274, 84275, 84276, 84277, 84278, 84279, 84280 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 28, ["flags"] = 0 } } },
[30695] = { ["id"] = 30695, ["name"] = "Ahead on the Way", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 30695 }, ["series"] = { 30271, 30272, 30273, 30376 }, ["description"] = "Huge maws of despair are spewing out sha from the pagodas on either side of the temple. Meanwhile, your impromptu training in the Way continues. \"She who mends torn umbrella will be more dry than she who strikes at rain.\" While I take issue with that particular lesson--sometimes punching the rain can be quite effective--the meaning holds true in this case. Take out those maws of despair and give my order a chance at reclaiming the temple grounds.", ["objectivesText"] = "Kill the Maw of Despair in both the eastern and western pagodas at the Temple of the Red Crane. Progress: Koro said there's a pagoda on either side of the temple. Let's find them and wipe out the sha presence in both.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81552, 81553, 81554, 81555, 81556, 81557, 90546, 90547, 90622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5490, ["questLineOrder"] = 2 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5495, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 559, ["name"] = "Krasarang Wilds", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5490, ["name"] = "Krasarang Wilds", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5495, ["name"] = "Krasarang Wilds", ["orderIndex"] = 30, ["flags"] = 0 } } },
[30699] = { ["id"] = 30699, ["name"] = "To Winter's Blossom", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30699 }, ["series"] = { 30665, 30670, 30690, 30723, 30724, 30750, 30991, 30994 }, ["description"] = "The battle against the Sha is eternal - we can not leave this place. But I am troubled by the absence of reinforcements from the Monastery given that we sent for them days ago. You have performed admirably, perhaps you could travel to Winter's Blossom, our base camp on the way to the Shado-Pan Monastery. Speak with Lin Silentstrike once you arrive - he should know what is happening. To get there, travel north of the village and follow the road through Shado-Li Basin to Winter's Blossom.", ["objectivesText"] = "Speak with Lin Silentstrike at Winter's Blossom in Kun-Lai Summit .", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 77, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 26, ["flags"] = 0 } } },
[30715] = { ["id"] = 30715, ["name"] = "A Line Unbroken", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30715 }, ["description"] = "When we regrouped after their initial attack, we numbered three less. You can fight, and we must plan our defense should these cursed yaungol attack again. If you would help us, grant our fallen comrades their last rites, and recover their armor. You will find their bodies to the west, near the gate. And try to keep the birds off them.", ["objectivesText"] = "Lay Shado-Master Zhiyao, Liu of the Thousand Blows and Shiya Boldblade to rest. Progress: Our comrades, are they at rest?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 78, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 27, ["flags"] = 0 } } },
[30723] = { ["id"] = 30723, ["name"] = "Honor, Even in Death", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30723 }, ["series"] = { 30665, 30670, 30690, 30699, 30724, 30750, 30991, 30994 }, ["description"] = "Hmm... If Shado-Master Chong trusted you, perhaps you can help us. The yaungol are our enemies. Still, we must prove we are better than they. We will show them honor in death. As after most battles, the carrion birds have begun gathering. Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered at the battlefield to the west.", ["objectivesText"] = "Kill 12 Kun-Lai Scavengers. Progress: Killing those birds may not soothe my anger, but at least it proves that we are better than our enemies. They would not do such a thing.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 79, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 28, ["flags"] = 0 } } },
[30724] = { ["id"] = 30724, ["name"] = "To the Wall!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30724 }, ["series"] = { 30665, 30670, 30690, 30699, 30723, 30750, 30991, 30994 }, ["description"] = "They are attacking again! <Lin looks to the Ox Gate.> Archers... on the wall! I need you to get up there. My wife Suna went to scout the wall with that fool Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that ridiculous ale lift contraption... It matters not. Get a kite from Len, to the west, and then get up there and find my wife. She'll know what to do next.", ["objectivesText"] = "Speak to Kite Master Len at Winter's Blossom in Kun-Lai Summit to take a kite up to the Ox Gate. Once there, speak to Suna Silentstrike . Progress: Lin sent you for me? How sweet.", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 80, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 29, ["flags"] = 0 } } },
[30742] = { ["id"] = 30742, ["name"] = "Shut it Down", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30742 }, ["description"] = "I mussed up. Bad. It's hard work cutting seeds out of kafa berries! But I noticed goots eat the berries up and give back the seeds... in a day or so. I fed everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves. Kota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", ["objectivesText"] = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak. Progress: I shoulda never fed them goots.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 30365, 30366, 30377, 30378, 57442, 57443 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30743] = { ["id"] = 30743, ["name"] = "Gourmet Kafa", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30743 }, ["description"] = "It was genius: kafa berries go in the goot, seeds come out. Kafa'kota is already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET. But its over now. Uncle is upset and peak is a muss. All thats left is to collect the rest of the Kafa'goot and never make it again. I won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so I can find it easily when the mountain is safe again.", ["objectivesText"] = "Mark 10 Kafa'goot \"Deposits\" on Kota Peak.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88382 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30744] = { ["id"] = 30744, ["name"] = "Kota Blend", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30744 }, ["series"] = { 30746, 30825 }, ["description"] = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation. Grummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming. Kafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves. I pay you good for any berries you bring down from Kota. Here, take a sample. Eat it. See for yourself the power of kafa.", ["objectivesText"] = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.", ["rewardXP"] = 162000, ["rewardItems"] = { 81054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 71, ["flags"] = 0 } } },
[30745] = { ["id"] = 30745, ["name"] = "Trouble Brewing", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30745 }, ["description"] = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots. Then they ate the goots full of kafa... <Keenbean shoots Gootfur a mean glance.> Now they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts. Gonna come outta those caves soon, I'm sure. Come lookin' for more kafa. Then we all in trouble.", ["objectivesText"] = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 87301, 87302, 87303, 87304, 87305, 87306, 87307, 87308, 87309, 88578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30746] = { ["id"] = 30746, ["name"] = "A Fair Trade", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30746 }, ["series"] = { 30744, 30825 }, ["description"] = "<The roar bellows out again, louder and more fierce than any of the yetis you've encountered so far. Again, a grummle voice replies...> Eep! Please, great Kota Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise! <The beast called Kota Kon answers with another meaty roar.>", ["objectivesText"] = "Bring the Bundle of Kafa'kota Berries to the Lair of Kota Kon, near the top of Kota Peak. Progress: Kota Kon wants more kafa, but I already fed her all I have! Then I tried giving her a nice bow, but she's not satisfied! <The terrified grummle gulps and leans in close to whisper.> I think she can smell the kafa I drank for breakfast...", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 18042, 80944 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 72, ["flags"] = 0 } } },
[30747] = { ["id"] = 30747, ["name"] = "The Burlap Grind", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30747 }, ["description"] = "Okayyy... well, she's not eating anybody. That's a good start. She must want more kafa, but we gotta give her somethin' to do with all the extra energy... I got it! The Burlap Trail! She can smash hozen out there all day! <Burrberry turns to the massive beast.> What do you think, pretty girl? Wanna smash hozens?! I think so. Here, feed her my emergency flask of kafa . She likes you.", ["objectivesText"] = "Feed the Flask of Kafa to Kota Kon at Kota Basecamp, then kill 100 Hozen along The Burlap Trail. Progress: Don't push our luck... we promised her hozens-smashies.", ["rewardGold"] = 212000, ["rewardXP"] = 203000, ["rewardItems"] = { 81183, 82523, 82524, 82525, 82526, 82527, 82528, 82529, 82530, 82531, 97980 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 73, ["flags"] = 0 } } },
[30750] = { ["id"] = 30750, ["name"] = "Off the Wall!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30750 }, ["series"] = { 30665, 30670, 30690, 30699, 30723, 30724, 30991, 30994 }, ["description"] = "The yaungol on the wall here are providing covering fire for the ones below. I don't know what Lao-chen is thinking, but I want you to deal with these archers. The good news is, up here we've got the spirit of the Ox helping us. When they're weakened, the ox spirit will stun them and you can use it to knock 'em off the wall. You'll find the archers just out that door.", ["objectivesText"] = "Kill 12 Osul Veteran Archers or Osul Fire-Warriors.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 81, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 30, ["flags"] = 0 } } },
[30751] = { ["id"] = 30751, ["name"] = "A Terrible Sacrifice", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30751 }, ["series"] = { 30765 }, ["description"] = "I have an idea, and... am prepared to make a terrible sacrifice. As much as I know that we need my stout brew, to fortify our defenders for the long-term security of the Ox Gate... It is too painful to discuss details now, but please - while you are up here defending the wall, gather the barrels of oil they are using to light their arrows. We will need them.", ["objectivesText"] = "Gather 6 Barrels of Yaungol Fire Oil. Progress: Do you have the oil?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82799 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 82, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 31, ["flags"] = 0 } } },
[30752] = { ["id"] = 30752, ["name"] = "Unbelievable!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30752 }, ["series"] = { 30757, 30759, 31030, 31031 }, ["description"] = "I simply refuse to believe the guards will not grant us entry to the monastery should we impress upon them the seriousness of the situation. Friend, go east, to the sentinel in front of the Monastery, and demand admittance. I will come with you.", ["objectivesText"] = "Speak to the Shado-Pan Monastery Sentinel to gain entrance to the Shado-Pan Monastery. Progress: Unbelievable!", ["rewardGold"] = 212000, ["rewardXP"] = 203000, ["rewardItems"] = { 82559, 82560, 82561, 82562, 82563 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 87, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 36, ["flags"] = 0 } } },
[30768] = { ["id"] = 30768, ["name"] = "My Husband...", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30768 }, ["description"] = "Lin... I don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit around waiting for everyone else to catch up. Once Taran Zhu opens the doors to his precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's alright.", ["objectivesText"] = "Meet up with Suna Silentstrike at Longying Outpost in the Townlong Steppes .", ["rewardGold"] = 55000, ["rewardXP"] = 98000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30769] = { ["id"] = 30769, ["name"] = "First Assault", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30769 }, ["series"] = { 30772 }, ["description"] = "Now that we have had time to assess our enemies' weaknesses, it is time for us to deal the yaungol a direct blow. Go and confront the Osul Sharphorn up the mesa to the west. Let them know that we are here, and that we are not scared of their threats.", ["objectivesText"] = "Kill 6 Osul Sharphorns .", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 88087, 88088, 88089, 88090, 88091, 88092, 88093, 88094, 88095 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 1, ["flags"] = 0 } } },
[30770] = { ["id"] = 30770, ["name"] = "Running Rampant", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30770 }, ["description"] = "There is one thing that every army needs, and that is a supply line. The enemy camp to the west contains a large beast herd, which serves as the yaungol army's main source of food. Luckily for us, the yaks and mushan beasts of this region are easily scared. Sneak in, give the beasts a good slap, and watch the results.", ["objectivesText"] = "Scare 8 Long-Haired Yaks or Steppebeasts.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 2, ["flags"] = 0 } } },
[30771] = { ["id"] = 30771, ["name"] = "Perfect Pitch", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30771 }, ["series"] = { 30773 }, ["description"] = "When the Osul tribe goes to war, they coat their spears and arrows with a highly flammable, ever-burning pitch. They use this terrible weapon to shed not only blood, but to raze the homes of their enemies. I need you to collect some of this pitch while you are in their camp. We will use it to show the yaungol that when you play with fire, you can get burned.", ["objectivesText"] = "Collect 8 Dark Pitch . Progress: The yaungol are not content merely to defeat their enemies. No, they would rather destroy and decimate them.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 3, ["flags"] = 0 } } },
[30772] = { ["id"] = 30772, ["name"] = "Seeing Red", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30772 }, ["series"] = { 30769 }, ["description"] = "Ahead of us is the main thrust of the yaungol army. Here, they prepare their vast army to attack the villages of Kun-Lai. If we strike at the Osul now, we can cut them at their very core. Remember, for every of their number that we strike down here, we save one of our own back at home.", ["objectivesText"] = "Kill 8 Osul Marauders or Osul Spitfires.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83671, 83672, 83673, 83674, 83675, 83676, 83677, 83678, 83679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 4, ["flags"] = 0 } } },
[30773] = { ["id"] = 30773, ["name"] = "Pitching In", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30773 }, ["series"] = { 30771 }, ["description"] = "The yaungol's siege weapons - those ballista spearthrowers down there - are tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit. Those terrible weapons must be destroyed. Take these explosives. I've covered them in the pitch that you collected. Toss them at those ballistas, and we'll give the yaungol a little taste of their own medicine.", ["objectivesText"] = "Use Ban's Explosives to destroy 6 Osul Ballistas. Progress: Fire is a cruel weapon. Luckily, we are only using it to destroy weapons of war.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81193, 88583 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 5, ["flags"] = 0 } } },
[30774] = { ["id"] = 30774, ["name"] = "Ranger Rescue", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30774 }, ["description"] = "I must ask a most important task of you, <name>. Somewhere among the cages in the Osul camp is my husband, Lin. He is the light of my world. Please find him and return him to me, and save as many of our fellow Shado-Pan as you can as well. You should find keys to those cages on the Osul Marauders.", ["objectivesText"] = "Unlock Drywood Cages to save 4 Longying Rangers and Lin Silentstrike .", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81178 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 6, ["flags"] = 0 } } },
[30775] = { ["id"] = 30775, ["name"] = "The Exile", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30775 }, ["description"] = "What is there to say, stranger? I fought Jung Duk and lost. I was the fool to believe he would fight fairly. Now, my own brothers turned against me, and here I am, speaking to our enemies. I know you have come for Osul blood. I only ask that you hunt down the three who betrayed me. Urang , who poisoned my drink. Ku-Tong , who bent my spear. And Battat , whose dagger slipped into my side as my victory was assured. Do this, and I can die in peace.", ["objectivesText"] = "Kill Urang , Ku-Tong , and Battat . Progress: How could they have betrayed me? They were once my brothers! Why did they turn on me? WHY? I hate them! I will slaughter them all!", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 6851, 53263, 53271, 53280 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 7, ["flags"] = 0 } } },
[30776] = { ["id"] = 30776, ["name"] = "Jung Duk", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30776 }, ["series"] = { 30777 }, ["description"] = "THIS. IS. WAR. I will have the heads of everyone who took Lin from me. EVERYONE! We will begin with the Osul leader, Jung Duk . Take this Shado-Pan war banner and place it at the center of their camp. Jung Duk will have no choice but to face you. Show him no mercy, <name>.", ["objectivesText"] = "Plant the Shado-Pan Banner on the Ceremonial Pile, then kill Jung Duk . Progress: Jung Duk 's legacy is written in the blood of innocents.", ["rewardGold"] = 220000, ["rewardXP"] = 245000, ["rewardItems"] = { 83689, 83690, 83691, 83692, 83693, 83694, 83695, 83696, 83697 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 8, ["flags"] = 0 } } },
[30777] = { ["id"] = 30777, ["name"] = "In Search of Suna", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30777 }, ["series"] = { 30776 }, ["description"] = "I have bad news. When I returned, Suna was already gone. The others say that she took her things and headed down the road to the east, muttering about hunting down the source of the yaungol aggression. I cannot allow her to venture into dangerous territory alone. I've already prepared a group of soldiers to push further east. We are leaving shortly. Hop on the caravan if you wish to travel with the Shado-Pan. You can also meet us there if you wish.", ["objectivesText"] = "Speak to Ban Bearheart after arriving at Hatred's Vice.", ["rewardGold"] = 55000, ["rewardXP"] = 98000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 9, ["flags"] = 0 } } },
[30778] = { ["id"] = 30778, ["name"] = "Dust to Dust", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 390, ["storyline"] = { 30778 }, ["description"] = "If we are to make camp here, we cannot leave all of these yaungol bodies lying to rot. Take this torch and set fire to the villagers' corpses. The incense from the torch should purify the earth and air around them as well. Even our enemies deserve to be laid to rest.", ["objectivesText"] = "Use the Shado-Pan Torch on 20 Palewind Villagers . Progress: The stench of death is overpowering.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 1191, 22778, 32446, 38718, 38751, 39022, 39051, 39089, 57400, 57401, 62895, 62896, 62897, 81356, 87361, 87362, 87363, 87364, 87365, 87366, 87367, 87368, 87369, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 10, ["flags"] = 0 } } },
[30779] = { ["id"] = 30779, ["name"] = "Slaying the Scavengers", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 390, ["storyline"] = { 30779 }, ["description"] = "The rotting corpses are attracting hyena scavengers. In addition to spreading diseases from feeding on the dead, the feral creatures will attack us on sight. Go and eradicate the beasts. It is unfortunate, but ultimately for the best.", ["objectivesText"] = "Kill 8 Ashfang Hyenas . Progress: It is better to be safe than sorry.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 11, ["flags"] = 0 } } },
[30780] = { ["id"] = 30780, ["name"] = "Totemic Research", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30780 }, ["series"] = { 30827 }, ["description"] = "As we entered the village, I couldn't help but notice yaungol totems lying around this camp. I have a suspicion that there are dark forces at work here, and those totems may be the key to drawing them out. Could you bring me some of these totems for further inspection? I would like to study them.", ["objectivesText"] = "Collect 9 Palewind Totems . Progress: I do believe the totems could be of use to us.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81355 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 12, ["flags"] = 0 } } },
[30781] = { ["id"] = 30781, ["name"] = "Last Toll of the Yaungol", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30781 }, ["description"] = "Ban has asked me to explore the village to determine what happened here. I noticed smoke rising up from the east, the west, northwest, and the south. I need someone I trust to watch my back. What do you say? Want to help me on my first scouting mission?", ["objectivesText"] = "Take Xiao Tu to the smoke trails at Hatred's Vice. Progress: Something terrible must have happened here.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83746, 83747, 83748, 83749, 83750, 83751, 83752, 83753, 83754, 83755 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 13, ["flags"] = 0 } } },
[30782] = { ["id"] = 30782, ["name"] = "Spiteful Spirits", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 390, ["storyline"] = { 30782 }, ["description"] = "The spirits of the fallen villagers have risen! I can feel the hatred emanating from the spirits. <name>, if we are to survive here, we must defend ourselves. This is the only way we can put them to rest.", ["objectivesText"] = "Kill 10 Spiteful Spirits . Progress: The air is thick with their malicious intent.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81430 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 15, ["flags"] = 0 } } },
[30783] = { ["id"] = 30783, ["name"] = "Hatred Becomes Us", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30783 }, ["description"] = "I should have suspected a sha presence earlier! We are safe as long as we stand inside the Totem of Harmony 's protective wards, but many of our people were not so lucky. They were trapped outside the camp when the sha's powers manifested, and now they turn upon each other! Take one of my totems with you. Place the totem near a crazed ally to purify them, but beware. You may have to face the darkness that gripped them.", ["objectivesText"] = "Use the Totem of Harmony to exorcise sha spirits from 8 Crazed Shado-Pan Rangers. Defeat the Seething Hatreds to purify your allies. Progress: Our people are possessed by hatred. We must help them come to their senses!", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81417, 81430, 88584 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 16, ["flags"] = 0 } } },
[30784] = { ["id"] = 30784, ["name"] = "The Point of No Return", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 390, ["storyline"] = { 30784 }, ["series"] = { 30785 }, ["description"] = "One of our rangers reported seeing Suna up the hill to the northwest. I am relieved to find her safe. I had feared what she would do in her grief. Would you go speak to her on my behalf? Take this totem with you. If you encounter any danger along the way, you may find it useful.", ["objectivesText"] = "Find Suna Silentstrike . Progress: If I could change the past, I would. If I could take Lin's place, I would. In a thousand lifetimes, I will never be able to repay Suna's loss, or share even a measure of her grief.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81430, 83662, 83663, 83664, 83665, 83666, 83667, 83668, 83669, 83670 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 17, ["flags"] = 0 } } },
[30785] = { ["id"] = 30785, ["name"] = "Gao-Ran Battlefront", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30785 }, ["series"] = { 30784 }, ["description"] = "With your help, we have quelled the spirits of this place. At last, they may rest in peace. Our journey into this cursed land, I am afraid, has only begun. I have some important matters to finish up here, but we will be moving out soon. I need someone to go ahead and tell Lord Taran Zhu that we are joining him. Find him at the Gao-Ran Battlefront. Tell him what has transpired here.", ["objectivesText"] = "Speak to Lord Taran Zhu at the Gao-Ran Battlefront in the Townlong Steppes .", ["rewardGold"] = 55000, ["rewardXP"] = 98000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30786] = { ["id"] = 30786, ["name"] = "A Spear Through My Side, A Chain Through My Soul", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30786 }, ["series"] = { 30787, 31894 }, ["description"] = "My fate is sealed. The yaungol put this spear in my side. The wound will kill me. The yaungol hold me in place with their twisted, corrupted magic. The indignity of it hurts worse than my spear-wound. My death, I cannot stop. My imprisonment... you may be able to help me with this.", ["objectivesText"] = "Slay Dmong Naruuk , the shaman who holds Orbiss hostage. Progress: I will not die before having my revenge.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 17, ["flags"] = 0 } } },
[30787] = { ["id"] = 30787, ["name"] = "The Torches", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30787 }, ["series"] = { 30786, 31894 }, ["description"] = "Until recently, the yaungol shaman would come here to work alongside us. Now, they bend my people to their will. If we refuse, they kill us. Even if we oblige... they kill us. The yaungol mist-shaman's magic flows through his torch. Take his torch away, and he has nothing.", ["objectivesText"] = "Obtain 6 Mist-Shaman's Torches. Progress: I can use these torches in my revenge. I have not succumbed to this wound yet. I can still have my revenge before I die. There is time yet.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81176, 84605, 84606, 84607, 84608, 84609 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 18, ["flags"] = 0 } } },
[30788] = { ["id"] = 30788, ["name"] = "Golgoss", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30788 }, ["series"] = { 30789, 30815 }, ["description"] = "The leader of the yaungol mist-shaman is named Jahesh. He is known for his strength. One of my kind is also known for his strength. His name is Golgoss . Golgoss sleeps within the mists of the Upper Sumprushes. Help me to summon him, and he will join me in avenging our people.", ["objectivesText"] = "Summon Golgoss by planting the Mist-Shaman's Torches into the Peat Clump in the Upper Sumprushes.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 19, ["flags"] = 0 } } },
[30789] = { ["id"] = 30789, ["name"] = "Arconiss", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30789 }, ["series"] = { 30788, 30815 }, ["description"] = "If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have Arconiss by my side. Arconiss ' ferocity is second to none. He rests beneath the mists of the Upper Sumprushes. Find his resting place, and then use these torches to awaken him.", ["objectivesText"] = "Summon Arconiss by planting the Mist-Shaman's Torches into the Peat Mound in the Upper Sumprushes. Progress: Arconiss ' size belies his prowess in battle. He will be an asset.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 20, ["flags"] = 0 } } },
[30790] = { ["id"] = 30790, ["name"] = "Golgoss Hungers", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30790 }, ["description"] = "Golgoss' strength is great, but he requires nutrition before he can use it. The snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These should sate his appetite.", ["objectivesText"] = "Obtain 10 Snarlvines . Progress: Golgoss' hunger is great.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81250 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 22, ["flags"] = 0 } } },
[30791] = { ["id"] = 30791, ["name"] = "Arconiss Thirsts", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30791 }, ["description"] = "Arconiss fights with unmatched fury, but his extended stay beneath the mists has left him weakened. The rodents of the swamp are plentiful, and their bodies are filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.", ["objectivesText"] = "Obtain 4 Clotted Rodent's Blood . Progress: Our preparation will not take much longer.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81260 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 23, ["flags"] = 0 } } },
[30792] = { ["id"] = 30792, ["name"] = "Orbiss Fades", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30792 }, ["description"] = "I knew death would come. I did not know that it would come this fast. I must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is nutritive to my kind. Gather this mist however you can... in jars, in vials, within the interior of your bags. Bring it back to me, and I can use it to remain corporeal for a bit longer.", ["objectivesText"] = "Obtain 8 Gushing Mists by walking through mist geysers in the Upper Sumprushes.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 24, ["flags"] = 0 } } },
[30793] = { ["id"] = 30793, ["name"] = "Mists' Opportunity", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30793 }, ["description"] = "Now is the time to strike. Golgoss, Arconiss, and I will go east, into Jahesh's domain. Meet us there, and prepare for battle. Today, we restore the pride of our people.", ["objectivesText"] = "Slay Jahesh of Osul .", ["rewardGold"] = 220000, ["rewardXP"] = 245000, ["rewardItems"] = { 83653, 83654, 83655, 83656, 83657, 83658, 83659, 83660, 83661 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 25, ["flags"] = 0 } } },
[30795] = { ["id"] = 30795, ["name"] = "Staying Connected", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30795 }, ["series"] = { 30487, 30683, 30684, 30796, 30829, 31306 }, ["description"] = "The Tongue of Ba-Shon should allow us to communicate from long distances, <name>. If the relic works the way I think it will, I should be able to stay here and continue my meditations while you do some scouting in the Valley of Emperors. Mishi will take you to the edge of the valley so that we can test my theory. I would hate for you to be in the tombs with no way to contact me. That would be horrible!", ["objectivesText"] = "Use the Tongue of Ba-Shon in the Valley of Emperors.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30796] = { ["id"] = 30796, ["name"] = "An End to Everything", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30796 }, ["series"] = { 30487, 30683, 30684, 30795, 30829, 31306 }, ["description"] = "These spirits must have been released when the tombs were opened... Death was not final for the Mogu. Instead, death was merely a stop over on the path to a new body. Spiritbinders used a foul magic to transfer spirits from one shell to the next. Years of being trapped in the tombs has left them confused. They need to be destroyed before their confusion turns to anger or worse, they find a new shell.", ["objectivesText"] = "Destroy 5 Tormented Spirits . Progress: Have you disposed of the spirits yet?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30797] = { ["id"] = 30797, ["name"] = "It Was Almost Alive", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30797 }, ["series"] = { 30798, 30799, 30800, 30801, 30802, 30935 }, ["description"] = "A ritual took place here, and from the looks of it wasn't successful. Among the abandoned items a book lies open. The text on the pages is foreign to you. Carrying the whole book may be difficult, but a single page might be enough. If you can get the page to Lorewalker Cho he may be able to tell you what it says.", ["objectivesText"] = "Tear a page from the open book to give to Lorewalker Cho. Progress: What have you found, <name>?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712, 81892 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 44, ["flags"] = 0 } } },
[30798] = { ["id"] = 30798, ["name"] = "Breaking the Emperor's Shield", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30798 }, ["series"] = { 30797, 30799, 30800, 30801, 30802, 30935 }, ["description"] = "The Mogu have been scattered and sparse in number for many years. Their purpose in the valley makes sense now. With this many restless spirits they can build themselves an army using the guardians buried in each tomb. Combined with the Zandalari forces this would be devastating! The Tomb of Secrets houses elite warriors called the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest rise to the southwest.", ["objectivesText"] = "Stop the Spiritbinding Ritual in the Tomb of Secrets. Progress: Have you gone to the Tomb of Secrets yet?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 46, ["flags"] = 0 } } },
[30799] = { ["id"] = 30799, ["name"] = "The Tomb of Shadows", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["mapID"] = 379, ["storyline"] = { 30799 }, ["series"] = { 30797, 30798, 30800, 30801, 30802, 30935 }, ["description"] = "Given the artifacts you found on the altar, I would guess they were attempting to perform a Spiritbinding ritual. Most of the texts involving Spiritbinding were locked away in the Tomb of Shadows. Perhaps we will find the answers we seek there. Look for anything that might help us. You'll find the tomb on the first rise closest to the ritual altar.", ["objectivesText"] = "Collect a rubbing of the Shen Dynasty Tablet, the Wai Dynasty Tablet, and the Qiang Dynasty Tablet in the Tomb of Shadows. Progress: Did you find anything in the Tomb of Shadows?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712, 82393, 82394, 82395, 82564, 82565, 82566, 82567, 82568 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 45, ["flags"] = 0 } } },
[30800] = { ["id"] = 30800, ["name"] = "Stealing Their Thunder King", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["mapID"] = 379, ["storyline"] = { 30800 }, ["series"] = { 30797, 30798, 30799, 30801, 30802, 30935 }, ["description"] = "Our only hope is to find the Thunder King's remains before they do. He must be buried within the Tomb of Conquerors. Getting to his remains will not be easy, <name>. The tomb will no doubt be defended by guardians and other unfriendly surprises intended to ward off thieves. Once inside we will need to figure out where his remains have actually been placed.", ["objectivesText"] = "Find the Bottom Fragment of Lei Shen's Tablet and restore the Tablet of Thunder. Progress: Have you figured out where the Thunder King's remains are hidden?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712, 82764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 47, ["flags"] = 0 } } },
[30801] = { ["id"] = 30801, ["name"] = "Lessons from History", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["mapID"] = 379, ["storyline"] = { 30801 }, ["series"] = { 30797, 30798, 30799, 30800, 30802, 30935 }, ["description"] = "The Thunder King was a vicious Emperor and with the Zandalari at his side he was unstoppable. His return would surely return this land to turmoil and misery. You must locate his remains and take them somewhere safe. The Tablet of Thunder should help you figure out how to access his tomb.", ["objectivesText"] = "Read the Tablet of Thunder in the Tomb of Conquerors. Progress: Have you read the tablet?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 48, ["flags"] = 0 } } },
[30802] = { ["id"] = 30802, ["name"] = "Chasing the Storm", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30802 }, ["series"] = { 30797, 30798, 30799, 30800, 30801, 30935 }, ["description"] = "We need to figure out where they are taking the Thunder King's remains. It won't be possible for them to ressurect him in the Valley of the Emperors. They would need to be somewhere remote and secure. It appears that getting out of here may also prove to be a challenge.... Fight your way out and look for information concerning location of the remains.", ["objectivesText"] = "Find the Blood-Revealed Map on a Zandalari Warrior. Progress: Were you able to find any information on their location?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712, 81890, 82579, 82580, 82581, 82582, 82583 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 49, ["flags"] = 0 } } },
[30804] = { ["id"] = 30804, ["name"] = "The Fearmaster", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30804 }, ["series"] = { 30582 }, ["description"] = "I am not gonna take this anymore. My wife, bless her, poured her heart and soul in to that ranch making it what it is today. Them yaungol got a leader over there being all smug and what not. I'll pay you handsomely if you knock that smug smile off his filthy, stinking, good for nothing face.", ["objectivesText"] = "Kill the Fearmaster . Progress: So many strangers in these lands these days. Luckily you <class> seem to be all right.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 84518, 84519, 84520, 84521, 84522, 84523, 84524, 84525, 84526 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30814] = { ["id"] = 30814, ["name"] = "A Foot in the Door", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30814 }, ["description"] = "<Lord Taran immediately pins you down with his steely gaze.> <class>, you bear the marks of many a past battle. Good! We need more seasoned people like you to hold back the front. We've managed to secure a foothold here, but the yaungol are desperate to remove our presence. If you wish to prove your worth, go down the hill and show the yaungol that we will not back down.", ["objectivesText"] = "Kill 8 Osul Chargers . Progress: We are slowly gaining ground.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 0, ["flags"] = 0 } } },
[30815] = { ["id"] = 30815, ["name"] = "The Death of Me", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30815 }, ["series"] = { 30788, 30789 }, ["description"] = "I have resolved to remove this spear from my side. For this, I require your assistance. Your grasping hands are stronger than mine.", ["objectivesText"] = "Remove the spear from Orbiss .", ["rewardGold"] = 11000, ["rewardXP"] = 19600, ["rewardItems"] = { 3440, 3446, 19784, 20646, 20647, 21359, 21360, 21361, 21362, 21364, 27398, 27400, 29954, 29955, 29959, 30368, 30369, 30370, 30371, 30401, 30860, 38669, 40483, 44358, 44359, 44360, 44361, 55915, 55916, 55917, 57147, 57148, 57151, 57152, 57153, 57300, 57301, 57302, 57790, 59212, 59213, 59214, 59215, 62962, 62963, 62964, 62965, 63191, 63192, 63193, 63648, 63649, 63650, 63651, 63760, 63761, 63762, 63882, 63883, 63884, 83756, 83757, 83758, 83760, 83761, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 21, ["flags"] = 0 } } },
[30823] = { ["id"] = 30823, ["name"] = "Shut it Down", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30823 }, ["description"] = "My cousin over at Kota Basecamp mussed up. He mussed up bad. He was too lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up and give back the seeds... in a day or so. He fed everything he had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves. Kota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", ["objectivesText"] = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 30365, 30366, 30377, 30378, 57442, 57443 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30824] = { ["id"] = 30824, ["name"] = "Gourmet Kafa", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30824 }, ["description"] = "It was a crazy idea: kafa berries go in the goot, seeds come out. Kafa'kota is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is GOURMET. But its over now. Uncle Keenbean is upset and peak is a muss. All thats left is to collect the rest of the Kafa'goot and never make it again. I won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it easily when the mountain is safe again.", ["objectivesText"] = "Mark 10 Kafa'goot \"Deposits\" on Kota Peak.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88382 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30825] = { ["id"] = 30825, ["name"] = "Kota Blend", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30825 }, ["series"] = { 30744, 30746 }, ["description"] = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation. Grummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to our cousin. He's got the wildlife up there hooked on kafa with his scheming. Kafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves. Uncle Keenbean will pay you good for any berries you bring down from Kota. Here, take a sample. Eat it. See for yourself the power of kafa.", ["objectivesText"] = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.", ["rewardXP"] = 162000, ["rewardItems"] = { 81054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30826] = { ["id"] = 30826, ["name"] = "Trouble Brewing", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30826 }, ["description"] = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots. Then stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and the yeti ate them goots. Now they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts. Gonna come outta those caves soon, I'm sure. Come lookin' for more kafa. Then we all in trouble.", ["objectivesText"] = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 87301, 87302, 87303, 87304, 87305, 87306, 87307, 87308, 87309, 88578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30827] = { ["id"] = 30827, ["name"] = "What Lies Beneath", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30827 }, ["series"] = { 30780 }, ["description"] = "If my suspicions are correct, this place still reels from some lingering darkness. Whatever happened here... it could not have been the natural course of events. Even the yaungol are not so brutal as to slaughter their own kind to the point of... this. I will use the totems that you brought me to perform a cleansing ritual. I need someone to assist me in the ceremony. Let me know when you are ready.", ["objectivesText"] = "Speak to Yalia Sagewhisper to begin the ceremony. Then, activate the Totem of Kindness , the Totem of Tranquility , and the Totem of Serenity . Progress: I believe that we must drive the taint from this place.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 14, ["flags"] = 0 } } },
[30828] = { ["id"] = 30828, ["name"] = "Cleansing the Mere", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30828 }, ["series"] = { 30480, 30496, 30855, 30967 }, ["description"] = "Pools of the same murky substance that came out of Mei emerged in the lake recently. I will travel into the Mere with you. Point out the pools of corruption that you are ready for me to cleanse. You will need to deal with whatever comes out and protect me as I complete the ritual.", ["objectivesText"] = "Point out Pools of Corruption in Inkgill Mere to Waterspeaker Gorai to let him know you are ready to defend him while he completes the cleansing ritual. Progress: Is the lake cleansed?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 7, ["flags"] = 0 } } },
[30829] = { ["id"] = 30829, ["name"] = "The Tongue of Ba-Shon", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30829 }, ["series"] = { 30487, 30683, 30684, 30795, 30796, 31306 }, ["description"] = "Thank you for coming, $p. I am sorry to have been so cryptic, but I could not risk alerting the mogu to my work here. They are seeking something in the valley. Plundering the tombs of their old kings for relics of power. I could not observe them long before having to flee, but I did manage to recover a relic of my own. The Tongue of Ba-Shon will let us communicate securely over long distances, but only after I have bound it to myself. I think I'm ready to begin, if you are.", ["objectivesText"] = "Assist Lorekeeper Cho in performing the Binding of Ba-Shon. Progress: I'll need to bind my essence to the Tongue, then you can use it to speak with me from anywhere.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 43, ["flags"] = 0 } } },
[30834] = { ["id"] = 30834, ["name"] = "Father and Child Reunion", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30834 }, ["description"] = "They survived? My father is alive! I thought we would all die here in this horrible mere, at the hands of these insane Jinyu. I will find my way back - meet me back at camp.", ["objectivesText"] = "Return to Merchant Shi and Wu-Peng at the southeastern shore of Inkgill Mere in Kun-Lai Summit . Progress: My boy! He is alive!", ["rewardGold"] = 204000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30855] = { ["id"] = 30855, ["name"] = "The Fall of Shai Hu", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30855 }, ["series"] = { 30480, 30496, 30828, 30967 }, ["description"] = "I can hear the voice of the Mere - it has been purified. But, this chapter in my people's history will never be closed - not until we defeat Shai Hu . He has retreated to the central island in the Mere, corrupting our holiest of sites. Beware - he is strong. But, after all we have done, I am confident we will be stronger.", ["objectivesText"] = "Defeat Shai Hu . He can be found at the Waterspeaker's Sanctuary, the island in the center of Inkgill Mere in Kun-Lai Summit .", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 82550, 82551, 82552, 82553, 82554, 82555, 82556, 82557, 82558 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 8, ["flags"] = 0 } } },
[30884] = { ["id"] = 30884, ["name"] = "Behind the Battlefront", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30884 }, ["series"] = { 30887 }, ["description"] = "This battlefront has been undermanned and unsupplied for too long during my absence in Kun-Lai. We need to get things back in order here before we can pick up the trail of the Sha of Hatred. Taoshi is my best. I've sent her north to investigate rumors of mantid that have somehow made it through the battlefront. I need someone I can trust to get out there and work with her to plug any holes in our defenses. If my reports on you are correct, I can trust you with this, right <class>?", ["objectivesText"] = "Meet with Taoshi at Dampsoil Burrow.", ["rewardGold"] = 27500, ["rewardXP"] = 49000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 19, ["flags"] = 0 } } },
[30887] = { ["id"] = 30887, ["name"] = "Unwelcome Intruders", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30887 }, ["series"] = { 30884 }, ["description"] = "Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep them out of eastern Townlong Steppes . If we allow them north of the barricade, we may lose our foothold here. Let's clear them out. I'll be with you.", ["objectivesText"] = "Kill 12 Krik'thik Deep-scouts with Taoshi 's help.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 20, ["flags"] = 0 } } },
[30888] = { ["id"] = 30888, ["name"] = "Breach in the Defenses", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30888 }, ["series"] = { 30890, 30893, 30895, 30898, 30900, 30901, 30960, 30970, 31697 }, ["description"] = "Normally, it only takes a few scouts to hold this pass. Most of this territory is in sight of the wall, so archers would devastate any mantid force attempting to push through here. The problem is, most of the archers are occupied with the onslaught at the gate. Take this flare - it will help you locate the mantid that are sneaking through the eastern pass under our diminished watch. Kill any you find. We can't let them lay a trail that might lead the mantid swarms farther into the steppes.", ["objectivesText"] = "Use the Shado-Pan Flare to aid in killing 10 Krik'thik Scentlayers .", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 63775, 63780, 81925 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 22, ["flags"] = 0 } } },
[30889] = { ["id"] = 30889, ["name"] = "Trap Setting", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30889 }, ["description"] = "Good to meet you, <class>. We have traps all along the pass to help us catch mantid that might be sneaking through, but their numbers have been so great that most of the traps have already been triggered. Taoshi said you might be able to reset some of them while you're out there. Can you help?", ["objectivesText"] = "Rearm 8 Shado-Pan Spike Traps . Progress: These traps have been very effective, the mantid numbers are just getting out of hand in these past weeks.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 23, ["flags"] = 0 } } },
[30890] = { ["id"] = 30890, ["name"] = "The Restless Watch", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30890 }, ["series"] = { 30888, 30893, 30895, 30898, 30900, 30901, 30960, 30970, 31697 }, ["description"] = "I'm being told that our scouts have been on duty in Shallowstep Pass for more than 2 days straight, no rest. No wonder mantid are slipping through. Even the most dedicated scouts would slip with those kinds of shifts. I want you to go out there and deliver orders to the scouts that they are to return to the battlefront immediately for rest and rations. I'll arrange for a new shift to be posted.", ["objectivesText"] = "Deliver return orders to Scout Wei-Chin , Scout Long , Scout Ying , and Scout Jai-Gan . Progress: This whole battlefront is being worked to the bone. We need more men out here.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 84610, 84611, 84612, 84613, 84614 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 21, ["flags"] = 0 } } },
[30891] = { ["id"] = 30891, ["name"] = "Treatment for the Troops", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30891 }, ["description"] = "A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan fighting. The mantid have poison that chews through the skin and infects the blood. It makes for a slow, excruciating death when not treated. I need pollen from the violet citron flowers. The nearest place to find them is around Dampsoil Burrow just north of the battlefront. If you happen to go in that direction, could you bring some back for me?", ["objectivesText"] = "Collect 10 Violet Citron . Progress: Mixed properly, the pollen from these flowers can eat away at the poison without doing any lasting damage to the body otherwise.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 18, ["flags"] = 0 } } },
[30892] = { ["id"] = 30892, ["name"] = "Back on Their Feet", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 422, ["storyline"] = { 30892 }, ["description"] = "<name>, I could use your help. With their long shifts, our warriors down at the southern front of the battlefront are fighting to the point of exhaustion, and many of them have been exposed to the mantid poison. We need more people to tend to the wounded. I've prepared some bandages with the herbs you brought me, but if you have some healing skills, those might work even better. Please, <name>, get our men back on their feet so that they can get back here to safety.", ["objectivesText"] = "Heal 8 Injured Gao-Ran Blackguards . Progress: With the constant mantid attacks, the men are being worked to the bone. We are undermanned on all fronts. Your help means a lot to us, <name>.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82787 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 25, ["flags"] = 0 } } },
[30893] = { ["id"] = 30893, ["name"] = "The Endless Swarm", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30893 }, ["series"] = { 30888, 30890, 30895, 30898, 30900, 30901, 30960, 30970, 31697 }, ["description"] = "Gao-ran's men need help down on the southern front. If you want to stand by the Shado-Pan, that's where you should do it.", ["objectivesText"] = "Kill 12 Krik'thik attackers at the Gao-Ran Battlefront.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83698, 83699, 83700, 83701, 83702, 83703, 83704, 83705, 83706 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 26, ["flags"] = 0 } } },
[30894] = { ["id"] = 30894, ["name"] = "Rummaging Through the Remains", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30894 }, ["description"] = "I do have another task for you, <name>, though it's a might grim. I really need to get to the bottom of this mantid poison, but to do that, I need more information directly from the source. While you're down on the southern battlefield, could you bring me back some mantid limbs so that I can examine their intact poison glands.", ["objectivesText"] = "Recover 20 Krik'thik Limbs . Progress: I'm hoping to find a permanent counter to the mantid poison so that the men won't be afflicted in the first place. It may take some time to piece it together.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82722, 88585 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 27, ["flags"] = 0 } } },
[30895] = { ["id"] = 30895, ["name"] = "Improvised Ammunition", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30895 }, ["series"] = { 30888, 30890, 30893, 30898, 30900, 30901, 30960, 30970, 31697 }, ["description"] = "I've got another job for you. The dragon cannons we depend on to keep the thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed an improvised explosive that's made from the globe seeds down the western ridge. They dispatched a couple initiates to bring some back hours ago, but have heard nothing from them. I want to send someone a bit more capable to make sure that this gets taken care of. Are you my <man/woman> for this?", ["objectivesText"] = "Recover 16 Volatile Dread Orbs from the Ambermarsh. Progress: Back even more quickly than expected. Did you bring the seeds?", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82723, 88096, 88097, 88098, 88099, 88100, 88101, 88102, 88103, 88104 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 35, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 28, ["flags"] = 0 } } },
[30896] = { ["id"] = 30896, ["name"] = "Thieves and Troublemakers", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 422, ["storyline"] = { 30896 }, ["description"] = "I can't catch the little buggers for the life of me. Kill any you can get your hands on. And keep a close eye on your valuables, they like to steal anything that isn't tied down.", ["objectivesText"] = "Kill 10 Agitated Nettleskins. Progress: I haven't hated plants so much since my job back at Halfhill.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 86472, 88487 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 29, ["flags"] = 0 } } },
[30897] = { ["id"] = 30897, ["name"] = "In the Wrong Hands", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30897 }, ["description"] = "Look... um... this is really embarrassing. I set down my sword for like ONE SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and bounded off down the western gap. I can't go back to camp without it. Losing your weapon is a sure way to get kicked out of the Shado-Pan. It's sacred. Please, can you try to find this big sprite and get my sword back? It would mean a lot to me.", ["objectivesText"] = "Recover Initiate Chao's Sword . Progress: My mom warned me this was going to happen...", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82783, 86472, 88586 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 30, ["flags"] = 0 } } },
[30898] = { ["id"] = 30898, ["name"] = "Cutting the Swarm", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30898 }, ["series"] = { 30888, 30890, 30893, 30895, 30900, 30901, 30960, 30970, 31697 }, ["description"] = "The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use. Get down on the battlefront and man one of the cannons. Let none through.", ["objectivesText"] = "Use a Dragon Launcher to kill 50 swarming mantid. Progress: I can't remember the last time they swarmed this thickly. They probably haven't within my lifetime.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 31, ["flags"] = 0 } } },
[30899] = { ["id"] = 30899, ["name"] = "In Skilled Hands", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30899 }, ["series"] = { 30975, 30976, 30978, 30979, 30980, 31065 }, ["description"] = "<name>, take these crossbow bolts and then bring them to Hawkmaster Nurong at Farwatch Overlook to the southwest. Nurong is praised among all the Wukao for being a flawless shot. His efforts are credited with holding the line here for these many months. I'm hoping you can work with him and judge for yourself. He may be the final Shado-Pan we need for the hunt.", ["objectivesText"] = "Bring the Shado-Pan Crossbow Bolt Bundle to Hawkmaster Nurong . Progress: Another wave of fliers approaches. Be ready.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83023 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 45, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 40, ["flags"] = 0 } } },
[30900] = { ["id"] = 30900, ["name"] = "Terror of the Dread Wastes", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30900 }, ["series"] = { 30888, 30890, 30893, 30895, 30898, 30901, 30960, 30970, 31697 }, ["description"] = "That thing is huge! The Shado-Pan holding the battlefront were never trained for something like this... let's get down there and take it out ourselves.", ["objectivesText"] = "Defeat Norvakess , the Terror of the Dread Wastes. Progress: I've never seen anything like this...", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83726, 83727, 83728, 83729, 83730 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 37, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 32, ["flags"] = 0 } } },
[30901] = { ["id"] = 30901, ["name"] = "Along the Southern Front", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30901 }, ["series"] = { 30888, 30890, 30893, 30895, 30898, 30900, 30960, 30970, 31697 }, ["description"] = "I'm heading westward with Taoshi to gather the strongest I can find to confront the Sha of Hatred. I would like you to come with me.", ["objectivesText"] = "Ride with Taran Zhu and Taoshi to Dusklight Hollow.", ["rewardGold"] = 27500, ["rewardXP"] = 49000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 33, ["flags"] = 0 } } },
[30921] = { ["id"] = 30921, ["name"] = "The Motives of the Mantid", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30921 }, ["series"] = { 30923, 30924, 30925 }, ["description"] = "<class>. You may be of assistance. The Shado-Pan wishes to know why the mantid are attacking so violently. We have our suspicions, but we cannot be sure. Furthermore, we do not want the mantid to know that we are investigating them. That's where you come in. I need you to kill the mantid of Kri'vess, in the north. I will lurk behind you in the shadows, and search for clues on their bodies.", ["objectivesText"] = "Slay mantid in Kri'vess so Tai Ho can look for clues on their bodies.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83120, 83707, 83708, 83709, 83710, 83711, 83712, 83713, 83714, 83715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 55, ["flags"] = 0 } } },
[30923] = { ["id"] = 30923, ["name"] = "Set the Mantid Back", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30923 }, ["series"] = { 30921, 30924, 30925 }, ["description"] = "Every day, the mantid build up munitions for use on their enemies. We cannot stop them, just you and I... but we can set them back. < Tai Ho hands you some explosives.> I need to keep a low profile. Would you do the honors?", ["objectivesText"] = "Use Gunpowder Casks to explode the Kri'thik Weapons and the Kri'thik Supplies in Kri'vess.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 81891 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 56, ["flags"] = 0 } } },
[30924] = { ["id"] = 30924, ["name"] = "The Wisdom of Niuzao", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30924 }, ["series"] = { 30921, 30923, 30925 }, ["description"] = "Niuzao, the Black Ox, rests in the temple to the west. He may know why the mantid are attacking. He may, in fact, know much more than that. I will rendezvous with you at Niuzao Temple, <class>.", ["objectivesText"] = "Speak with Ogo the Younger at Niuzao Temple in the Townlong Steppes .", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 57, ["flags"] = 0 } } },
[30925] = { ["id"] = 30925, ["name"] = "Niuzao's Price", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30925 }, ["series"] = { 30921, 30923, 30924 }, ["description"] = "Niuzao owns a statuette which he values greatly: a small icon, in his image, sculpted by one of his long-since fallen sentinels. This statuette was recently stolen by the Sra'thik mantid, and taken to their encampment to our north. Bring back this statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.", ["objectivesText"] = "Kill the mantid of the Sra'thik Incursion so that Tai Ho can search their bodies for pieces of Niuzao's statuette. Progress: Niuzao does not move quickly, nor does he make rash decisions. Perform his task, and give him time to decide.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83736, 83737, 83738, 83739, 83740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 58, ["flags"] = 0 } } },
[30926] = { ["id"] = 30926, ["name"] = "The Terrible Truth", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 389, ["storyline"] = { 30926 }, ["description"] = "It is with a heavy heart that I confirm your suspicions. The mantid are indeed under the sway of the Sha of Fear. It was OUR sworn duty to confine that creature beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha escaped. It is with the mantid now. See for yourself. The mantid burrowed into the western side of our island.", ["objectivesText"] = "Investigate the Niuzao Catacombs, then slay the Dread Shadow that dwells within.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83731, 83732, 83733, 83734, 83735 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 389, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 59, ["flags"] = 0 } } },
[30927] = { ["id"] = 30927, ["name"] = "Give Them Peace", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30927 }, ["description"] = "I overheard. Our secret is out, then. When I learned that the mantid had burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend what they could, but they were not prepared. They succumbed to fear, and never returned. A pandaren deserves to die embracing the ground, as he does in sleep... not flat on his back with his eyes transfixed in terror. Please, <name>. Give them the peace they deserve.", ["objectivesText"] = "Give peace to 10 Fear-Stricken Sentinels by closing their eyes and placing them on their bellies. Progress: I should have gone with them.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30935] = { ["id"] = 30935, ["name"] = "Fisherman's Tale", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30935 }, ["series"] = { 30797, 30798, 30799, 30800, 30801, 30802 }, ["description"] = "The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the Zandalari are hiding on one of the islands, they will know. Mishi will take you as far as Emperor's Path. I will go ahead to speak with the village elders. Follow the path to Whispercloud Rise. Shin Whispercloud will help you reach the village.", ["objectivesText"] = "Speak with Mishi to travel to the Path of Conquerors. From there find Shin Whispercloud at Whispercloud Rise.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81712, 86471 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 50, ["flags"] = 0 } } },
[30942] = { ["id"] = 30942, ["name"] = "Make A Fighter Out of Me", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30942 }, ["description"] = "Shhh! Don't speak so loudly! My father might hear you. < Shomi gestures to Steelbender Doshu.> My father is delusional! He thinks I should be studying my tea pouring while our village is under attack. It's ridiculous! I have just as much courage as any man. I just don't know how to fight... yet. That's where you come in. Let me travel with you! I'm a fast learner and I won't get in the way I promise! Pleaseeeeee! If we get separated I'll meet you back in the village.", ["objectivesText"] = "Kill 4 Amani Skirmishers, 4 Gurubashi Hexxers, and 3 Drakkari Frostweavers in Zouchin Province. Progress: I'll show my father he's wrong about me!", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 65665, 82599, 82600, 82601, 82602, 82603, 82604, 90488, 90489, 90623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 56, ["flags"] = 0 } } },
[30943] = { ["id"] = 30943, ["name"] = "Handle With Care", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30943 }, ["description"] = "I've seen the numbers these invaders have brought with them, this will not be an easy victory. I do know of one thing that may help us gain an advantage. There is a plant that grows around the village that can be used to make a rather effective explosive liquid. If you can gather enough I can begin brewing the mixture. The plant you are looking for is appropriately named volatile bloom. Handle it with care, <class>.", ["objectivesText"] = "Bring Elder Shu 50 Volatile Blooms. Progress: Were you able to find a suitable amount of volatile blooms?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82298 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 54, ["flags"] = 0 } } },
[30944] = { ["id"] = 30944, ["name"] = "It Takes A Village", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30944 }, ["description"] = "The villagers have been guarding Zouchin since the first attack. They are exhausted and many are injured. If the Zandalari attack again the last thing we need is for the defenders to fall asleep on the job. Relieve them of their posts so that they might have time to heal and see their families. You'll find them stationed around the village.", ["objectivesText"] = "Relieve the Exhausted Defenders from their guard posts. Progress: Are the villagers recovering?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 53, ["flags"] = 0 } } },
[30945] = { ["id"] = 30945, ["name"] = "What's Yours Is Mine", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30945 }, ["description"] = "The elders want us to mount a defense? We're not monks, <class>; we need weapons if we hope to fight! Scavenge some arms from those barbarians for me. I should be able to melt them down and make something more suitable for our villagers to fight with. Bring me as many as you can carry and I'll take care of the rest.", ["objectivesText"] = "Retrieve 6 Stolen Weapons from the Zandalari Invaders. Progress: We'll need more than luck to get us through this. I hope you found something I can work with.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80783, 80784, 80785, 80786, 80787, 82299 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 55, ["flags"] = 0 } } },
[30946] = { ["id"] = 30946, ["name"] = "Revelations", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30946 }, ["series"] = { 31011, 31228 }, ["description"] = "The prisoner is being kept upstairs, <name>. It will be difficult to get information from him, but even the slightest detail about their location will help. The elders have begun questioning him already. With their help we should be able to figure out our next move. Go speak with him and see if he has any useful information.", ["objectivesText"] = "Speak with the Zandalari Prisoner . Progress: What did the prisoner have to say?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 58, ["flags"] = 0 } } },
[30960] = { ["id"] = 30960, ["name"] = "Returning from the Pass", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30960 }, ["series"] = { 30888, 30890, 30893, 30895, 30898, 30900, 30901, 30970, 31697 }, ["description"] = "I still have some cleanup to do here in the pass - there are some mantid still making it through. You're a valuable person to have at hand though, and I know Taran wouldn't appreciate me keeping you longer for such basic work. Taran should still be in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.", ["objectivesText"] = "Report in to Taran Zhu at the Gao-Ran Battlefront.", ["rewardGold"] = 27500, ["rewardXP"] = 49000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 24, ["flags"] = 0 } } },
[30967] = { ["id"] = 30967, ["name"] = "Free the Dissenters", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30967 }, ["series"] = { 30480, 30496, 30828, 30855 }, ["description"] = "Not all of my fellow villagers from Inkgill are corrupted. Many heeded my warnings and did not drink of the sha-tainted waters. They are in hiding, terrified, and intimidated by the guards. Please, tell them there is hope! Go into the village to the north. Speak with them and send them to me.", ["objectivesText"] = "Rescue 6 Inkgill Dissenters in Inkgill Mere.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 5, ["flags"] = 0 } } },
[30968] = { ["id"] = 30968, ["name"] = "The Sha of Hatred", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30968 }, ["series"] = { 30981, 31063, 31064, 31656 }, ["description"] = "The end of our hunt is upon us. We have gathered the strongest the Shado-Pan have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and choke out its influence on the world. When we enter the tunnel, stay close, and keep hatred clear from your heart. The fight ahead will put all of us to the test. Whatever happens, it has been an honor traveling beside you, <name>.", ["objectivesText"] = "Defeat the Sha of Hatred .", ["rewardGold"] = 330000, ["rewardXP"] = 294000, ["rewardItems"] = { 83644, 83645, 83646, 83647, 83648, 83649, 83650, 83651, 83652 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 54, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 52, ["flags"] = 0 } } },
[30970] = { ["id"] = 30970, ["name"] = "Enraged By Hatred", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30970 }, ["series"] = { 30888, 30890, 30893, 30895, 30898, 30900, 30901, 30960, 31697 }, ["description"] = "These scorpions are infected with sha. It seems to have driven them out of their hole and into our camp, seething with hatred at invaders in their territory. We need to clear the scorpions and secure the camp. Kill any you find.", ["objectivesText"] = "Kill 9 Seething Fleshrippers . Progress: The Sha of Hatred's passing did this to them. I doubt this is the only thing that will have been affected by its passing.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83741, 83742, 83743, 83744, 83745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 39, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 34, ["flags"] = 0 } } },
[30971] = { ["id"] = 30971, ["name"] = "Taking Stock", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30971 }, ["series"] = { 30972 }, ["description"] = "I was dispatched back to camp to gather pitch-tipped arrows for our archers at the bridge, and this is what I came to. I trained with most of these pandaren... I wasn't prepared for this. Still, the archers at the bridge need our help. If you could help gather arrows from the wreckage, then maybe we can salvage something from this horror.", ["objectivesText"] = "Gather 120 Shado-Pan Fire Arrows . Progress: The pandaren at the bridge are depending on us...", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83024 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 40, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 35, ["flags"] = 0 } } },
[30972] = { ["id"] = 30972, ["name"] = "Joining the Fight", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 30972 }, ["series"] = { 30971 }, ["description"] = "Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?", ["objectivesText"] = "Bring the Quiver of Shado-Pan Fire Arrows to Lao-Chin the Iron Belly at Dusklight Bridge. Progress: Welcome to the mess.", ["rewardGold"] = 27500, ["rewardXP"] = 49000, ["rewardItems"] = { 83136 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 41, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 36, ["flags"] = 0 } } },
