[30991] = { ["id"] = 30991, ["name"] = "Do a Barrel Roll!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30991 }, ["series"] = { 30665, 30670, 30690, 30699, 30723, 30724, 30750, 30994 }, ["description"] = "When I trained as a Brewmaster, I didn't expect to use my knowledge like this... Did you know beer catches fire when lit? Well, with yaungol oil mixed in, it's downright explosive. I've mixed the oil in with these kegs. Roll them at the yaungol over by the gate, and ignite them when you get close. It'll take a few seconds for the keg to blow, but when it does... Well, let's just say I wouldn't want to be over there. Which is why I'll be over here. Mourning the loss of this brew.", ["objectivesText"] = "Pick up a keg near Lao-Chin, roll it downhill at the yaungol, and ignite it near them to destroy 4 Osul Treelaunchers and 50 Osul Invaders . Progress: Wha? I was just thinking about my poor, poor beer...", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88531 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 84, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 33, ["flags"] = 0 } } },
[30992] = { ["id"] = 30992, ["name"] = "Finish This!", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30992 }, ["description"] = "We've heard back from Suna, on the wall. Something's going on... It looks like they are preparing for their final push. It's time to finish this, friend.", ["objectivesText"] = "Finish the battle for the Ox Gate. Progress: Lin is captured... we must break Taran Zhu from his complacence!", ["rewardGold"] = 212000, ["rewardXP"] = 203000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 85, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 34, ["flags"] = 0 } } },
[30993] = { ["id"] = 30993, ["name"] = "Where are My Reinforcements?", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30993 }, ["description"] = "This has simply gone too far. I cannot ignore our abandonment any longer. After all that's happened here, and all you've been through in Firebough, we must travel to the monastery. Whatever they are doing in there can wait! We can take my balloon up the mountain to the Monastery. It's anchored back by the camp, to the northeast.", ["objectivesText"] = "Speak with Ban Bearheart outside the Shado-Pan Monastery in Kun-Lai Summit . Progress: Here we are, then.", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 86, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 35, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 35, ["flags"] = 0 } } },
[30994] = { ["id"] = 30994, ["name"] = "Lao-Chin's Gambit", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30994 }, ["series"] = { 30665, 30670, 30690, 30699, 30723, 30724, 30750, 30991 }, ["description"] = "Alright. Thanks to you, we have the wall under control. Good job. I'll stay up here for a little while and make sure no more yaungol get up onto the wall. You, though, should go back down and see what Lao-Chin has cooked up. I hate to say it, but maybe he had a good idea after all...", ["objectivesText"] = "Speak with Lao-Chin the Iron Belly at Winter's Blossom in Kun-Lai Summit . Progress: Ah, hello again. As sad as I am to have to do this, I'm glad I came up with something.", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 83, ["flags"] = 0 }, { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 32, ["flags"] = 0 } } },
[30999] = { ["id"] = 30999, ["name"] = "Path Less Traveled", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30999 }, ["series"] = { 30601, 31459, 31460 }, ["description"] = "The toughest roads often have the most to teach us, <class>. I will no doubt learn a great deal from following the path of Shaohao. Many years ago Shaohao traveled to the highest peak in Kun-Lai to seek the guidance of the Jade Serpent. I too will travel to Seeker's Point in search of wisdom. Perhaps you would be interested in a journey such as this? If so speak with Uncle Cloverleaf . He will help you prepare.", ["objectivesText"] = "Speak to Uncle Cloverleaf in Onekeg.", ["rewardGold"] = 53000, ["rewardXP"] = 81000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 35, ["flags"] = 0 } } },
[31001] = { ["id"] = 31001, ["name"] = "Falling Down", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 422, ["storyline"] = { 31001 }, ["series"] = { 31895 }, ["description"] = "It's bad enough trying to hold off the mantid, but now we've got spiders swarming up from the ruins below. One of my best marksmen caught a blast of webbing around his leg and got pulled straight down! We think he's alive, but I don't have the manpower to send anyone in after him. We're stretched thin up here, <class>. If you want to help, use the rope behind me to drop down into the ruins. You're not afraid of heights are you? How about spiders?", ["objectivesText"] = "Use the Shado-Pan Rope to descend into the Terrace of Gurthan and search for the fallen Shado-Pan marksman.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 0, ["flags"] = 0 } } },
[31002] = { ["id"] = 31002, ["name"] = "Nope", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 31002 }, ["description"] = "We're holding, but just barely. Anything you can do to stem the tide of dreadspinners coming up the wall would be a big help. Feel like tearing open spider eggs one at a time by hand? I didn't think so. Take one of our dragon guns and light it up down there. I wanna hear those puppies pop.", ["objectivesText"] = "Slay 6 Dreadspinner Tenders and use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in the Terrace of Gurthan. Progress: Hey, help me out here!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82807, 84037, 84038, 84039, 84040, 84041, 84042, 84043, 84044, 84045 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 1, ["flags"] = 0 } } },
[31003] = { ["id"] = 31003, ["name"] = "Psycho Mantid", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31003 }, ["series"] = { 31004 }, ["description"] = "You aren't going to believe what I saw! Two mantid fighting each other, whipping some serious magic back and forth. One of them didn't look like any mantid I've ever seen. Completely different color and dress to him, like some kind of... oracle or something. The other one was a total psycho, splashing sha energy around like it was a keg of Stormstout Special. Look, I gotta get back to my post, but those two are still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?", ["objectivesText"] = "Investigate the mantid infighting at the Terrace of Gurthan. Progress: The empress... is... misguided.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 2, ["flags"] = 0 } } },
[31006] = { ["id"] = 31006, ["name"] = "The Klaxxi Council", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31006 }, ["series"] = { 31005, 31676 }, ["description"] = "I must report to the Klaxxi. They would not have woken me unless the situation were dire. You have not been entirely useless. For that, I will spare your life. The council may even find a use for you.", ["objectivesText"] = "Travel to Klaxxi'vess at the center of the Dread Wastes . You may speak with Kil'ruk the Wind-Reaver in the Terrace of Gurthan for a ride, or travel on your own.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84055, 84056, 84057, 84058, 84059 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 6, ["flags"] = 0 } } },
[31007] = { ["id"] = 31007, ["name"] = "The Dread Clutches", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31007 }, ["description"] = "The imperial clutches have become an abomination! Clutch-Keepers rush the development of new swarmborn, saturating them in this vile \"sha\" energy before sending them away to the wall. The Klaxxi wish to stem the tide of swarmborn production in these dread clutches. Put the keepers to death!", ["objectivesText"] = "Slay 6 Shek'zeer Clutch-Keepers in the Clutches of Shek'zeer.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 7, ["flags"] = 0 } } },
[31008] = { ["id"] = 31008, ["name"] = "Amber Arms", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31008 }, ["description"] = "You! Filth! You work for me now! The amber blades of the Shek'zeer Bladesworn are the finest weapons in the empire. If you are not impaled upon them immediately after leaving here, bring me as many of the blades as you can carry! I want to make sure we have weapons in reserve, should we need them.", ["objectivesText"] = "Gather 6 Amber Blades from Shek'zeer Bladesworn around the Heart of Fear and The Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear. Progress: The bladesworn carry their swords with pride. I want them on my weapon racks!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83135, 88114, 88115, 88116, 88117, 88118, 88119, 88120, 88121, 88122 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 10, ["flags"] = 0 } } },
[31009] = { ["id"] = 31009, ["name"] = "Dead Zone", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31009 }, ["series"] = { 31010 }, ["description"] = "A Klaxxi'va whispers to the tower. It carries their whisper far; to other towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear it. This way, they see all. A tower near the palace is quiet. This will not do. It must sing for the Klaxxi. It is my job to fix the tower, but if you serve the Klaxxi, you should serve me as well. You fix the tower, and I will wait here!", ["objectivesText"] = "Use the Klaxxi Resonating Crystal on the Inactive Sonic Relay at the Heart of Fear. Speak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.", ["rewardXP"] = 236000, ["rewardItems"] = { 83276 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 9, ["flags"] = 0 } } },
[31010] = { ["id"] = 31010, ["name"] = "In Her Clutch", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31010 }, ["series"] = { 31009 }, ["description"] = "The crystal sings to the Klaxxi. They sense a paragon in the clutch, east of the tower. Clutch-keepers are trying to pollute this one. The Klaxxi will not permit this. Go and find the paragon. Place your hands on his chamber, and the Klaxxi will channel their whispers through you to break him free. Protect him if you can.", ["objectivesText"] = "Locate and waken the mantid paragon in The Clutches of Shek'zeer.", ["rewardGold"] = 228000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 12, ["flags"] = 0 } } },
[31011] = { ["id"] = 31011, ["name"] = "Enemies At Our Door", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31011 }, ["series"] = { 30946, 31228 }, ["description"] = "The Zandalari have begun their attack! You must help defend the village! If we can't push them back, we will never find the Thunder King's remains!", ["objectivesText"] = "Defeat 10 Amani Beserkers, 5 Amani Behemoths , and 3 Gurubashi Bloodriders . Progress: The village must be saved!", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 57, ["flags"] = 0 } } },
[31019] = { ["id"] = 31019, ["name"] = "Amber Is Life", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31019 }, ["description"] = "In order for our efforts against the mantid empire to continue, we require more amber. There is a great deposit of amber underneath the lake to the south, but the area is inhabited by a savage saurok tribe. I cannot spare anyone else. You must go to the lake and test the tribe's strength. Thin their numbers and eliminate their leader, who is probably hiding in his underground cavern. Surely this is not too great a task for you?", ["objectivesText"] = "Kill 7 Mistblade Rippers and the Mistblade Scale-Lord . Progress: The amber looks familiar for some reason...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82870, 86522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 34, ["flags"] = 0 } } },
[31020] = { ["id"] = 31020, ["name"] = "Feeding the Beast", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31020 }, ["description"] = "I must join the Klaxxi Council and the other paragons immediately, but I am barely strong enough to stand. I must feed, Wakener. I sense the beating hearts of creatures on the northern bank of the lake. Kill them for me, and I shall do the rest.", ["objectivesText"] = "Kill 8 Coldbite Crocolisks . Progress: I have been sleeping for many thousands of years. I must regain my strength before rejoining the Council.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 35, ["flags"] = 0 } } },
[31021] = { ["id"] = 31021, ["name"] = "Living Amber", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 422, ["storyline"] = { 31021 }, ["description"] = "Liquid amber is most efficient for restoring a newly awakened paragon's strength, and is usually provided at a wakening ceremony. Unfortunately, it seems you did not receive these instructions, so we shall have to improvise. I can sense a vast quantity of fossilized amber in the lake below us. It will serve, but I am too weak to dig it up myself. Do this for me, and I will see to it that you are rewarded.", ["objectivesText"] = "Collect 8 Living Amber , then feed them to Korven the Prime. Progress: Do you understand, Wakener? The amber gives life.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82864 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 36, ["flags"] = 0 } } },
[31022] = { ["id"] = 31022, ["name"] = "Kypari Zar", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 422, ["storyline"] = { 31022 }, ["series"] = { 31026, 31085, 31354, 31398, 32030 }, ["description"] = "What is that tree on the hill to the west? Can it be... Kypari Zar? <Korven the Prime lapses into silence.> When I returned from my final ravage, before being elevated to a paragon, I was given the honor of planting that very tree. I see it has grown into a great kypari, but... it seems something is amiss. There is an old sonar tower at the base of the tree. Take me there, Wakener. I can use the tower to take a closer look.", ["objectivesText"] = "Activate the Sonar Tower, then defend Korven the Prime as he examines the tree. Progress: What has happened to our home? Things feel amiss.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 37, ["flags"] = 0 } } },
[31023] = { ["id"] = 31023, ["name"] = "Relics of the Swarm", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31023 }, ["description"] = "This strange-looking carving is covered in a complex written language that might be mantid in origin. You notice more relics strewn carelessly among the camps and inside the lake. Perhaps the Klaxxi would be interested in examining these artifacts. Who knows? Perhaps it will earn you some favor.", ["objectivesText"] = "Collect 8 Mantid Relics . Progress: What do you have there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82867, 82870 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["startItems"] = { 82870 } },
[31026] = { ["id"] = 31026, ["name"] = "The Root of the Problem", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31026 }, ["series"] = { 31022, 31085, 31354, 31398, 32030 }, ["description"] = "Kypari Zar is dying. A creature of terrible darkness corrupts it from deep beneath its roots. The tree cannot be saved, but at least we can lessen its pain. Look. The vile creature has carved a path to its own lair. We need only follow it down the hill, just behind this tower.", ["objectivesText"] = "Kill the Coldbite Matriarch . Progress: The swarm knows not of their terrible folly! These precious trees must be protected at all costs!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84075, 84076, 84077, 84078, 84079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 38, ["flags"] = 0 } } },
[31030] = { ["id"] = 31030, ["name"] = "Into the Monastery", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5918, ["storyline"] = { 31030 }, ["series"] = { 30752, 30757, 30759, 31031 }, ["description"] = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption. Gather a group of your allies, and meet me inside the Monastery.", ["objectivesText"] = "Meet Ban Bearheart inside the Shado-Pan Monastery .", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5918 } }, ["questType"] = "dungeon" },
[31032] = { ["id"] = 31032, ["name"] = "Choking the Skies", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 31032 }, ["description"] = "Nurong wants me to pass out torches for burning the bodies. The flying mantid are fragile, and won't last long in the hot smoke.", ["objectivesText"] = "Burn 10 Kor'thik Fleetwing corpses. Progress: Some of them can make it through the smoke, but in small enough numbers that we can easily pick them off.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 76061, 83768, 88589, 89112 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 42, ["flags"] = 0 } } },
[31063] = { ["id"] = 31063, ["name"] = "Lao-Chin and Serevex", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 31063 }, ["series"] = { 30968, 30981, 31064, 31656 }, ["description"] = "Lao-Chin is facing off against the leader just above the entrance in the tree, on the north side of Sik'vess. He is to bring back the second crystal that we need to get into the mantid tunnel. Go there and lend him your aid.", ["objectivesText"] = "Kill Serevex with the aid of Lao-Chin the Iron Belly. Progress: The Sha of Hatred dies this day...", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 52, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 50, ["flags"] = 0 } } },
[31064] = { ["id"] = 31064, ["name"] = "Nurong and Rothek", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 31064 }, ["series"] = { 30968, 30981, 31063, 31656 }, ["description"] = "Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the last mantid leader cannot escape. Catch up with him and help him kill the mantid leader. Nurong will bring back the final crystal once you've aided him in this.", ["objectivesText"] = "Kill Rothek with the aid of Hawkmaster Nurong. Progress: Act swiftly. I do not want the Sha of Hatred to escape our grasp again.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 53, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 51, ["flags"] = 0 } } },
[31065] = { ["id"] = 31065, ["name"] = "Buried Beneath", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 31065 }, ["series"] = { 30899, 30975, 30976, 30978, 30979, 30980 }, ["description"] = "Taoshi set up a spyglass on the ridge edge to show me what her scouting uncovered. Go over and take a look.", ["objectivesText"] = "Look through the spyglass in Rensai's Watchpost. Progress: Go. Look.", ["rewardGold"] = 27500, ["rewardXP"] = 49000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 49, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 46, ["flags"] = 0 } } },
[31066] = { ["id"] = 31066, ["name"] = "A Cry From Darkness", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31066 }, ["description"] = "So, you survived the imperial clutches. You are... resilient. The Klaxxi hear another paragon to the north, among the sha-scorched roots of Kypari Vor. This one cries out in terror and agony. It cannot be saved. The Klaxxi want him put down. Go and defeat him or do not return here.", ["objectivesText"] = "Slay the corrupted paragon at Kypari Vor. Progress: The order stands. Slay the fallen paragon.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84060, 84061, 84062, 84063, 84064 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 16, ["flags"] = 0 } } },
[31067] = { ["id"] = 31067, ["name"] = "The Heavens Hum With War", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31067 }, ["series"] = { 31069, 31730 }, ["description"] = "The mantid don't ever make my job easy, but now they've gone too far. We can fend off the occasional attack from Kor'vess, but now... now they're starting to surround us. What's worse, they're draining the amber from our tree. This will not stand! We need that amber! To make beer! They've dug a burrow into the south side of the tree. I'm short-handed here. Could you take care of them for me?", ["objectivesText"] = "Slay Azzix K'tai .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 51, ["flags"] = 0 } } },
[31068] = { ["id"] = 31068, ["name"] = "Sacred Recipe", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31068 }, ["description"] = "\"When the horror comes a-rising And the heavens hum with war Our great vessel of salvation Must be broken from its core.\" The scroll continues on for several stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic message.", ["objectivesText"] = "Bring the Scroll of Auspice to Lya of Ten Songs at The Sunset Brewgarden. Progress: Is that some sort of scroll? Would you mind if I took a look?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84071, 84072, 84073, 84586 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 52, ["flags"] = 0 } } },
[31069] = { ["id"] = 31069, ["name"] = "Bound With Shade", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31069 }, ["series"] = { 31067, 31730 }, ["description"] = "About that scroll you found... I keep looking at that line in the second stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me. I must admit, I've often considered taking some of the area's residual sha essence and incorporating it into a brew. I suspect that this is the shade which our recipe calls for. You will find large amalgamations of sha to the southeast of our tree... though you may also be able to harvest some from the local wildlife.", ["objectivesText"] = "Harvest 100 drops of Shade by slaying sha creatures and wildlife near The Sunset Brewgarden.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84080, 84081, 84082, 84083, 84084 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 35, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 53, ["flags"] = 0 } } },
[31070] = { ["id"] = 31070, ["name"] = "Daggers of the Great Ones", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31070 }, ["description"] = "That recipe said: \"rending daggers of the great ones\"... < Olon ponders this line.> Mushan! That's it! There's plenty of mushan roaming out there with these great, big teeth... they're as long as daggers. That's gotta be what the recipe calls for.", ["objectivesText"] = "Obtain 3 Large Mushan Teeth. Progress: I wonder how we'll mix those things into the brew? Can't grind them up - that'd be too gritty. Maybe I'll just soak 'em for a while.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84107 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 54, ["flags"] = 0 } } },
[31071] = { ["id"] = 31071, ["name"] = "I Bring Us Great Shame", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31071 }, ["description"] = "I have failed my fellow brewers. I took some supplies out to the clearing, east of our tree... and I left them there. Now, with the sha corrupting the land, and the mantid on the prowl, it is too dangerous for me to bring them back. If you would help me look for them, perhaps I could regain some of my lost honor.", ["objectivesText"] = "Find the Lost Keg , the Lost Mugs , and the Lost Picnic Supplies . Progress: Did you find them? Can it be?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83781, 83782, 83783 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 37, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 56, ["flags"] = 0 } } },
[31072] = { ["id"] = 31072, ["name"] = "Rending Daggers", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31072 }, ["series"] = { 31074 }, ["description"] = "Forget about them, and forget their BREW. We've got real work to do. The scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where to find them. A pair of mantid lieutenants patrol the Horrid March, to the south. Each one carries a ceremonial dagger. Bring those daggers back here, <name>. We may be on the brink of something big.", ["objectivesText"] = "Obtain the Blade of Kz'Kzik and the Blade of Ilikkax . Progress: I think I'm starting to understand the next few lines of this prophecy, <name>. Do you have the daggers yet?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84111, 84112, 88123, 88124, 88125, 88126, 88127, 88128, 88129, 88130, 88131 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 57, ["flags"] = 0 } } },
[31073] = { ["id"] = 31073, ["name"] = "Bound With Wood", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31073 }, ["description"] = "<Vu eyes the recipe.> Hmm... \"bound with wood\". We don't typically brew with wood. Sap, yes... but not wood. We have, on rare occasions, infused our drinks with corewood from the treants to the west of here. Most of them have fallen to the mantid... but their remains should suffice for our recipe.", ["objectivesText"] = "Obtain 8 pieces of Fragrant Corewood . Progress: We don't brew with wood here. It gives the brew a harsh, insipid flavor, not unlike that of wine. <Vu spits.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84118 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 39, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 55, ["flags"] = 0 } } },
[31074] = { ["id"] = 31074, ["name"] = "Wood and Shade", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31074 }, ["series"] = { 31072 }, ["description"] = "\"Rending daggers of the great ones shall be bound with WOOD and SHADE.\" Hmm. I've learned a lot about the Kor'thik mantid in my time here. I know that they maintain shrines within their settlement, Kor'vess. One is a heartroot of the very tree that they inhabit. The other is a dark pillar, connecting them with their queen. These shrines are the wood and shade. If my predictions are right... the daggers should react in their presence.", ["objectivesText"] = "Find the Mark of the Empress and the Heartroot of Kypari Kor. Progress: <Lya looks concerned.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 40, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 58, ["flags"] = 0 } } },
[31075] = { ["id"] = 31075, ["name"] = "Sunset Kings", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31075 }, ["description"] = "Olon had a clever idea. He thinks that we should visit the sprites to the west, and ask them if they have any of these ingredients. Some of the elements to this recipe are seeming... strange. The Rikkitun sprites have a village to the west of Kor'vess. I hope to see you there, <name>.", ["objectivesText"] = "Meet Sapmaster Vu at Rikkitun Village.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 41, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 64, ["flags"] = 0 } } },
[31077] = { ["id"] = 31077, ["name"] = "Evie Stormstout", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31077 }, ["series"] = { 31078 }, ["description"] = "I was too late. She was so small... and I was too late. She should be given a proper burial. A little warrior like her deserves better than this.", ["objectivesText"] = "Meet Chen Stormstout at The Sunset Brewgarden, then listen to his eulogy. Progress: <Chen is in mourning.>", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 62, ["flags"] = 0 } } },
[31078] = { ["id"] = 31078, ["name"] = "Han Stormstout", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31078 }, ["series"] = { 31077 }, ["description"] = "There will be time for mourning later. For now, there are other Stormstouts to be found. They say that Han Stormstout was last seen exploring Kor'vess. I suspect he headed into that mantid burrow, just across the way. You should meet me down there, <name>. I don't doubt that I can handle a few mantid by myself... but I'd feel better with you by my side.", ["objectivesText"] = "Find Han Stormstout in the Morrowchamber beneath Kor'vess. Progress: I think I see someone over there, but I can't seem to get across these amber beams.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 63, ["flags"] = 0 } } },
[31080] = { ["id"] = 31080, ["name"] = "Fiery Wings", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31080 }, ["description"] = "I think that old paper said something about \"fiery wings.\" Those little dragons around here have wings. They're kind of fiery, in a way. You're quicker than me. Try catching some of those dragons... or at least slapping the powder off of them. No point in killing a harmless little dragon, if all you want is the sparkle from their wings.", ["objectivesText"] = "Slap Rikkilea Flitterlings, then catch 88 flecks of Flitterling Dust . Progress: I haven't been able to catch any of those things!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84239 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 43, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 66, ["flags"] = 0 } } },
[31084] = { ["id"] = 31084, ["name"] = "Bind the Glamour", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31084 }, ["series"] = { 31082 }, ["description"] = "It has been a very, very long time since our tribe has been called on to perform this rite. I will do the best I can.", ["objectivesText"] = "Allow Chief Rikkitun to enchant the Forked Blade. Progress: ...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 46, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 69, ["flags"] = 0 } } },
[31085] = { ["id"] = 31085, ["name"] = "Fires and Fears of Old", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31085 }, ["series"] = { 31022, 31026, 31354, 31398, 32030 }, ["description"] = "We've found the blades, bound them together with wood and shade, and blessed them with an ancient incantation. If I'm not mistaken, it's time to use this thing. The sprites spoke of an ancient piece of sap within the Amber Hibernal, a mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the prophecy spoke of. Whatever's inside that sap must be important. Good luck, <name>.", ["objectivesText"] = "Use the Ruining Fork on Iyyokuk the Lucid, then protect him until he is able to escape. Progress: Make sure to bring that forked blade with you.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84019, 84020, 84021, 84022, 84023, 84024, 84025, 84026, 84027, 84771 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 47, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 70, ["flags"] = 0 } } },
[31086] = { ["id"] = 31086, ["name"] = "Blood of Ancients", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31086 }, ["description"] = "Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the sap from the great trees of the area. I should know - I brew with the stuff all the time. The most ancient tree of all is the one that Grand Empress Shek'zeer calls her home, now known as the Heart of Fear. Find some amber from that tree, and our brew should be complete.", ["objectivesText"] = "Obtain a Chunk of Solidified Amber . Progress: Any luck?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 48, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 71, ["flags"] = 0 } } },
[31087] = { ["id"] = 31087, ["name"] = "Extending Our Coverage", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31087 }, ["description"] = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened. There is a tower in Amberglow Hollow that has been silent for many years. It must sing; the Klaxxi demand it! This time I will go with you. You will help me repair it. Take the resonating crystal and meet me in Amberglow.", ["objectivesText"] = "Activate the Resonating Beacon in Amberglow Hollow.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86009 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 17, ["flags"] = 0 } } },
[31088] = { ["id"] = 31088, ["name"] = "Crime and Punishment", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31088 }, ["series"] = { 31089, 31090 }, ["description"] = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken. The Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters .", ["objectivesText"] = "Kill 8 Ik'thik Harvesters on the Stinging Trail. Progress: Have the harvesters been punished?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 19, ["flags"] = 0 } } },
[31089] = { ["id"] = 31089, ["name"] = "By the Sea, Nevermore", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31089 }, ["series"] = { 31088, 31090 }, ["description"] = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore. The lizard men surround him. He cannot fall into their scaley hands. You will find him; you will awaken him. Do not return without him! If you do this the Klaxxi will be pleased with us.", ["objectivesText"] = "Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84119 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 23, ["flags"] = 0 } } },
[31090] = { ["id"] = 31090, ["name"] = "Better With Age", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31090 }, ["series"] = { 31088, 31089 }, ["description"] = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber. Young amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises! Gather the young amber. We will store it until it is aged and can be consumed.", ["objectivesText"] = "Gather 7 Amber-Filled Jars from the Amber Collectors on the Stinging Trail. Progress: I would go with you to gather amber, but my talents are more useful here.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84635, 84636, 84637, 84638, 84639, 85159 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 21, ["flags"] = 0 } } },
[31091] = { ["id"] = 31091, ["name"] = "Reunited", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31091 }, ["series"] = { 31359 }, ["description"] = "You look at me and see I am no great warrior. Why was I chosen to be a Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance alone. Before I explain further, I need to know that you are trustworthy. Something precious to me was hidden at the time of my preservation. I am nothing without it. Defend me as I unearth my greatest weapon, and you will have my trust.", ["objectivesText"] = "Assist Kaz'tik the Manipulator as he unearths his greatest weapon.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83983, 83984, 83985, 83986, 83987, 83988, 83989, 83990, 83991 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 25, ["flags"] = 0 } } },
[31092] = { ["id"] = 31092, ["name"] = "Feed or Be Eaten", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31092 }, ["description"] = "After years of working with the Kunchong I developed a theory; raising one from infancy would strengthen the bond and therefore strengthen the sonic connection. I had just begun training Kovok when I was chosen for encasement. He is still very young and will need diligent training to reach his full potential. I'm entrusting Kovok to you, but be warned; if any harm comes to him your life is forfeit. First, you must feed him to gain his trust. The turtles in the area should be suitable for this.", ["objectivesText"] = "Begin Kovok's training by feeding him 6 Succulent Turtle Filets found on the Brineshell Snappers in the Briny Muck.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 26, ["flags"] = 0 } } },
[31107] = { ["id"] = 31107, ["name"] = "Citizens of a New Empire", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31107 }, ["description"] = "At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a totem of horror. Like those outside of the palace, the clutch nearby is now used to corrupt our swarmborn. Recover the eggs of the Vor'thik before they are tainted. We shall raise them here. They will be the citizens of a new empire, free from the sha.", ["objectivesText"] = "Gather 10 Vor'thik Eggs from Kypari Vor. Progress: Kypari Vor was beautiful once. Rich with amber and surrounded by prime hunting grounds.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 15, ["flags"] = 0 } } },
[31108] = { ["id"] = 31108, ["name"] = "Concentrated Fear", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31108 }, ["description"] = "Amber is power. It brings life. This... dread amber you brought me has been twisted. It is concentrated fear. The Vor'thik know this well. Their kypari has been completely engulfed by sha, and they use the dread amber to quicken their own swarmborn. Bring me the crystals used by the Vor'thik fear-shapers in their rituals. The Klaxxi will study them and decide on a protocol for disposal.", ["objectivesText"] = "Gather 4 Dread Amber Foci from Vor'thik Fear-Shapers at Kypari Vor. Progress: Do you have the crystals?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31112] = { ["id"] = 31112, ["name"] = "They're So Thorny!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31112 }, ["series"] = { 29821 }, ["description"] = "The crate, once full of desperately needed supplies, has been thoroughly pillaged. A quick scan of the area shows evidence left behind by the thieves. Icy thorns, just like the ones on the water sprites on the shoreline to the east. This is a life or death situation for your band of survivors. Those supplies need to be retrieved from these thieving pests and returned to camp.", ["objectivesText"] = "Collect 5 Emergency Supplies from the Water Sprites. Progress: You manage to get your hands on them supplies, pal?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74623, 84157 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 21, ["flags"] = 0 } } },
[31121] = { ["id"] = 31121, ["name"] = "Stay a While, and Listen", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31121 }, ["series"] = { 29822, 31132, 31134 }, ["description"] = "Rush rush rush - are your people always in such a hurry? Sit and have some tea with me a moment, and we will discuss your plight. < Lorewalker Cho 's features settle into a patient smile.>", ["objectivesText"] = "Drink from Cho's Teapot. Progress: I hope I didn't bore you, traveler.", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 23, ["flags"] = 0 } } },
[31129] = { ["id"] = 31129, ["name"] = "Fate of the Stormstouts", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31129 }, ["description"] = "$p! It is so great to see you healthy, and traveling so far. It would seem that our paths are quite tightly intertwined. I'm here looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them. Have you seen anyone named Stormstout come through here? Would you mind helping me ask around?", ["objectivesText"] = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts. Progress: You are brave to have come across the wall, <race>.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 61, ["flags"] = 0 } } },
[31130] = { ["id"] = 31130, ["name"] = "A Visit with Lorewalker Cho", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31130 }, ["series"] = { 29888, 29889 }, ["description"] = "Stranger, I may be able to help you find your prince. But first, I would like to know a little more about you and your people. Come, help me with my chores, and we will chat. You have the look of a grizzled war veteran, but certainly you have a few minutes to help a bookish Pandaren like myself putter around the house, yes?", ["objectivesText"] = "Befriend Lorewalker Cho by assisting him around his house: Trim his tree, paint his wall, and feed his birds. Progress: There is nothing like a little manual labor to bring strangers together, don't you think?", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 549, ["name"] = "The Jade Forest, The White Pawn & Pearlfin Village", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 40, ["flags"] = 0 } } },
[31132] = { ["id"] = 31132, ["name"] = "A Mile in My Shoes", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31132 }, ["series"] = { 29822, 31121, 31134 }, ["description"] = "Oh, where have my manners gone? Technically, I suppose I am the host here. Allow me to tell you a little bit about myself and my people before asking questions of you.", ["objectivesText"] = "Speak to Lorewalker Cho at the Circle of Bone.", ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 24, ["flags"] = 0 } } },
[31133] = { ["id"] = 31133, ["name"] = "Kor'thik Aggression", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31133 }, ["description"] = "I'm no brewer - just looking at all those heaps of ingredients makes my head spin. Just put the brew in front of me when it's finished, thank you. No, I'm here to make sure that the brewers don't get cut in half while they're trying to make that perfect brew. It's not an easy job. The Kor'thik mantid across this basin have been attacking us nightly. If you're already heading over there, why don't you return the favor and attack a few of them?", ["objectivesText"] = "Slay 17 Kor'thik Mantid at Kor'vess. Progress: Can't stand those mantid.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84617, 84618, 84619, 84620, 84621, 84622, 84623, 84624, 84625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 59, ["flags"] = 0 } } },
[31134] = { ["id"] = 31134, ["name"] = "If These Stones Could Speak", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31134 }, ["series"] = { 29822, 31121, 31132 }, ["description"] = "This is a very ancient place, traveler. Only recently have I pieced together a method of translating the forgotten language carved into these stones. Oh, the thrill of discovery! This never gets old, I assure you. Here, you are the guest. You do the honors. I insist. Use this key to unlock the secrets the stones contain.", ["objectivesText"] = "Use the Stone Monoliths at the Circle of Bone. Progress: Your assistance is most appreciated, traveler.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 25, ["flags"] = 0 } } },
[31167] = { ["id"] = 31167, ["name"] = "Family Tree", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31167 }, ["series"] = { 29879, 29935, 29936, 29941 }, ["description"] = "So there you have it, traveler, or as much of it as would make for a proper introduction, hmm? What of you, then? Are your people so much different than mine? Surely, there must be things we share in common. Let us see...", ["objectivesText"] = "Light the Incense Bundle at the Circle of Stone. Progress: A fine day we're having, wouldn't you say?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 26, ["flags"] = 0 } } },
[31175] = { ["id"] = 31175, ["name"] = "Skeer the Bloodseeker", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31175 }, ["description"] = "Our efforts to secure the shallows before Zan'vess have paid off. We have spotted another paragon buried in amber, hidden in the waters to the southwest. Adding another paragon to our numbers is vital. Another champion from ages past could turn the tide in our favor. I would go immediately, but unfortunately, I am needed here. Since you are already a Wakener, you can carry out this task in my stead.", ["objectivesText"] = "Awaken Skeer the Bloodseeker in the underwater cave.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 29, ["flags"] = 0 } } },
[31176] = { ["id"] = 31176, ["name"] = "A Strange Appetite", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31176 }, ["description"] = "Food. I must have food. In my time, the meat of the starfish brought not only strength, but also clarity of mind. This is what I must eat. Bring this to me from the nearby shallows. Wait much longer, and I will devour you instead.", ["objectivesText"] = "Collect 12 Starfish Meat . Progress: The juices of the starfish will clear my mind.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85211 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 30, ["flags"] = 0 } } },
[31177] = { ["id"] = 31177, ["name"] = "Fine Dining", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31177 }, ["description"] = "In my living years, I was the greatest warrior of the swarm. Help me regain my strength, and I shall show you. I smell the salt sea nearby, and where you can find the sea, you will find briny clackers. Bring me their tails. I must feast upon their flesh.", ["objectivesText"] = "Collect 8 Clacker Tails . Progress: I have much work to do. The sooner I can fight, the sooner I can return to the Council.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85212 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 31, ["flags"] = 0 } } },
[31178] = { ["id"] = 31178, ["name"] = "A Bloody Delight", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31178 }, ["description"] = "A warrior is not ready for battle until he tastes the blood of his enemies. I am still too weak to hunt, so you must go in my stead. Only the blood from the fiercest predators will do. I can smell their presence in the waters outside this cave! Bring this to me, and then perhaps you shall see why they call me the Bloodseeker.", ["objectivesText"] = "Collect 100 Volatile Blood from Dread Remoras. Progress: By drinking the blood of your enemies, you acquire their strength.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 32, ["flags"] = 0 } } },
[31179] = { ["id"] = 31179, ["name"] = "The Scent of Blood", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31179 }, ["description"] = "I'm afraid that I wet my hands with saurok blood while you were away. I'm sorry, but I could not help myself. Now, watch them attack me. Pitiful! Do they think to take vengeance for their fallen? Do they come challenge ME? I, who have won a hundred wars? I, who stood alone against thousands and still shouted for my enemies to come? No, these... saurok... will crumple before me like paper before the flame! I shall show you my might, Wakener. Fight alongside me and see. Here they come!", ["objectivesText"] = "Kill 12 Muckscale Flesheaters and the Muckscale Serpentus .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84095, 84096, 84097, 84098, 84099, 84100, 90104, 90105, 90624 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 33, ["flags"] = 0 } } },
[31181] = { ["id"] = 31181, ["name"] = "Fresh Pots", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31181 }, ["series"] = { 31727 }, ["description"] = "We got a load of empty crab pots out there that need fresh bait. Now, we COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it? Never gonna happen. Head to Lonesome Cove, immediately southwest, and bait those pots with two chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water. Oh, and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the lingo.", ["objectivesText"] = "Bait 10 Empty Crab Pots in Lonesome Cove. Each pot requires 2 Sea Monarch Chunks . Progress: What's wrong, green? You aren't afraid of the dark, icy sea are you?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84001, 84002, 84003, 84004, 84005, 84006, 84007, 84008, 84009, 85230 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 50, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 40, ["flags"] = 0 } } },
[31182] = { ["id"] = 31182, ["name"] = "You Otter Know", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31182 }, ["description"] = "You know what happened to the bait in those pots? Otters. That's what happened. They prefer fresh clams, but they'll pick our crab traps clean if they're hungry enough. The otters in Lonesome Cove are protected by law and we run a legitimate operation here. As much as I'd love to chum those little rats and call it a day, we just make sure they aren't hungry enough to raid the crab pots. Toss 'em a few clams to keep them busy while you're out there.", ["objectivesText"] = "Use the Bag of Clams to feed 8 Coldwhisker Otters in Lonesome Cove.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 51, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 41, ["flags"] = 0 } } },
[31183] = { ["id"] = 31183, ["name"] = "Meet the Cap'n", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31183 }, ["description"] = "Alright, $p, I got another job for ya. You see that lion seal in the pen over there? Name's Dog. He's been Soggy's pet for years. Dog's acting up lately - I think he's getting restless in that pen. Why don't you go talk to Soggy and let him know. I'd say it's about time you meet the cap'n anyway.", ["objectivesText"] = "Speak with \"Soggy\" Su-Dao in Soggy's Gamble.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 52, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 42, ["flags"] = 0 } } },
[31184] = { ["id"] = 31184, ["name"] = "Old Age and Treachery", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31184 }, ["description"] = "Look, I ain't got reason to trust you, but there's a task I can't give to my crew. I need you to search the wreck of our old ship, the Mist-Hopper, and bring back the charter. It'd be sealed up in a silver tube, in a footlocker. It's sort of, uh... incriminating. I can't risk any of the crew finding it if they decide to visit the ol' girl. She's resting on the Shelf of Mazu, to the west. I'd suggest riding a rip current out there, if you got the stomach. They're all over the shelf.", ["objectivesText"] = "Recover the charter from the Wreck of the Mist-Hopper. Progress: To be honest, I hope a grouper ate the old charter. Wait, then it might end up here anyway. Dang it!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85886 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 53, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 44, ["flags"] = 0 } } },
[31185] = { ["id"] = 31185, ["name"] = "Walking Dog", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31185 }, ["description"] = "Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my life more than once, you know. But I'm gettin' too old to walk him anymore, and he still needs his exercise. Take Dog for a trip around the shelf for me, would ya? He loves to swim through the hot geysers just southeast of the shallows. He absolutely has to... er... \"leave his mark\" on the dead whale at the far western edge of the shelf. Oh, and he'll want to visit our old shipwreck, too. He likes to reminisce.", ["objectivesText"] = "Take Dog to visit the hot geysers, the whale corpse, and the wreck of the Mist-Hopper on the Shelf of Mazu.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84010, 84011, 84012, 84013, 84014, 84015, 84016, 84017, 84018, 85955 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 43, ["flags"] = 0 } } },
[31186] = { ["id"] = 31186, ["name"] = "Dog Food", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31186 }, ["description"] = "< Dog whines as best as a lion seal can, feebly lifting one flipper toward his massive jaws. He's hungry. The Shelf of Mazu is covered in rockshell makrura that should make a fine meal for him.>", ["objectivesText"] = "Help Dog to eat the remains of 10 Rockshell Snapclaws. Progress: <This has got to be the most pathetic lion seal you've ever seen.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 45, ["flags"] = 0 } } },
[31187] = { ["id"] = 31187, ["name"] = "On the Crab", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31187 }, ["description"] = "I just got word that a string of pots we dropped this morning hit it BIG. We're on the crab! Problem is, the rips are getting stronger and we lost track of some of the pots. They're just sitting out there, filled with spiky blue GOLD! I need you back out there. Hook one of these buoys up to any of the full traps you find and send it to the surface for us.", ["objectivesText"] = "Attach a Mist-Hopper Buoy to 8 Full Crab Pots on the Shelf of Mazu.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 3666, 3683, 59729, 59730, 59731, 59759, 59760, 59761, 68609, 85972 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 54, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 46, ["flags"] = 0 } } },
[31188] = { ["id"] = 31188, ["name"] = "Shark Week", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31188 }, ["description"] = "Crabbing is our big money-maker, but we send all kinds of goods back around the wall. Oils, plants, even rare minerals - the sea's bounty is rich out here! Right now the big craze in the markets back home is thresher teeth . Apparently they make great necklaces? Threshers are all over the Shelf of Mazu to the west. Bring me lots of teeth!", ["objectivesText"] = "Collect 200 Thresher Teeth by pulling them from the jaws of Longfin Threshers on the Shelf of Mazu. Progress: Having actually seen someone eaten by a thresher, I'm not sure why you'd willingly string their teeth around your neck, but whatever.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 36438, 85998, 85999 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 47, ["flags"] = 0 } } },
[31189] = { ["id"] = 31189, ["name"] = "Reeltime Strategy", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31189 }, ["description"] = "I never thought I'd see the day, but for the first time since... well, EVER, Master Angler Ju Lien asked for some help with his lines. Apparently the sea is going crazy today and he can't keep up. See if you can give him a hand. He's fishing just south of here.", ["objectivesText"] = "Assist Master Angler Ju Lien in Soggy's Gamble. Progress: Go give Ju Lien a hand, would ya?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 55, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 48, ["flags"] = 0 } } },
[31190] = { ["id"] = 31190, ["name"] = "The Mariner's Revenge", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31190 }, ["description"] = "I'm not gonna sit in a damn rocking chair while my crew gets devoured by a leviathan! Come on, let's get to the dock and launch a dinghy. I got a special one set up just for this kind of situation. My own little Mist-Hopper Jr. We'll give that thing a case of harpoon fever.", ["objectivesText"] = "Launch the Mist-Hopper Jr. from the dock in Soggy's Gamble and use it to bring down Jiao. Progress: Let's go!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83992, 83993, 83994, 83995, 83996, 83997, 83998, 83999, 84000 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 56, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 49, ["flags"] = 0 } } },
[31228] = { ["id"] = 31228, ["name"] = "Prophet Khar'zul", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31228 }, ["series"] = { 30946, 31011 }, ["description"] = "Prophet Khar'zul is a powerful caster, but he is also underestimating your abilities. Khar'zul and his forces must be destroyed to protect this village. His death will send a strong message to the Thunder King that we will not be defeated! You'll find him on the Isle of Reckoning.", ["objectivesText"] = "Defeat Prophet Kharzul. Progress: Is Khar'zul dead?", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82514, 82515, 82516, 82517, 82518, 82519, 82520, 82521, 82522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31230] = { ["id"] = 31230, ["name"] = "Welcome to Dawn's Blossom", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31230 }, ["description"] = "Cho's off on another one of his adventures, and this one requires a big order of jade. I'm going to have to call in some favors. How 'bout in the meantime you introduce yourself to some of the locals. Kai Wanderbrew is a good guy to know, as is Master Windfur . Oh, and say hi to Peiji Goldendraft up at the inn. Between the three of them, you should get the feel for life in Dawn's Blossom.", ["objectivesText"] = "Speak with Kai Wanderbrew , Master Windfur , and Peiji Goldendraft in Dawn's Blossom. Progress: Any luck?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 553, ["name"] = "The Jade Forest, Dawn's Blossom & Tian Monastery & Nectarbreeze Village", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 50, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 46, ["flags"] = 0 } } },
[31241] = { ["id"] = 31241, ["name"] = "Wicked Wikkets", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31241 }, ["description"] = "<name> good wikket, they say... <name> help hozen, they say... No more grookin' <name>, they say. That ok. Look out there. Wicked wikkets fallin' like rain, ripe for the grookin'! Go, join the fun. But remember, Chief Kah Kah gets all the shinies! That's hozen rule number two. < Jeek Jeek scratches his head.> Hmm, all hozen rules are number two...", ["objectivesText"] = "Collect 6 Alliance Service Medallions from Battleworn Paratroopers Progress: Whatcha got, wikket?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 40727, 85783, 85784, 88699, 88700, 88701, 88702, 88703 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 30, ["flags"] = 0 } } },
[31251] = { ["id"] = 31251, ["name"] = "Best Meals Anywhere!", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 379, ["storyline"] = { 31251 }, ["description"] = "Yeah, yeah. Everyone knows us goblins do tinkering. And explosives. And... well, ya' know, the less reputable stuff. But what nobody knows is that I'm really a great chef! It's a hobby of mine. Gather us up some meaty bits from the creatures around here, and I'll cook us up the best meals ANYWHERE! And I promise, I'll only use three or four percent rocket fuel.", ["objectivesText"] = "Collect 160 Kun-Lai Meaty Bits . Progress: The meaty bits, <name>? We need 'em!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 21025, 80245 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 12, ["flags"] = 0 } } },
[31252] = { ["id"] = 31252, ["name"] = "Back to Westwind Rest", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31252 }, ["description"] = "Well, far as I figure, we've got quite a lot of rebuildin' to do. I'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" So, who am I to stop 'em? Bring 'em with you, back to Farmhand Bo . I'll miss 'em, but they're better off with you.", ["objectivesText"] = "Return to Farmhand Bo at Westwind Rest in Kun-Lai Summit .", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 15, ["flags"] = 0 } } },
[31253] = { ["id"] = 31253, ["name"] = "Back to Eastwind Rest", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31253 }, ["description"] = "Well, far as I figure, we've got quite a lot of rebuildin' to do. I'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Horde\". So, who am I to stop 'em? Bring 'em with you, back to Farmhand Ko . I'll miss 'em, but they're better off with you.", ["objectivesText"] = "Return to Farmhand Ko at Eastwind Rest in Kun-Lai Summit .", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 15, ["flags"] = 0 } } },
[31256] = { ["id"] = 31256, ["name"] = "Round 'Em Up", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31256 }, ["description"] = "Lok'tar, <class>. We've made progress, but we're going to need mobility if we want to maintain our foothold here in Kun-Lai. I don't see many worgs, kodo, or the like around here. What I do see are yaks. Our pandaren allies have said they make good mounts, so they'll have to do. Go round some up and return them here, so we can get our people riding them!", ["objectivesText"] = "Round up 3 Wild Plains Yaks and return them to Eastwind Rest. Progress: The yaks?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 15697, 15698, 15864, 15865, 28501, 62178, 62179, 62180, 84509, 84510, 84511, 84512, 84513, 84514, 84515, 84516, 84517 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 8, ["flags"] = 0 } } },
[31265] = { ["id"] = 31265, ["name"] = "Mazu's Breath", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31265 }, ["description"] = "Here to help, are ya? Well, first thing's first. <Arie rummages through her pockets for a moment before producing a small vial of glowing blue fluid.> Here it is! \"Mazu's Breath.\" Cap'n's own formula. What? You thought I'd send you out to sea without a means of breathin'? I need deckhands, not corpses! Down the hatch with it, green. This'll give you a fighting chance out there on the shelf.", ["objectivesText"] = "Drink the Potion of Mazu's Breath . Progress: No, I don't have a \"chaser!\" Just drink it!", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["rewardItems"] = { 85869 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 49, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 39, ["flags"] = 0 } } },
[31303] = { ["id"] = 31303, ["name"] = "The Seal is Broken", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31303 }, ["series"] = { 30485, 30500, 31362 }, ["description"] = "<Cho looks at you in disbelief.> I... I thought Sha of this immensity were a myth - we all did. Just a story to keep our children from fighting. No time to talk now. Those fissures - they're feeding it... it grows stronger by the moment! I must research the scrolls from my family archives. You, take this cannon and ride Mishi. You must find a way to contain this horror that has been unleashed!", ["objectivesText"] = "Seal 12 Sha Fissures to banish the Sha of Doubt.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 83, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 78, ["flags"] = 0 } } },
[31319] = { ["id"] = 31319, ["name"] = "Emergency Response", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31319 }, ["description"] = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict. The full extent of their destruction here we cannot yet know. Already it is... unspeakable. Nevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care. These fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", ["objectivesText"] = "Use Cho's Fireworks near Admiral Taylor , Mishka and Sully .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 86511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 554, ["name"] = "The Jade Forest, Greenstone Quarry & Terrace of Ten Thunders & The Jade Serpent", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 86, ["flags"] = 0 } } },
[31359] = { ["id"] = 31359, ["name"] = "The Kunchong Whisperer", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31359 }, ["series"] = { 31091 }, ["description"] = "To really connect with Kovok you need to challenge him mentally and physically. You must respect his strength and intelligence; only then will he allow you to really train him. The muckscale tribe may provide an adequate test of his abilities and with you there he shouldn't be in danger. Additionally, this will allow us to decrease their numbers in the Briny Muck.", ["objectivesText"] = "Kill Oracle Hiss'ir and 10 Muckscale tribe members.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 27, ["flags"] = 0 } } },
[31394] = { ["id"] = 31394, ["name"] = "A Celestial Experience", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31394 }, ["series"] = { 31392, 31512 }, ["description"] = "Nobody is allowed into the Vale without the approval of the August Celestials. Xuen , The White Tiger, appears ready to listen to me. But Taran Zhu of the Shado-Pan is reluctant to let the Alliance or Horde anywhere NEAR the Vale after all that's happened. <Anduin shakes his head.> Maybe you can help me make my case. Speak to the White Tiger on our behalf. Be careful! He may set a number of challenges before you...", ["objectivesText"] = "Speak to Xuen and complete his tests. Progress: Are you finished with the White Tiger's tasks?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 51, ["flags"] = 0 } } },
[31395] = { ["id"] = 31395, ["name"] = "A Celestial Experience", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31395 }, ["series"] = { 31393, 31511 }, ["description"] = "The human calf is arguing on our behalf. He is well-spoken; I can see why Baine Bloodhoof regards the prince so highly. Still, the argument does not go well. I am of little consequence, but you are a hero of the Horde. Perhaps you can intercede in our favor? Speak with the White Tiger and plead our case, <race>. Be careful! He may set a number of challenges before you...", ["objectivesText"] = "Speak to Xuen and pass his tests. Progress: Have you passed the White Tiger's tests. <race>?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 52, ["flags"] = 0 } } },
[31398] = { ["id"] = 31398, ["name"] = "Falling to Pieces", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31398 }, ["series"] = { 31022, 31026, 31085, 31354, 32030 }, ["description"] = "Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be so protective of it? It is unlikely this came from the heavily guarded Zan'vess, so where did it come from? Perhaps the Klaxxi will know what to make of it.", ["objectivesText"] = "Return the Glowing Amber to Kaz'tik the Manipulator . Progress: Where did you find this?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84626, 84627, 84628, 84629, 84630, 84631, 84632, 84633, 84634, 86533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 28, ["flags"] = 0 } } },
[31453] = { ["id"] = 31453, ["name"] = "The Shado-Pan", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31453 }, ["description"] = "Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive. It's clear that, no matter what happens here in Kun-Lai, making an alliance with these Shado-Pan will be critical to our foothold in Pandaria. That's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook. You will go there, and curry their favor. For the Horde!", ["objectivesText"] = "Speak to Shado-Master Chong at Shado-Pan Fallback in Firebough Nook.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 87315, 87316, 87317, 87318, 87319, 87320, 87321, 87322, 87323 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5496, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5496, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 21, ["flags"] = 0 } } },
[31455] = { ["id"] = 31455, ["name"] = "The Shado-Pan", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31455 }, ["description"] = "Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive. That's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook. You should travel there as an envoy of the Alliance. Give them any help they require.", ["objectivesText"] = "Speak to Shado-Master Chong at Shado-Pan Fallback in Firebough Nook.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 87315, 87316, 87317, 87318, 87319, 87320, 87321, 87322, 87323 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5491, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5491, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 21, ["flags"] = 0 } } },
[31511] = { ["id"] = 31511, ["name"] = "A Witness to History", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31511 }, ["series"] = { 31393, 31395 }, ["description"] = "I will gather up the other Tauren pilgrims and we will travel into the Vale together. Meet me at the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.", ["objectivesText"] = "Speak with Sunwalker Dezco at the Gate of the August Celestials. Progress: You must be <name>.", ["rewardGold"] = 51000, ["rewardXP"] = 64000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[31512] = { ["id"] = 31512, ["name"] = "A Witness to History", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 31512 }, ["series"] = { 31392, 31394 }, ["description"] = "The celestials are allowing us back into the Vale! This will be a sight to behold. We shouldn't waste any time. Head to the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.", ["objectivesText"] = "Speak with Anduin Wrynn at the Gate of the August Celestials. Progress: You must be <name>.", ["rewardGold"] = 51000, ["rewardXP"] = 64000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[31656] = { ["id"] = 31656, ["name"] = "The Threat in the South", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31656 }, ["series"] = { 30968, 30981, 31063, 31064 }, ["description"] = "With the Sha of Hatred dead, the greatest threat to this land is vanquished, but our travels along the southern border have made it exceedingly clear that the mantid forces in the Dread Wastes are on the move, and likely won't be held back for long. If you wish to continue to aid the Shado-Pan, I would recommend reporting in to Bowmistress Li on the Serpent's Spine. She oversees the great wall that separates the terrors in the Dread Wastes from our bountiful lands to the east.", ["objectivesText"] = "Speak with Bowmistress Li on the Serpent's Spine.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31660] = { ["id"] = 31660, ["name"] = "Not Fit to Swarm", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31660 }, ["description"] = "Newly hatched mantid have only two instincts: kill and feed. They turn on one another, devouring the weak and leaving the strongest to mature. Those hatched during a swarm - the swarmborn - are turned loose on our enemies instead. The swarmborn in the Clutches of Shek'zeer have been tainted. They are born into shadows and nightmares. Driven by terror, not hunger. They are not fit to swarm. They must be purged.", ["objectivesText"] = "Slay 30 Shek'zeer Swarmborn in the Clutches of Shek'zeer.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 8, ["flags"] = 0 } } },
[31661] = { ["id"] = 31661, ["name"] = "A Source of Terrifying Power", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31661 }, ["description"] = "<The clutch-keepers seem to be using these blinding white crystals as magical foci. Peering inside, you see thick tendrils of black smoke swirling in the center. One of the workers at Klaxxi'vess may know more about this material and why it is so abundant in the wastes.>", ["objectivesText"] = "Bring the Sha-Haunted Crystal to Ambersmith Zikk at Klaxxi'vess. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 88538 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 11, ["flags"] = 0 } }, ["startItems"] = { 88538 } },
[31682] = { ["id"] = 31682, ["name"] = "By the Sea, Nevermore", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31682 }, ["series"] = { 31679, 31680, 31681 }, ["description"] = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore. The lizard men surround him. He cannot fall into their scaley hands. You will find him; you will awaken him. Do not return without him! If you do this the Klaxxi will be pleased with us.", ["objectivesText"] = "Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84119 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 562, ["name"] = "Dread Wastes", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 24, ["flags"] = 0 } } },
[31687] = { ["id"] = 31687, ["name"] = "Thinning the Sik'thik", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 31687 }, ["description"] = "For all our efforts to keep the mantid in the Dread Wastes, some have broken through, seemingly intent on Niuzao Temple. My men have been attempting to extinguish their presence to the west, at Sik'vess, but to no success. If you're half of the <class> Taran paints you to be, maybe you will fare better. Head west, and kill any Sik'thik mantid you find. And remember, this is no time for mercy. There are lives at the temple depending on us.", ["objectivesText"] = "Kill 12 Sik'thik mantid.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 83716, 83717, 83718, 83719, 83720 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 561, ["name"] = "Townlong Steppes", ["orderIndex"] = 50, ["flags"] = 0 }, { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 47, ["flags"] = 0 } } },
[31688] = { ["id"] = 31688, ["name"] = "The Search for Restless Leng", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 31688 }, ["description"] = "One of my best scouts, Restless Leng , went missing during a mission on the other side of Sik'vess. I'm hopeful that he was captured rather than killed, but with the mantid corrupted so heavily by sha, it doesn't seem likely. Still, can you investigate the cages around Sik'vess? I owe him a more thorough search than even this, but I have no men to spare without allowing our southern lines to break. Please, <class>, even if there's no life left in him, find him that I might know his fate.", ["objectivesText"] = "Search Sik'thik Cages for Restless Leng .", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5492, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5492, ["name"] = "Townlong Steppes", ["orderIndex"] = 48, ["flags"] = 0 } } },
[31689] = { ["id"] = 31689, ["name"] = "The Dreadsworn", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31689 }, ["description"] = "The Klaxxi see far and hear much. They have shared their insight with me. The Vor'thik embrace the sha, using its power to fuel their march in this false swarm. Their warriors consume tainted amber and call themselves dreadsworn. There is no future for them. They are waste which needs disposing. And YOU will begin that process for us when you reach Kypari Vor.", ["objectivesText"] = "Slay 6 Vor'thik Dreadsworn at Kypari Vor.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5493, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5493, ["name"] = "Dread Wastes", ["orderIndex"] = 13, ["flags"] = 0 } } },
[31694] = { ["id"] = 31694, ["name"] = "Hisingen Blues", ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 12, ["mapID"] = 224, ["storyline"] = { 31694 }, ["series"] = { 30173 }, ["description"] = "test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crl *DO NOT LOCALIZE*", ["objectivesText"] = "test log desc ! 1 Julia Stevens Julia Stevens 1 test cona Julia Stevens fodasse $o1x caracois $o1 crl *DO NOT LOCALIZE*", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 3, ["title"] = "Test Campaign", ["questLineID"] = 863, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 224, ["questLines"] = { { ["id"] = 863, ["name"] = "Francesco Test Quest Line", ["orderIndex"] = 1, ["flags"] = 0 } } },
[31732] = { ["id"] = 31732, ["name"] = "Unleash Hell", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31732 }, ["series"] = { 29547, 29548, 31733 }, ["description"] = "I will NOT let the Horde gain a foothold on these shores before we do! If you're looking to jump into the fray, I've got a spare gyrocopter for you at the end of the runway. An attack run is already programmed in, all you have to do is concentrate on shooting. Unleash hell upon these orcs!", ["objectivesText"] = "Use a Skyfire Gyrocopter to slay 60 of the Garrosh'ar troops and destroy 8 Garrosh'ar Shredders , and then sink the Bladefist Reaper and Stygian Scar. Progress: What are you waiting for?! Scorch the ground beneath them!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 90374, 90375, 90376, 90377, 90378, 90379, 90380, 90381, 90382, 90383 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 2, ["flags"] = 0 } } },
[31733] = { ["id"] = 31733, ["name"] = "Touching Ground", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31733 }, ["series"] = { 29547, 29548, 31732 }, ["description"] = "Their town is burning and their men are scattered and broken. I need every available man on the ground NOW to finish them off. Grab one of the parachutes on the edge of the ship and get down there!", ["objectivesText"] = "Use a Skyfire Parachute to touch ground in Garrosh'ar Point, then speak to Sully \"The Pickle\" McLeary . Progress: Move it!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 3, ["flags"] = 0 } } },
[31734] = { ["id"] = 31734, ["name"] = "Welcome Wagons", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31734 }, ["description"] = "Did you see the size of those war wagons? They're packing so many explosives, I cannae tell if the Horde is here to take over this continent or just blow it out of the sea! We need to neutralize those wagons before they leave Garrosh'ar Point. Here, take me pocket flares. Fire 'em into a wagon and watch the fireworks!", ["objectivesText"] = "Use Sully's Flaregun to destroy 5 Horde War Wagons . Progress: Did \"The Pickle\" send you with a mission?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 89612 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 5, ["flags"] = 0 } } },
[31735] = { ["id"] = 31735, ["name"] = "The Right Tool For The Job", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31735 }, ["description"] = "I've scouted the area and found no leads on the prince or Admiral Taylor. We need to neutralize this base quickly and continue our search elsewhere. Operations here are being led by an orc warlock; Ga'trul . He's barricaded the dock and is trying to escape through a demonic circle. Put that flaregun to work again and blow those barricades! I'll cover your back and move in when you reach Ga'trul .", ["objectivesText"] = "Use Sully's Flaregun to clear out the barricades and confront Ga'trul at the end of the dock. Progress: We will complete our mission, but right now our priority is that <class>!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 89624, 90347, 90348, 90349, 90350, 90351, 90352, 90353, 90354, 90355 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 6, ["flags"] = 0 } } },
[31736] = { ["id"] = 31736, ["name"] = "Envoy of the Alliance", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31736 }, ["description"] = "North of this base is a cherry blossom orchard and a village tucked away behind it. We will need to quarter there and tend to our wounded while we plan our next move. Head to that village and make contact with the native leader. Agent Mishka and I will rendezvous with you there. Be courteous, <name>! I am authorizing you to represent the entire Alliance here. I'm banking that seeing a powerful Alliance hero like you should make a favorable impression.", ["objectivesText"] = "Find and meet with the leader of Paw'don Village.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 7, ["flags"] = 0 } } },
[31737] = { ["id"] = 31737, ["name"] = "The Cost of War", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31737 }, ["description"] = "This whole place is going up in flames and the Skyfire is reporting that more of those... shadows are crawling up out of the ground. We need to get our people out of here. Clear a path through the base on your way north and head for the town. I will rendezvous with you there.", ["objectivesText"] = "Slay 15 Sha Haunts and 5 Sha Harbingers in Garrosh'ar Point. Progress: You have no idea what kind of consequences your actions may have here!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 8, ["flags"] = 0 } } },
[31738] = { ["id"] = 31738, ["name"] = "Pillaging Peons", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31738 }, ["description"] = "How did my village become a battlefield? To the west, your Horde enemies cut down our precious orchard. Without our apple trees, we will have no harvest, no food, and no livelihood. If you are truly different than this Horde, show us! Help us protect our grove by killing those who defile the land.", ["objectivesText"] = "Kill 12 Twinspire Taskmasters or Twinspire Peons . Progress: It is easier to harbor hatred than to make peace.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 7, ["flags"] = 0 } } },
[31739] = { ["id"] = 31739, ["name"] = "Priorities!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31739 }, ["series"] = { 31740 }, ["description"] = "Those \"orc\" things ransacked the brewery and made off with my family's finest barrels of cider. I know there is a war out there, but I am not a brewer who will stand idly by while his prized vintage is chugged by undeserving lips. The \"Horde\" will likely put up some resistance. Why don't you put that weapon to good use and help me recover my cider?", ["objectivesText"] = "Collect 6 Applebloom Cider. Progress: Is that my husband with you? Did you recover the cider?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 9, ["flags"] = 0 } } },
[31740] = { ["id"] = 31740, ["name"] = "Koukou's Rampage", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31740 }, ["series"] = { 31739 }, ["description"] = "We have more than just our cellars to worry about. Koukou , our beloved mushan, has gone crazy! Just look at him! I've tried cajoling and pleading and yelling and soothing, but nothing has worked. I'm afraid he is no longer of his own mind. There is only one way to save him, and our brewery. Strike swift and sure. He will not feel a thing.", ["objectivesText"] = "Kill Koukou .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 10, ["flags"] = 0 } } },
[31741] = { ["id"] = 31741, ["name"] = "Twinspire Keep", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31741 }, ["description"] = "I do not trust this Horde. They wield foul magic, and their intentions are clearly malevolent. We can no longer stand their presence in Twinspire Keep, so close to Paw'don. I beg you, visitor: thin their numbers before they do something awful to this village.", ["objectivesText"] = "Slay 15 Horde troops in Twinspire Keep. Progress: Gol' dang, but there's a bunch of 'em down there...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 11, ["flags"] = 0 } } },
[31742] = { ["id"] = 31742, ["name"] = "Fractured Forces", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31742 }, ["description"] = "The Horde have made our jobs easier for us. Their infighting and segregation have split their camp in two: orcs in the west, and undead in the east. The orcs obey their commander Dalgan , while the undead follow Bellandra Felstorm , a powerful warlock. Hopefully, their internal squabbles will be enough of a distraction that you'll be able to sneak in there and kill both of them. Sully has already infiltrated the ruins; find him inside when you are done.", ["objectivesText"] = "Slay Dalgan and Bellandra Felstorm . Progress: Pretty scary-lookin' characters around here...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 12, ["flags"] = 0 } } },
[31743] = { ["id"] = 31743, ["name"] = "Smoke Before Fire", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31743 }, ["description"] = "Sully scouted the Horde establishment to the north, and he reports seeing a large pile of explosives, along with a small force of demolishers. That's not to mention the demons that their warlocks have summoned. Luckily, we came prepared. We've got air support from the Skyfire. We just need to show our pilots where to strike. <Rell hands you a smoke flare, and gives you a knowing nod.>", ["objectivesText"] = "Use the Alliance Flare to call in an airstrike on the Pile of Munitions, the Twinspire Demolishers, the Wild Imps, and Xhu'daggab. Progress: What's that you've got, lad? Some kind o' flare? Shoot, I coulda put together a better flare'n that in half a wink, if Rell had only asked.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 89602 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 13, ["flags"] = 0 } } },
[31744] = { ["id"] = 31744, ["name"] = "Unfair Trade", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31744 }, ["description"] = "Though we have only just met, we have a common enemy: this group called the \"Horde.\" Several days ago, their leader made us a trade offer. When we refused, his servants abducted several of our cubs as bargaining chips. We have called in the Shado-Pan to help, but they are in Kun-Lai Summit, a journey of several days. Can you come to our aid?", ["objectivesText"] = "Free 8 Captive Pandaren Cubs from Twinspire Keep by slaying the demonic eyeballs that watch over them.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31745] = { ["id"] = 31745, ["name"] = "Onward and Inward", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31745 }, ["series"] = { 30070 }, ["description"] = "\"Sha\" energy, hm? Tread carefully, <name> - there's a hidden darkness to this continent. We'll stay behind to mop up the rest of the Horde, but we need you to continue with the main mission: the rescue of Captain Taylor, and the retrieval of Prince Anduin. Our aerial scouts think we've found the wreckage of the flagship near Paw'don Village. Go there and report to Admiral Rogers for instructions. You are welcome to use my gyrocopter.", ["objectivesText"] = "Report to Admiral Rogers at Paw'don Village in the Jade Forest .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5488, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 547, ["name"] = "The Jade Forest, Paw'don Village", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5488, ["name"] = "The Jade Forest", ["orderIndex"] = 16, ["flags"] = 0 } } },
[31765] = { ["id"] = 31765, ["name"] = "Paint it Red!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31765 }, ["series"] = { 29611, 29612, 29690, 31766, 31767, 31768, 31769, 31853 }, ["description"] = "They shot out our engines and we floated here - HERE! Right in the firing line of the enemy! You know what to do, <name>. Get below decks and man those guns! Show these scum that they're in OUR line of fire!", ["objectivesText"] = "Use a Gunship Turret to kill 80 Thunder Hold troops and destroy 9 Thunder Hold cannons . Progress: What are you waiting for?! Get on those guns!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 90322, 90323, 90324, 90325, 90326, 90327, 90328, 90329, 90336 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 11, ["flags"] = 0 } } },
[31766] = { ["id"] = 31766, ["name"] = "Touching Ground", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31766 }, ["series"] = { 29611, 29612, 29690, 31765, 31767, 31768, 31769, 31853 }, ["description"] = "Nazgrim has taken command of the ground assault and has requested that you be sent to meet up with him immediately. We have several rappelling ropes setup near the guns. Fastest way down you're going to find, save the one that ends poorly.", ["objectivesText"] = "Use a Rappelling Rope to reach the ground. Progress: What?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 12, ["flags"] = 0 } } },
[31767] = { ["id"] = 31767, ["name"] = "Finish Them!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31767 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31768, 31769, 31853 }, ["description"] = "We've softened them up. Now it's time to finish them off! That fortress must be cleansed of Alliance, and we've got nowhere to keep any prisoners. <The hint of a smile crosses Nazgrim's face.> You know what to do, <name>. The cowards will run if you give them the chance. See that you don't!", ["objectivesText"] = "Slay 15 Thunder Hold troops.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 13, ["flags"] = 0 } } },
[31768] = { ["id"] = 31768, ["name"] = "Fire Is Always the Answer", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31768 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31767, 31769, 31853 }, ["description"] = "It's not enough that we destroy their forces. Nothing must be left for them to salvage! Take this flare-gun and fire it into their munitions stockpiles. Leave them nothing!", ["objectivesText"] = "Destroy 10 Stacks of Thunder Hold Munitions . Progress: Burn them out!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 89605 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31769] = { ["id"] = 31769, ["name"] = "The Final Blow!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31769 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31767, 31768, 31853 }, ["description"] = "We've learned that their captain has barricaded himself in above us. The coward allowed his forces to die while he hid from our fury! Typical Alliance! No matter. He cannot delay his fate any longer. I will scale the walls with my marines while you lead a frontal assault up the ramps. Use your flare gun on munitions near the barricades to blast your way through. We will meet you up top and destroy this pathetic excuse for a captain together!", ["objectivesText"] = "Slay Captain Doren in Thunder Hold.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 89769 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 15, ["flags"] = 0 } } },
[31770] = { ["id"] = 31770, ["name"] = "You're Either With Us Or...", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31770 }, ["description"] = "The assistance of the nearby village has now become a necessity, $p. We will need to use the village to regroup and tend to our wounded. Perhaps the villagers will join our cause after seeing the brutality unleashed by the alliance. You will act as envoy for the Horde. Ensure the cooperation of their leader. Do not disappoint me!", ["objectivesText"] = "Attempt to enlist the help of Mayor Honeydew in Honeydew Village. Progress: You seek the help of the village your war has just devastated? Interesting...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 16, ["flags"] = 0 } } },
[31771] = { ["id"] = 31771, ["name"] = "Face to Face With Consequence", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31771 }, ["description"] = "I do not know the history of this war that you fight, and I am not interested. This land responds to negative energy in kind. The hatreds, doubt, and violence you have brought here now ooze out of Pandaria like blood from an open wound. Your actions have wrought havoc all over these ruins! Clean up after yourself and meet me in the village below - I will do my best to explain what is happening here.", ["objectivesText"] = "Kill 20 Sha Haunts and 7 Sha Harbingers .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 18, ["flags"] = 0 } } },
[31773] = { ["id"] = 31773, ["name"] = "Prowler Problems", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31773 }, ["description"] = "The animals have all gone crazy! Normally the prowlers steer clear of the village, but now we can't seem to keep them away. I've never seen them act this way before! The mayor has summoned in the Shado-Pan, but they're not all here yet. Can you take care of those prowlers before they maul one of our farmers?", ["objectivesText"] = "Destroy 10 Sha-Infested Prowlers in Honeydew Glade. Progress: Look at this mess! This is madness!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 72120, 72162 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 8, ["flags"] = 0 } } },
[31774] = { ["id"] = 31774, ["name"] = "Seeking Zin'jun", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31774 }, ["series"] = { 29694, 29765, 29804 }, ["description"] = "Rivett claims to have seen Zin'jun abandon ship with the rest of the survivors. That means he's still out there somewhere. We can't leave him behind. He could be injured or worse yet, captured! Go track down Zin'jun and bring him back.", ["objectivesText"] = "Locate Zin'jun somewhere in the Ascent of the Swirling Winds.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 90313, 90314, 90315, 90316, 90317, 90318, 90319, 90320, 90321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 9, ["flags"] = 0 } } },
[31775] = { ["id"] = 31775, ["name"] = "Assault on the Airstrip", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31775 }, ["description"] = "I have found their hidden airfield, <name>: the Strongarm Airstrip. It wasn't hard to spot, it's swarming with Alliance. <Nazgrim spits.> They think they've wiped us out, but we're Horde! We fight until we're corpses... and sometimes even afterwards. Let them taste our steel!", ["objectivesText"] = "Slay 15 Strongarm troops at Strongarm Airstrip.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 12, ["flags"] = 0 } } },
[31776] = { ["id"] = 31776, ["name"] = "Strongarm Tactics", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31776 }, ["description"] = "Scouting reports from the Strongarm Airstrip are in, and I've underlined a few high-priority targets for you. Two gnomish mechanics have been keeping Alliance gyrocopters in the air. Take out the mechanics, and the gyrocopters' numbers will dwindle. A dwarven death knight wanders their perimeter. He's an adventurer like yourself - loosely allied and highly dangerous. Finally, a name I recognize: Corporal Jackson Silver . He's a hero of the Alliance and a deadshot with a crossbow. Good luck, <name>.", ["objectivesText"] = "Slay Corporal Jackson Silver , Morgus Grimhatchet , and Master Mechanic Cogswing and Gyro-Engineer Lavenderp. Progress: These aren't your normal kill targets, <name>. Be on guard.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 13, ["flags"] = 0 } } },
[31777] = { ["id"] = 31777, ["name"] = "Choppertunity", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31777 }, ["description"] = "I spotted some shoulder-mounted rocket launchers on the way over here. They mighta been fireworks. I dunno. I'm just going to assume that they were shoulder-mounted rocket launchers until I'm proven wrong. Point is, in the arms of a skilled <class> like you, they could probably take down a chopper. If you find any lying around, try pointing them at those poorly-built gyrocopters.", ["objectivesText"] = "Pick up Requisitioned Fireworks Launchers in Strongarm Airstrip, then use them on 12 Strongarm Gyrocopters . Progress: Any luck?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 89163 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31778] = { ["id"] = 31778, ["name"] = "Unreliable Allies", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31778 }, ["description"] = "We originally welcomed the Alliance as friends. Several of our villagers volunteered to help them build an airstrip. Only recently, however, did it become clear to us that they were building a war base, within shouting distance of our village. What's worse - I fear that some villagers are being held against their will. If you find them, <class>, let them know that it is time to come home.", ["objectivesText"] = "Encourage 12 Pandaren Volunteers to leave the Strongarm Airstrip.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 15, ["flags"] = 0 } } },
[31779] = { ["id"] = 31779, ["name"] = "The Darkness Within", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31779 }, ["series"] = { 31999 }, ["description"] = "You didn't see Captain Doren while you were out there, did you? That sniveling Alliance leader must be in hiding somewhere. If he wasn't in that airbase, he can't be far. Search the perimeter - try searching the cave southwest of the main airfield. I want the Alliance gone from here!", ["objectivesText"] = "Slay Captain Doren . Progress: On your way then, <name>.", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 89640 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 551, ["name"] = "The Jade Forest, First Contact", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 16, ["flags"] = 0 } } },
[31853] = { ["id"] = 31853, ["name"] = "All Aboard!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 76, ["storyline"] = { 31853 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31767, 31768, 31769 }, ["description"] = "You hear all of that, <name>? There are Alliance that need killing and I need to round up a veteran crew. You're coming with me! We won't be returning until our assignment's complete, so round up your things and make ready. I'll be aboard a newly commissioned gunship over Bladefist Bay. Don't keep me waiting!", ["objectivesText"] = "Speak to General Nazgrim aboard Hellscream's Fist.", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 550, ["name"] = "The Jade Forest, The Remains of Hellscream's Fist", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5657, ["name"] = "Mists of Pandaria", ["orderIndex"] = 9, ["flags"] = 0 } } },
[31886] = { ["id"] = 31886, ["name"] = "Dread Space", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31886 }, ["description"] = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled <class> such as yourself. Take a kite and check in with Bowmistress Li .", ["objectivesText"] = "Speak with Bowmistress Li on the Serpent's Spine.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31894] = { ["id"] = 31894, ["name"] = "A Delicate Balance", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31894 }, ["series"] = { 30786, 30787 }, ["description"] = "The calling to be a Shado-pan is one to bring balance and harmony to this land. It is our duty to ensure balance is maintained, <name>. The yaungol activity in Townlong is threatening this balance and must be stopped before it is too late. We've had sightings of yaungol in the Sumprushes. The reports indicate they are attacking the mist lurkers in the area. Find out why and put an end to it!", ["objectivesText"] = "Speak with Orbiss in the Sumprushes.", ["rewardGold"] = 11000, ["rewardXP"] = 19600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31978] = { ["id"] = 31978, ["name"] = "Priorities!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31978 }, ["description"] = "Just look at this mess! All that brew gone to waste! Taran Zhu warned us against speaking to you outsiders, but I'll take any help I can get. We were on our way to Dawn's Blossom to deliver our brew when the fighting broke out. Now all of our brew has been lost! You want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", ["objectivesText"] = "Find 6 Barrels of Honeybrew in Honeydew Glade.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31999] = { ["id"] = 31999, ["name"] = "Nazgrim's Command", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31999 }, ["series"] = { 31779 }, ["description"] = "You have a comfortable base of operations, no Alliance around for miles, and a few Horde veterans by your side. It looks like it's time to start painting this continent red. General Nazgrim should know where to start.", ["objectivesText"] = "Report to General Nazgrim at Strongarm Airstrip in the Jade Forest .", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["rewardItems"] = { 90285, 90286, 90287, 90288, 90289, 90290, 90292, 90293, 90294 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5494, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 552, ["name"] = "The Jade Forest, Strange Bedfellows & Grookin Hill", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5494, ["name"] = "The Jade Forest", ["orderIndex"] = 17, ["flags"] = 0 } } },
[32038] = { ["id"] = 32038, ["name"] = "Stag Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32038 }, ["description"] = "I always was a fan of a good stag hunt. Stags are tough, fast, and territorial. They may be plant eaters but they can give any hunter a run for his money. East of here is a whole mess of Wilderland Stags just waiting for a hunter like yourself to give 'em a good run. Happy hunting.", ["objectivesText"] = "Kill 10 Wilderland Stags . Progress: How goes the hunt?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32108] = { ["id"] = 32108, ["name"] = "Domination Point", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32108 }, ["series"] = { 32250 }, ["description"] = "Now it is time to show this new land the true strength of the Horde. Return to the beach and light the remaining signal fire . Our fleet is waiting.", ["objectivesText"] = "Light the Signal Fire on the beach of the Horde Landing Site to signal the Horde fleet.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 2, ["flags"] = 0 } } },
[32109] = { ["id"] = 32109, ["name"] = "Lion's Landing", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32109 }, ["series"] = { 32247 }, ["description"] = "For too long the Horde has been allowed to run rampant across Azeroth. I will not see these new lands conquered by some barbaric \"warchief.\" Are you ready to bring Alliance justice to the shores of Pandaria? Let us return to the landing site. Use the flare launcher to bring in the fleet proper, and begin Operation: Shieldwall.", ["objectivesText"] = "Use the Flare Launcher in Krasarang Cove to signal the Alliance fleet.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 2, ["flags"] = 0 } } },
[32190] = { ["id"] = 32190, ["name"] = "To Mogujia", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32190 }, ["description"] = "Throm-ka, <class>. While we were busy defending our foothold here, Regent Lord Lor'themar Theron led a research expedition north into Kun-Lai Summit. Unfortunately, it seems they have encountered trouble. Warchief Garrosh Hellscream has already departed to lend his assistance, but he will require additional reinforcements. Go northward into the mountains of Kun-Lai. Speak to Tak-Tak for transportation.", ["objectivesText"] = "Find Regent Lord Lor'themar Theron at Mogujia. Speak to Tak-Tak at Domination Point for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 12, ["flags"] = 0 } } },
[32191] = { ["id"] = 32191, ["name"] = "Ancient Guardians", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32191 }, ["description"] = "Before the mogu overwhelmed our scouting party, we found relics scattered amongst the ruins to the north. I would like to collect some samples, but the mogu's terracotta watchdogs are too much for us to handle. If you could clear the area of their presence, we will be able to resume our work.", ["objectivesText"] = "Kill 5 Korune Guardians .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 13, ["flags"] = 0 } } },
[32192] = { ["id"] = 32192, ["name"] = "Bloodlines", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32192 }, ["description"] = "We managed to fend off the mogu wardens and their dogs, but many of the blood elves from the scouting party were not as lucky. Many of my people are trapped inside the ruins to the north. We are devising a solution to break them out, but I believe there may be a more straightforward approach. Go to the ruins and kill the wardens guarding each prisoner. If my intuition is correct, this will free our comrades.", ["objectivesText"] = "Free 6 Domination Mages by killing Korune Wardens.", ["rewardGold"] = 86000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 14, ["flags"] = 0 } } },
[32193] = { ["id"] = 32193, ["name"] = "To Mogujia", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32193 }, ["description"] = "The Explorer's League sent an expedition north some days ago. We haven't heard from them since, and I'd sleep better at night knowing our folks aren't in some sort of trouble. Last I heard, Brann Bronzebeard was heading toward Mogujia in the Kun-Lai Summit. Find him and report back with their status. Fennie over there can give you a ride if you need one.", ["objectivesText"] = "Find Brann Bronzebeard at Mogujia. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 12, ["flags"] = 0 } } },
[32194] = { ["id"] = 32194, ["name"] = "Bad Blood", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32194 }, ["description"] = "The Explorer's League is here to excavate the ruins, and it's my job to protect them. When we arrived, we found this place crawling with blood elves. Apparently,the Horde are just as interested in the mogu as we are. This gives quite an opportunity to thin our enemies' numbers, and steal their findings, too. Slay any blood elves you find in the ruins, and bring back whatever they are digging up.", ["objectivesText"] = "Collect 5 Korune Artifacts from Silvermoon Runeseekers, Dominance Mages, or Dominance Knights. Progress: What are those blood elves after?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 13, ["flags"] = 0 } } },
[32242] = { ["id"] = 32242, ["name"] = "Buried Secrets", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6141, ["mapID"] = 390, ["storyline"] = { 32242 }, ["series"] = { 32256, 32257 }, ["description"] = "I am told that the mogu once possessed hundreds of hidden armories full of earth-shattering weapons. When a mogu army prepared for war, they struck fear and terror into the hearts of their enemies. THIS is the knowledge I seek here on Pandaria! I have sent an expedition to study some ruins to the west, but they work as slowly as dim-witted peons! Go speak to Fanlyr Silverthorn , their leader. Tell him that I want to see results immediately.", ["objectivesText"] = "Speak to Fanlyr Silverthorn at Ancestral Rise in the Vale of Eternal Blossoms.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6141 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 5, ["flags"] = 0 } } },
[32243] = { ["id"] = 32243, ["name"] = "The Source of Korune Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 394, ["storyline"] = { 32243 }, ["description"] = "Why hullo there! Have ya ever seen tha like o' these statues? Fascinatin'! I was scouting up along the ruins earlier, and I spotted somethin' innerestin' up on the highest rise. I couldn't get close enough, but I think it might be one o' these mogu statues, 'cept it was movin'! I can't get through all those nasty blood elves, but you look like you could. Would you mind going up there and bringing me back anything of interest?", ["objectivesText"] = "Collect a Sha-Touched Claw from the Korune Spellweaver. Progress: Did ya find anything up there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93190, 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 394, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 14, ["flags"] = 0 } } },
[32244] = { ["id"] = 32244, ["name"] = "The Korune", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32244 }, ["description"] = "These terracotta wardens are fearsome, but not nearly as horrifying as the creature that we found at the top of the ruins. Some of our surviving scouts reported seeing some kind of mogu spellweaver on the highest rise to the north. He practices a type of magic unlike any other we have seen. We must learn whatever we can from this creature. Slay him, and bring me anything you find.", ["objectivesText"] = "Collect a Korune Codex from the Korune Spellweaver. Progress: What did you discover?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92072, 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 15, ["flags"] = 0 } } },
