[32248] = { ["id"] = 32248, ["name"] = "A Little Patience", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 487, ["storyline"] = { 32248 }, ["description"] = "King Varian needs decisive adventurers to help him resolve a showdown between Tyrande Whisperwind and a detachment of Horde warriors holed up in the Temple of the Red Crane. Report to him immediately!", ["objectivesText"] = "Enter the \"A Little Patience\" scenario and report to King Varian Wrynn .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 92751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1104, ["db2PoiUiMapID"] = 487, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 3, ["flags"] = 0 } } },
[32249] = { ["id"] = 32249, ["name"] = "Meet the Scout", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 418, ["storyline"] = { 32249 }, ["description"] = "It has been two months since the parting of the mists. Horde scouts, seeking a suitable landing site for the fleet, have engaged Alliance forces on a small island off the coast of Krasarang Wilds. Meet with Scout Rokla and help secure the landing site.", ["objectivesText"] = "Speak with Scout Rokla at the Horde Landing Site in Krasarang Wilds.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 0, ["flags"] = 0 } } },
[32250] = { ["id"] = 32250, ["name"] = "The Might of the Warchief", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32250 }, ["series"] = { 32108 }, ["description"] = "Come, <class>! I want to inspect this island and ensure that my landing team has done their job. Blood Guard Gro'tash should be somewhere on the northern side of the island looking for a suitable place to build our keep. The goblin survey team will have gone up the eastern coast in search of oil. Let us crush this pitiful display and claim this land for the Horde!", ["objectivesText"] = "Accompany Garrosh Hellscream to find Blood Guard Gro'tash , Grizzle Gearslip , and slay 25 Alliance. Progress: Gorehowl thirsts for Alliance blood.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93169 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 1, ["flags"] = 0 } } },
[32251] = { ["id"] = 32251, ["name"] = "Dagger in the Dark", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32251 }, ["description"] = "Shadow Hunter Vol'jin has joined a group of Kor'kron scouts on an important mission for the warchief. Of course a proud member of the Horde such as yourself is welcome to go along, but be warned - it could get ugly.", ["objectivesText"] = "Enter the \"Dagger in the Dark\" scenario and report to Vol'jin .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 3, ["flags"] = 0 } } },
[32256] = { ["id"] = 32256, ["name"] = "Rise Of An Empire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 390, ["storyline"] = { 32256 }, ["series"] = { 32242, 32257 }, ["description"] = "Warchief Garrosh Hellscream travels north with a squad of his most elite soldiers. Report to him with news of our continued victory against the Alliance. Speak to Tak-Tak for transportation.", ["objectivesText"] = "Find Warchief Hellscream at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 4, ["flags"] = 0 } } },
[32257] = { ["id"] = 32257, ["name"] = "Voice of the Gods", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 32257 }, ["series"] = { 32242, 32256 }, ["description"] = "Too slowly!? We are working as quickly as possible for the Warchief! We must excavate carefully, catalogue each find, and of course follow safety procedures. He must understand! Well, we may have something to show him soon. Do you see that stone statue to the west? We suspect it is an ancient stone storage vessel. Now we just have to find a way to open it. If you would care to help us with our excavation, please go about it carefully.", ["objectivesText"] = "Investigate the Mercurial Guardian and obtain the Ancient Korune Tablet . Progress: We are quite capable of handling this excavation. I understand the Warchief sent you, but he will get faster results if he leaves us to our work.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92425, 92440, 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 6, ["flags"] = 0 } } },
[32276] = { ["id"] = 32276, ["name"] = "Tear Down This Wall!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32276 }, ["description"] = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon. I suppose we'll have to make a gate of our own then. Let me know when you're ready, <name>.", ["objectivesText"] = "Speak with Lor'themar Theron , then break into the lower city and secure it for the Horde.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 7, ["flags"] = 0 } } },
[32277] = { ["id"] = 32277, ["name"] = "To the Skies!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32277 }, ["description"] = "We can use the pterrorwing that you found to strike a decisive blow against the mogu. Their mining operation is vulnerable to attack from the air, and your pterrorwing is the only beast we have capable of flying out there. Let me know when you are ready!", ["objectivesText"] = "Gain access to the Lightning Vein Mine.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 63868, 63869, 63870, 74586, 79802, 85429, 85430, 88589, 88590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 8, ["flags"] = 0 } } },
[32278] = { ["id"] = 32278, ["name"] = "Decisive Action", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32278 }, ["description"] = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army. If we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure. I have a plan to do just that, and it won't take an entire army.", ["objectivesText"] = "Infiltrate Stormsea Landing and open the courtyard gate from within. Speak with Taoshi to begin the mission.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 9, ["flags"] = 0 } } },
[32279] = { ["id"] = 32279, ["name"] = "The Fall of Shan Bu", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32279 }, ["description"] = "Long ago, Lei Shen found a rare clutch of storm dragon eggs. One of these creatures - Nalak - was particularly brutal, and Lei Shen took it for his own. The Thunder King's servant, Shan Bu , works to resurrect Lei Shen's dragon, Nalak. We must defeat Shan Bu and, if we are able, prevent him from resurrecting the dragon.", ["objectivesText"] = "Defeat Shan Bu Progress: We must defeat Shan Bu while he is exposed!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 10, ["flags"] = 0 } } },
[32284] = { ["id"] = 32284, ["name"] = "Someone You Should See", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32284 }, ["series"] = { 32318 }, ["description"] = "$p? It is good fortune I find you. Chen Stormstout says to give this to you and ask you to meet him at Binan Village of the Kun-Lai Summit. He found a friend of yours who needs much luck to get healthy. Chen say speak to Tak-Tak for fast travels.", ["objectivesText"] = "Find Chen Stormstout at Binan Village. Speak to Tak-Tak at Domination Point for transportation. Progress: It is not my place to choose a side in this war. But I am not going to let a <race> who has accomplished so much in his day fall by the wayside.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92501 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 7, ["flags"] = 0 } } },
[32315] = { ["id"] = 32315, ["name"] = "Anduin's Plea", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 394, ["storyline"] = { 32315 }, ["series"] = { 32316 }, ["description"] = "Ah, just the <class> I was looking for. I have received an urgent letter from the young Prince Anduin. He is playing host to his father, King Wrynn, and several other Alliance dignitaries at the Shrine of Seven Stars in the Vale of Eternal Blossoms. According to his most recent correspondence, something bad is happening at the city. Please go at once and speak with him. I must settle some affairs here at Lion's Landing, but I will join you soon. Speak to Fennie if you'd like a ride to the Vale.", ["objectivesText"] = "Find Anduin at the Shrine of Seven Stars. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 394, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 15, ["flags"] = 0 } } },
[32318] = { ["id"] = 32318, ["name"] = "Regeneration Takes Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32318 }, ["series"] = { 32284 }, ["description"] = "Vol'jin would be dead if he were any race other than a troll. His regeneration is impressive, but it is being blocked by a poison. We need to cleanse this poison so that he can regenerate the damage. Take to the skies and travel southeast. Across the mountain tops of the Secret Aerie you will find needle sprites. Bring me some of the hardest needles from them you can find. With them I can attempt an acupuncture technique that should purge the poison from his body and accelerate his regeneration.", ["objectivesText"] = "Collect 10 Sturdy Needles . Progress: My herbs are the only thing keeping Vol'jin from death. I dare not leave his side.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 8, ["flags"] = 0 } } },
[32319] = { ["id"] = 32319, ["name"] = "Find Thrall!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 461, ["storyline"] = { 32319 }, ["series"] = { 32320, 32372 }, ["description"] = "< Vol'jin half opens an eye and begins to move his lips as if to speak. Though no sound comes, you decipher two words.> Find Thrall . <With an effort, Vol'jin thrusts a hearthstone into your hands and then passes out.>", ["objectivesText"] = "Find Thrall by using Vol'jin's Hearthstone . Progress: You have come a long way to see me, <race>. Speak.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92510 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 461, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 9, ["flags"] = 0 } } },
[32320] = { ["id"] = 32320, ["name"] = "The Horde Is Family", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 32320 }, ["series"] = { 32319, 32372 }, ["description"] = "This hearthstone was part of a conversation Vol'jin and I shared a long time ago. He believes his people are in danger. I don't know what all has transpired in my absence, but I can at least do this for my friend. Come, $p, travel with me to the Echo Isles. We must make sure that the Darkspear are safe.", ["objectivesText"] = "Escort Thrall to the Echo Isles.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 49046, 93169 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 10, ["flags"] = 0 } } },
[32326] = { ["id"] = 32326, ["name"] = "Insertion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 89, ["storyline"] = { 32326 }, ["series"] = { 32327, 32328 }, ["description"] = "<name>! You'll do perfectly. We know where the Alliance have hidden the Divine Bell. We've already inserted an agent into enemy territory, we just need you to help him execute his mission. Pack up, <name>. You're headed to Darnassus.", ["objectivesText"] = "Use the Sunreaver Portal in Domination Point to secure a teleport to Darnassus.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 89, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 29, ["flags"] = 0 } } },
[32327] = { ["id"] = 32327, ["name"] = "The Darnassus Mission", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 141, ["mapID"] = 89, ["storyline"] = { 32327 }, ["series"] = { 32326, 32328 }, ["description"] = "The Divine Bell is in the city. We don't want to cause a scene, we just want the artifact. I need you to find a way in, WITHOUT getting caught. That means no mounts, no flying, no fighting. I can provide aid. I will magically cloak you, so you may move with stealth. I will also give you a small charm that you may use to return to safety, should you get in trouble. Now go, <name>. Go, locate the bell, and tag it to be teleported back with you.", ["objectivesText"] = "Locate the Divine Bell. You may use the Silvermoon Charm to return to Fanlyr if you get in trouble.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 141 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 89, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 30, ["flags"] = 0 } } },
[32328] = { ["id"] = 32328, ["name"] = "Victorious Return", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 141, ["mapID"] = 418, ["storyline"] = { 32328 }, ["series"] = { 32326, 32327 }, ["description"] = "The portal by my side will return you safely to Domination Point. I will return behind you; I must clean up our tracks a bit before we leave, so that Proudmoore doesn't discover our involvement.", ["objectivesText"] = "Report your success to Nazgrim at Domination Point in Krasarang Wilds.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 141 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 31, ["flags"] = 0 } } },
[32329] = { ["id"] = 32329, ["name"] = "Get My Results!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 110, ["storyline"] = { 32329 }, ["series"] = { 32330 }, ["description"] = "Ah, $p. The Warchief has instructed me to dispatch you to Silvermoon. He grows impatient with the progress of Lor'themar's research and feels they might benefit from your... unique... experiences with the mogu. Go to Silvermoon and demand that Lor'themar increase the speed of his research.", ["objectivesText"] = "Speak with Lor'themar Theron in Silvermoon City.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92058 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 22, ["flags"] = 0 } } },
[32330] = { ["id"] = 32330, ["name"] = "What's in the Box?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 32330 }, ["series"] = { 32329 }, ["description"] = "We are trying to uncover the secrets of one of the mogu artifacts Garrosh insisted we investigate. It is proving most difficult, as anyone who probes it magically is greatly affected by raw, negative emotions. I called in the assistance of Arch-mage Aethas of the Sunreavers in the hopes that he and Rommath could crack this puzzle. They asked for you specifically - apparently you have some relevant experience? Go to the chamber below Farstrider Square east of here and see if you can assist them.", ["objectivesText"] = "Assist with Aethas and Rommath's experiment.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3487 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 23, ["flags"] = 0 } } },
[32331] = { ["id"] = 32331, ["name"] = "The Kirin Tor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 501, ["storyline"] = { 32331 }, ["series"] = { 32362 }, ["description"] = "$p, King Varian has asked that I send you after his son to Dalaran. He believes you can help negotiate the withdrawal of blood elves there. These \"Sunreavers\" claim fealty to the Horde and represent a major threat to the war effort. Now that our very own Jaina Proudmoore is in charge of the Kirin Tor it should be easy to convince her to remove this Horde threat to her city. Use the portal here in Lion's Landing to go to the Purple Parlor and lend what aid you can to Prince Anduin.", ["objectivesText"] = "Use the Portal to the Purple Parlor in Lion's Landing and meet with Anduin Wrynn .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 10, ["flags"] = 0 } } },
[32332] = { ["id"] = 32332, ["name"] = "The First Riddle: Mercy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 418, ["storyline"] = { 32332 }, ["series"] = { 32333, 32334, 32335 }, ["description"] = "So, you wake up the Monkey King for a mallet hmmm? Answer first, these riddles three, and then the mallet you shall see. First riddle! \"Softly singing a song of pain There is a creature tortured and lame. Way down south and beyond the wall, It hides from its wikket masters' call. Seek out the creature sad and somber, And free it from its untamed amber .\" Bring me the untamed amber .", ["objectivesText"] = "Find the object the Monkey King described in his riddle. Progress: Ah, the wise-ish thing returns. Have you my amber?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92539 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 33, ["flags"] = 0 } } },
[32333] = { ["id"] = 32333, ["name"] = "The Second Riddle: Fellowship", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 418, ["storyline"] = { 32333 }, ["series"] = { 32332, 32334, 32335 }, ["description"] = "You want to stop the Divine Bell? We need the mallet first. You want the mallet? We need to be friends first. You want to be friends? We need a Metal brew first. You want a Metal brew? You need to go to the Shrine of Fellowship first. You want to go to the Shrine of Fellowship? Great! It's in the Jade Forest southeast of the Tian Monastery. Ring the bell and get the Monkey King some brew while there. Oh... you may have to fight for it.", ["objectivesText"] = "Obtain Metal Brew. Progress: You have the Metal Brew ?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 34, ["flags"] = 0 } } },
[32335] = { ["id"] = 32335, ["name"] = "The Greatest Prank", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32335 }, ["series"] = { 32332, 32333, 32334 }, ["description"] = "So riddles three you answered me. Good good. The Monkey King is not so old that he tells just anyone his tricks. It was the greatest prank ever! You want to hear story of the Mallet and the Monkey? Too bad! No choice!", ["objectivesText"] = "Listen to the Monkey King 's story.", ["rewardItems"] = { 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 36, ["flags"] = 0 } } },
[32336] = { ["id"] = 32336, ["name"] = "The Handle", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32336 }, ["description"] = "There once was a Chief named Ingoo Ingoo, Who beat me in a drink drink boogaloo. He took the mallet's handle for winning, Not knowing you can't beat the King in drinking. Monkey King had to hide the mallet from the bell, But Ingoo's children do not use the handle well. Over the years they have used the handle to do harm, Now we must find the current chief so we can disarm. Go south to Unga Ingoo, Monkey King meet you there. Only wikkets show to a party with hands bare.", ["objectivesText"] = "Recover the Mallet Handle . Progress: Ingoo was a great hozen. Good leader, nice parties, and good booze.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 37, ["flags"] = 0 } } },
[32337] = { ["id"] = 32337, ["name"] = "The Head", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32337 }, ["description"] = "Monkey King receive word on where to find the head, The hozen who got it has long since been dead. Kunzen chiefs pass the relic from father to son, But then virmen Skiggit came and the head it won. Now the wikket worships it in a hollow. Since it was too ookin' big for him to swallow. I sent a royal finder north to find him and stand. Look for finder in mountains west of the Heartland.", ["objectivesText"] = "Recover the Mallet Head . Progress: You got head?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 20213, 20215, 20216, 20217, 23409, 23410, 23411, 29434, 44366, 44367, 44368, 44369, 52190, 52191, 52195, 52915, 52960, 54516, 55924, 55925, 55926, 55927, 55928, 55929, 56708, 56709, 56710, 61087, 61088, 61089, 61090, 63742, 63743, 63744, 63745, 63746, 63747, 67414, 92560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 38, ["flags"] = 0 } } },
[32338] = { ["id"] = 32338, ["name"] = "The Harmonic Ointment", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 32338 }, ["description"] = "Legends are not born, they are made. Much like your next target, a mogu named \"The Blade.\" In his bags you will find, An ointment whose sound plays with the mind. Bring this nibby ointment to the Monkey King ! And with it, he shall make the mallet sing! Travel north along the wall, and when you reach the end, turn left.", ["objectivesText"] = "Recover the Harmonic Ointment . Progress: How the mogu found the ointment is a wonder. But a lot has happened since the world tore assunder.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92562, 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 39, ["flags"] = 0 } } },
[32352] = { ["id"] = 32352, ["name"] = "A Gathering Storm", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6141, ["mapID"] = 392, ["storyline"] = { 32352 }, ["series"] = { 32351 }, ["description"] = "If General Nazgrim sent you, then I trust you are capable of discretion. When I arrived here, I found Garrosh... experimenting... with some ancient power that he found in the mountains to the north. He believes that this \"sha\" can strengthen our soldiers. Unfortunately, so far the results have been quite the opposite. Our troops are erupting into random violence. Go and interrogate them. If they threaten you, be prepared to defend yourself.", ["objectivesText"] = "Confront 6 Sha-Touched Grunts .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6141 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 392, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 21, ["flags"] = 0 } } },
[32370] = { ["id"] = 32370, ["name"] = "The Kun-Lai Expedition", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32370 }, ["series"] = { 32371, 32377 }, ["description"] = "Glory to the Alliance, <class>. We are making gains against the Horde in the Krasarang Wilds, albeit slowly. While we hold the front here, we need your help to fight a different battle - one that strikes at our enemy's heart. Our SI:7 informant, Agent Connelly , has sent word that a Horde vanguard is moving up into the northern reaches of Kun-Lai Summit. Go without delay. Make contact with Agent Connelly in the field, and find out what is going on. Speak to Fennie over there for a flight in.", ["objectivesText"] = "Find Connelly at the Grummle Bazaar. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 17, ["flags"] = 0 } } },
[32371] = { ["id"] = 32371, ["name"] = "Memory Wine", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32371 }, ["series"] = { 32370, 32377 }, ["description"] = "<The radio static crackles, and Agent Connelly continues speaking.> Now comes the real challenge, <laddie/lassie>. Head on over to the center of camp and see what you can overhear.", ["objectivesText"] = "Use the Kor'kron Disguise to enter the camp. Then drink the Memory Brew and witness Shan Kien 's past.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92766, 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 19, ["flags"] = 0 } } },
[32376] = { ["id"] = 32376, ["name"] = "To the Valley!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32376 }, ["description"] = "This sealed communication was sent for you, along with urgent orders to travel to the Valley of Emperors in Kun-Lai Summit. This looks serious. I'd not delay if I were you. Speak to Tak-Tak for transportation.", ["objectivesText"] = "Find your \"Friend from Silvermoon\" at the Valley of Emperors. Speak to Tak-Tak at Domination Point for transportation.", ["rewardGold"] = 114000, ["rewardXP"] = 7070, ["rewardItems"] = { 20560, 53388, 53389, 93019 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 16, ["flags"] = 0 } } },
[32377] = { ["id"] = 32377, ["name"] = "A Kor'kron In Our Midst", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32377 }, ["series"] = { 32370, 32371 }, ["description"] = "Garrosh is hell-bent on finding that Divine Bell. I wouldn't be surprised if he tore Kun-Lai Summit apart to find that artifact. The Warchief's called a gathering at Garrosh'ar Advance, just to our north. I need to stay here to monitor troop movements, so you'll have to infiltrate their camp and overhear their discussion. Go to Garrosh'ar Advance and steal some Kor'kron Armor from Reavers, Honor Guards, and Scouts. Take this radio earpiece. Don't contact me... I'll contact you.", ["objectivesText"] = "Collect 1 Kor'kron Helmet , 1 Kor'kron Armor , and 1 Kor'kron Boots , then combine them into a Kor'kron Disguise .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92763, 92764, 92765, 92766 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 18, ["flags"] = 0 } } },
[32378] = { ["id"] = 32378, ["name"] = "Clearing a Path", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32378 }, ["description"] = "First thing's first. If we're going to take the leader captive, we'll need to thin the numbers of his agents. Be careful. These mogu are particularly dangerous - they appear to be manipulating the sha in ways we haven't seen before.", ["objectivesText"] = "Kill 10 Korune Mogu.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 17, ["flags"] = 0 } } },
[32379] = { ["id"] = 32379, ["name"] = "Legacy of the Korune", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32379 }, ["description"] = "I'm not prepared to throw away more of our people fighting against an enemy we don't know or understand. See if you can find any clues in the area as to who exactly these \"Korune\" mogu are. A contingency in case this operation doesn't go as planned.", ["objectivesText"] = "Find the document Legacy of the Korune in the Valley of the Emperors, and collect the Sealed Korune Artifact and Korune Orders from Korune Mogu. Progress: Have you found anything on the mogu?", ["rewardItems"] = { 92801, 92802, 92803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 18, ["flags"] = 0 } } },
[32380] = { ["id"] = 32380, ["name"] = "The Best Around", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 500, ["storyline"] = { 32380 }, ["series"] = { 32381 }, ["description"] = "We're going to need help if we hope to figure out Garrosh's plans for Pandaria. I have someone specific in mind, but he will not be easy to convince. Agent Connelly considers himself retired, but one does not simply leave the SI: 7. We've had an undercover agent following his every move for months. Currently, he is disguising himself as a high roller at Bizmo's Brawlpub. Something about settling an old debt. Meet with our undercover agent in the Brawler's Guild.", ["objectivesText"] = "Report to undercover agent Townsley in Bizmo's Brawlpub in the Stormwind side of Deeprun Tram. Progress: So you think you are going to talk Connelly out of retirement? Good luck!", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 369, ["db2PoiUiMapID"] = 500, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 4, ["flags"] = 0 } } },
[32381] = { ["id"] = 32381, ["name"] = "To Catch A Spy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 2257, ["mapID"] = 500, ["storyline"] = { 32381 }, ["series"] = { 32380 }, ["description"] = "Now, I could tell you who Connelly is, but that would be too easy! To catch a spy you have to think like a spy. You have to pass the test first! The small things can say a lot about a person. It's all in the details. I'm going to give you a drink to deliver. I will give you a small detail about something the recipient is wearing. From there it will be up to you. Be careful who you pick to give drinks to. People here tend to get pretty hostile if you give them the wrong order!", ["objectivesText"] = "Deliver the Pink Marmot , the Mogu Melon Twist , and the Rusty Dagger to the correct patron. Progress: You learn to look at the details when you barkeep.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92975, 92976, 92977 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 369, ["db2PoiUiMapID"] = 500, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 5, ["flags"] = 0 } } },
[32382] = { ["id"] = 32382, ["name"] = "He's In Deep", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32382 }, ["description"] = "Agent Connelly has managed to infiltrate Garrosh's camp in Kun-Lai! He's been following their every move. Connelly requested you specifically to assist him in gathering some vital intelligence. He sent along a disguise for you. Make sure you put it on before approaching the camp! It will no doubt be heavily guarded. He insists you will know him when you see him. Something about your keen eye for details... Go talk to Fennie over there for a drop-off.", ["objectivesText"] = "Meet Connelly in Kun-Lai Summit. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 6743, 21100, 21746, 52646, 52652, 56658, 56659, 56660, 59079, 59080, 59081, 59082, 59666, 59667, 59668, 59669, 59670, 59671, 59672, 61065, 61066, 61067, 61430, 61431, 61432, 62849, 62850, 62851, 63542, 63543, 63544, 63545, 63546, 63547, 63548, 63549, 66012, 66021, 66030, 66039, 87283, 87284, 87285, 87286, 87287, 87288, 87289, 87290, 87291, 92950 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 7, ["flags"] = 0 } } },
[32384] = { ["id"] = 32384, ["name"] = "Trapping the Leader", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32384 }, ["description"] = "It is time to make our move. Go to the Tomb of Shadows, weaken him, and take him captive. I will stay here in case Garrosh arrives. He must be delayed so that we can take our prize before he destroys it in his anger. Hurry!", ["objectivesText"] = "Weaken and capture Shan Kien at the Tomb of Shadows in Kun-Lai Summit. Progress: Move, <name>!", ["rewardItems"] = { 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 19, ["flags"] = 0 } } },
[32391] = { ["id"] = 32391, ["name"] = "The Ruins of Korune", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32391 }, ["series"] = { 32392 }, ["description"] = "Garrosh sent a hundred riders to search the northern coast of Kun-Lai Summit, to seek a mogu crypt matching the one you saw in Shan Kien's memory. Out of those, one found the resting place of the Divine Bell. Blademaster Ishi is leading an advance party to secure the bell now. Go and assist him. Defend that artifact from anyone who might stand in your way! Speak to Tak-Tak without delay. He can take you there.", ["objectivesText"] = "Find Ishi at the Ruins of Korune. Speak to Tak-Tak at Domination Point for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 27, ["flags"] = 0 } } },
[32392] = { ["id"] = 32392, ["name"] = "The Divine Bell", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32392 }, ["series"] = { 32391 }, ["description"] = "If the Alliance thought they could steal the Divine Bell from us, they were wrong! Even now, we have them trapped in the crypts beneath us. Death will be the price they pay for defying us. Come, <class>. Let us show them the error of their ways.", ["objectivesText"] = "Kill Sarannha Skyglaive .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 28, ["flags"] = 0 } } },
[32393] = { ["id"] = 32393, ["name"] = "The Ruins of Korune", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32393 }, ["description"] = "It's time for our boldest move yet, <name>. Since you acquired intel on the location of the Divine Bell, we've amassed a top team to excavate the artifact without delay. Commander Sarannha Skyglaive leads the expedition into the northern-most reaches of Kun-Lai Summit. Join them at once, and use whatever skills you need to make the endeavor a success. Good luck, <class>. I don't need to tell you how important this mission is to the Alliance. Speak to Fennie. She'll get you there quickly.", ["objectivesText"] = "Find Sarannha Skyglaive at the Ruins of Korune. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 20, ["flags"] = 0 } } },
[32394] = { ["id"] = 32394, ["name"] = "The Divine Bell", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 387, ["storyline"] = { 32394 }, ["description"] = "There's no telling what lies below, so I will lead the initial scouting party myself. If your report was correct, then the Korune mogu hid the Divine Bell in the rooms below our very feet. I have a feeling they would not have left such a precious artifact unguarded. I could use a capable <class> such as yourself to watch my back. Let me know when you're ready.", ["objectivesText"] = "Kill Dreadweaver Avartu and recover the Divine Bell.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 69777, 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 387, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 21, ["flags"] = 0 } } },
[32397] = { ["id"] = 32397, ["name"] = "He Won't Even Miss It", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32397 }, ["description"] = "I've noticed Garrosh and that Reliquary blood elf carrying around some sort of journal. The journal is never more than a stone's throw away. It must be important! If you can cause enough of a distraction, you may be able to swipe the journal off the table. These yaks might just do the trick. Give one of 'em a tap and they'll do the rest. Just be ready to move fast!", ["objectivesText"] = "Create a distraction in the camp and steal the Weathered Journal . Progress: What did you find?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92804, 92950, 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 9, ["flags"] = 0 } } },
[32398] = { ["id"] = 32398, ["name"] = "The Bell Speaks", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32398 }, ["series"] = { 32399 }, ["description"] = "Your efforts have culminated in this moment, <class>. Warchief Garrosh gathers the most elite champions of the Horde in Kun-Lai Summit to witness the ringing of the Divine Bell. You have more than earned the right to participate. Go now. The dawn of the new Horde begins today. Speak to Tak-Tak. He should be able to secure your travel arrangements.", ["objectivesText"] = "Find Malkorok at Emperor's Reach. Speak to Tak-Tak at Domination Point for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 9603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 42, ["flags"] = 0 } } },
[32399] = { ["id"] = 32399, ["name"] = "Breath of Darkest Shadow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32399 }, ["series"] = { 32398 }, ["description"] = "It is time, <name>. We have traveled a long path to reach this moment. Today, our Warchief, Garrosh Hellscream , will change the course of our people's history forever. Today, we witness the birth of Garrosh's Horde! Do not let anything interfere with the ceremony!", ["objectivesText"] = "Witness the ringing of the Divine Bell. Progress: We cannot rely on fate or destiny. We must carve out our own future... the future that WE deserve!", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 43, ["flags"] = 0 } } },
[32400] = { ["id"] = 32400, ["name"] = "The Bell Speaks", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 379, ["storyline"] = { 32400 }, ["series"] = { 32401, 32455 }, ["description"] = "Horde forces are amassing in huge numbers at the Emperor's Reach, high up in the mountains of Kun-Lai Summit. The area is an ancient mogu palace, and certainly a source of untold power. This can only mean one thing. Garrosh is going to use the Divine Bell, and Anduin... and the Harmonic Mallet... are both missing. I have no doubt that the fool boy went north by himself. I don't have time to gather an elite force to detain him. You must go and stop Anduin. Fennie can take you.", ["objectivesText"] = "Find Anduin at Emperor's Reach. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 40, ["flags"] = 0 } } },
[32401] = { ["id"] = 32401, ["name"] = "Breath of Darkest Shadow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32401 }, ["series"] = { 32400, 32455 }, ["description"] = "Garrosh is right over there, and he's going to ring that bell at any moment. We don't have time to wait for my father's army. This is our only chance to stop him! I'll attempt to appeal to his senses before resorting to using the Harmonic Mallet. Charge in whenever you're ready, <name>. I'll be right behind you.", ["objectivesText"] = "Defeat Ishi and destroy the Divine Bell.", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 93385, 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 41, ["flags"] = 0 } } },
[32402] = { ["id"] = 32402, ["name"] = "The Situation In Dalaran", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 502, ["storyline"] = { 32402 }, ["series"] = { 32403, 32404, 32405, 32406 }, ["description"] = "The night elves learned that the Divine Bell was stolen. This much we anticipated. However, they've also found out that the \"neutral\" Sunreavers of Dalaran were complicit. Now, we've got a situation. I need you to go to Dalaran. Speak with Kromthar for a ride. You are to rendezvous with Grand Magister Rommath once you arrive.", ["objectivesText"] = "Speak with Kromthar to obtain a ride to Dalaran.", ["rewardGold"] = 86000, ["rewardXP"] = 177000, ["rewardItems"] = { 9603, 93169 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 502, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 32, ["flags"] = 0 } } },
[32403] = { ["id"] = 32403, ["name"] = "It Starts in the Sewers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 502, ["storyline"] = { 32403 }, ["series"] = { 32402, 32404, 32405, 32406 }, ["description"] = "Compared to the rest of the city, this part of the sewers is relatively calm. This is good - we can extract more Sunreavers in peace than we can in war. Find as many citizens as you can. Tell them that it is not safe here, that they must leave the city at once. And try to stay clear of the Silver Covenant. We don't want to cause a scene if we can avoid it. Not yet, anyhow.", ["objectivesText"] = "Evacuate 9 Sunreaver Citizens .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 502, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 33, ["flags"] = 0 } } },
[32404] = { ["id"] = 32404, ["name"] = "Violence in the Arena", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 502, ["storyline"] = { 32404 }, ["series"] = { 32402, 32403, 32405, 32406 }, ["description"] = "As I suspected, it gets worse up ahead. The Silver Covenant is outright attacking innocent Sunreavers! This cannot stand. While our prime directive is to rescue Aethas Sunreaver, we must also protect as many blood elves as we can. I will continue to scout ahead. Fight well, <class>!", ["objectivesText"] = "Slay 6 Silver Covenant Enforcers and 4 Silver Covenant Spellbows .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 502, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 34, ["flags"] = 0 } } },
[32405] = { ["id"] = 32405, ["name"] = "Hand of the Silver Covenant", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 502, ["storyline"] = { 32405 }, ["series"] = { 32402, 32403, 32404, 32406 }, ["description"] = "Every Sunreaver Jaina expels from this city is a new blade that fights for the Horde. For US. I'm off to gather more strong elves. You've proven your hand in combat thus far - go take care of that creep in the black market. When you're done, we'll meet at the ramp and prepare to go aboveground.", ["objectivesText"] = "Slay Sorin Magehand .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 502, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 35, ["flags"] = 0 } } },
[32406] = { ["id"] = 32406, ["name"] = "A Tactical Assault", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32406 }, ["series"] = { 32402, 32403, 32404, 32405 }, ["description"] = "If we're to survive up above ground, we're going to need a base of operations. I'm going to try to take the center of the city. It's risky, but hopefully Jaina and the Silver Covenant won't expect it. Stay by my side now, <name>.", ["objectivesText"] = "Follow Grand Magister Rommath into the center of Dalaran.", ["rewardGold"] = 86000, ["rewardXP"] = 177000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 36, ["flags"] = 0 } } },
[32408] = { ["id"] = 32408, ["name"] = "The Silver Covenant's Stronghold", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32408 }, ["series"] = { 32409, 32410, 32411, 32412 }, ["description"] = "I have it on good authority that Archmage Aethas Sunreaver is being held in the Silver Enclave, home of the Silver Covenant. Arcanist Rathaella holds him in captivity. Most Covenant agents are out slaughtering Sunreavers right now, which means our chance is ripe. Slay Rathaella, and spring Aethas from his prison.", ["objectivesText"] = "Slay Arcanist Rathaella .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 43824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 37, ["flags"] = 0 } } },
[32409] = { ["id"] = 32409, ["name"] = "The Kirin Tor's True Colors", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32409 }, ["series"] = { 32408, 32410, 32411, 32412 }, ["description"] = "Any pretense that the Kirin Tor might have had at being a \"neutral\" group can officially be discarded. I'm now hearing that Jaina's got Alliance troops stowed away near Antonidas Memorial. The area's free of Sunreavers, but it still makes my blood boil to see such blatant favoritism from the Kirin Tor. Go visit the memorial, <name>... and give those Alliance dogs a good kick on your way through.", ["objectivesText"] = "Slay Lieutenant Corwin and 10 of his troops.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 43824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 38, ["flags"] = 0 } } },
[32410] = { ["id"] = 32410, ["name"] = "Krasus' Landing", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32410 }, ["series"] = { 32408, 32409, 32411, 32412 }, ["description"] = "We can rescue as many Sunreavers as we want, but if they can't escape, then there's no point. The Silver Covenant will certainly be subduing and killing the Sunreavers' dragonhawks. Put a stop to it.", ["objectivesText"] = "Free 6 Sunreaver Dragonhawks .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 43824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 39, ["flags"] = 0 } } },
[32411] = { ["id"] = 32411, ["name"] = "The Remaining Sunreavers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32411 }, ["series"] = { 32408, 32409, 32410, 32412 }, ["description"] = "There's still a number of significant Sunreavers who haven't been accounted for. Odds are that they're in the Sunreaver's Sanctuary, caught by surprise. <Rommath hands you an artifact, clearly made by blood elf hands.> The place is crawling with Silver Covenant. You'll need to get in, use the Tear to evacuate the VIPs, and then get out. Stay alive, <name>.", ["objectivesText"] = "Use the Tear of the Sin'dorei on Uda the Beast , High Arcanist Savor , Magister Hathorel , Magister Surdiel , and Magistrix Vesara .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 43824, 93124 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 40, ["flags"] = 0 } } },
[32412] = { ["id"] = 32412, ["name"] = "One Last Grasp", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 94, ["storyline"] = { 32412 }, ["series"] = { 32408, 32409, 32410, 32411 }, ["description"] = "We've looked everywhere he's likely to be, except for one place: the Violet Citadel. Find out if Archmage Aethas is being held within the citadel, <name>. We may get lucky. If not... at least we saved a number of lives today.", ["objectivesText"] = "Slay Mage-Commander Zuros , then escape from Dalaran.", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 43824, 93386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 41, ["flags"] = 0 } } },
[32414] = { ["id"] = 32414, ["name"] = "Darnassus Attacked?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["mapID"] = 89, ["storyline"] = { 32414 }, ["description"] = "As you know, our night elven allies moved the Divine Bell you retrieved to Darnassus for safekeeping and study. Moments ago, they portaled some Highbourne mages over here to ask for backup. Details are hazy - some sort of stealth attack on the city? I don't know what to make of it, but Jaina Proudmoore is already on the scene and I suspect they need all the help they can get. Speak to Seamus Goldenkicks over there for a quick portal to Darnassus. Find Jaina!", ["objectivesText"] = "Speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus, then speak with Jaina once you arrive.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 89, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 22, ["flags"] = 0 } } },
[32416] = { ["id"] = 32416, ["name"] = "Jaina's Resolution", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1657, ["mapID"] = 501, ["storyline"] = { 32416 }, ["description"] = "For too long, I have toiled to mend fences between Alliance and Horde. Time and time again, I've given the Horde the benefit of the doubt - and time and time again, they stab me in the back. I refuse to be betrayed again! If the Horde intends to use the Kirin Tor as a weapon against the Alliance, then they have no place in Dalaran. Come with me, <name>.", ["objectivesText"] = "Use the portal from Darnassus to Dalaran, then speak with Vereesa Windrunner on the other side.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1657 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 24, ["flags"] = 0 } } },
[32417] = { ["id"] = 32417, ["name"] = "Sewer Cleaning", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32417 }, ["series"] = { 32418, 32419, 32420, 32421, 32423 }, ["description"] = "Jaina's doing a good job taking care of Sunreavers above ground, but there's still plenty rooting around in the sewers. Go find those lying rats and exterminate them!", ["objectivesText"] = "Slay 12 Sunreavers in the Dalaran Sewers.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 25, ["flags"] = 0 } } },
[32418] = { ["id"] = 32418, ["name"] = "Unfair Trade", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32418 }, ["series"] = { 32417, 32419, 32420, 32421, 32423 }, ["description"] = "Most shopkeepers in the Magus Commerce Exchange have sided with the Silver Covenant, but there remain a few holdouts that must be taken care of. <Vereesa shows you a list of names.> They will not go easily.", ["objectivesText"] = "Slay Inkmaster Aelon , Tolyria , Gearmage Astalon , and Sintharia Cinderweave .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 26, ["flags"] = 0 } } },
[32419] = { ["id"] = 32419, ["name"] = "Nowhere to Hide", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32419 }, ["series"] = { 32417, 32418, 32420, 32421, 32423 }, ["description"] = "The Sunreaver's Sanctuary is still crawling with those Horde-loving Sunreavers. Jaina will have sent the reasonable ones to the Violet Hold. The rest refuse to leave, raising their weapons against us. Show them the cost of their defiance. They now face the judgment of the Alliance, the Silver Covenant, and the Kirin Tor!", ["objectivesText"] = "Slay 16 Sunreavers in the Sunreaver's Sanctuary. Progress: Slay them all!", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 27, ["flags"] = 0 } } },
[32420] = { ["id"] = 32420, ["name"] = "Cashing Out", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32420 }, ["series"] = { 32417, 32418, 32419, 32421, 32423 }, ["description"] = "I just saw one of the Sunreavers - Brasael, I think his name was - running off in the direction of the bank to the north. No doubt he's trying to gather whatever assets he can before he leaves. Head him off and make sure he doesn't steal any resources from our coffers. He relinquished whatever funds he left in the bank when he and his Sunreaver kind betrayed us.", ["objectivesText"] = "Slay Magister Brasael .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 28, ["flags"] = 0 } } },
[32421] = { ["id"] = 32421, ["name"] = "Nowhere to Run", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 501, ["storyline"] = { 32421 }, ["series"] = { 32417, 32418, 32419, 32420, 32423 }, ["description"] = "Compliant Sunreavers will be sent to the Violet Hold. Defiant ones are put to the sword. NONE are to escape. The Sunreavers keep their dragonhawk mounts on Krasus' Landing. Take this dust, and use it to render them incapable of flying. Or kill them. I don't care.", ["objectivesText"] = "Render 5 Sunreaver Dragonhawks incapable of flying.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 62854, 62855, 62856, 93159 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1106, ["db2PoiUiMapID"] = 501, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 29, ["flags"] = 0 } } },
[32423] = { ["id"] = 32423, ["name"] = "What Had To Be Done", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["mapID"] = 418, ["storyline"] = { 32423 }, ["series"] = { 32417, 32418, 32419, 32420, 32421 }, ["description"] = "Thank you for your aid today, <name>. I will be handling the purge from here on out. Jaina will soon be off to Lion's Landing, to speak with King Varian. She asked for your attendance.", ["objectivesText"] = "Speak with Vereesa Windrunner to travel to Lion's Landing, then speak with King Varian Wrynn .", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 93385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 249, ["title"] = "Landfall", ["questLineID"] = 5497, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5497, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 418, ["questLines"] = { { ["id"] = 5497, ["name"] = "Operation Shieldwall", ["orderIndex"] = 30, ["flags"] = 0 } } },
[32442] = { ["id"] = 32442, ["name"] = "Impending Danger", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 41040, 41059, 41087 }, ["description"] = "Our scouts have sighted a fel command ship looming on the horizon, Grandmaster. It appears to be headed on a collision course with the Wandering Isle. We should prepare our troops for the worst case situation - an all out attack. In the meantime, let us send our champions ahead to try and divert the Legion ship's attention.", ["objectivesText"] = "Complete the mission, \"Impending Danger.\" Progress: The command ship appears to be gunning straight for us. We need everyone on alert, now!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 8, ["flags"] = 0 } } },
[32448] = { ["id"] = 32448, ["name"] = "Ties with the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32448 }, ["description"] = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien. I am needed here, so I have no choice but to ask you to recover the essential ingredient for me. We need the spirit essence of a mogu that lived in the time of the memory we wish to see. You should be able to find just such a spirit inside the Path of Conquerors, to the northeast.", ["objectivesText"] = "Recover the Spirit Essence of Varatus . Progress: You never know what you will find in a book. Especially an ancient pandaren one. I'm eager to see how this Memory Wine works.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93212 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 246, ["title"] = "Landfall", ["questLineID"] = 5499, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5499, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5499, ["name"] = "Dominance Offensive", ["orderIndex"] = 25, ["flags"] = 0 } } },
[32640] = { ["id"] = 32640, ["name"] = "Champions of the Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32640 }, ["description"] = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities. If you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them. Find and destroy members of each group to keep them destabilized, and I will make it worth your time.", ["objectivesText"] = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder , and then defeat the powerful opponents that are summoned forth.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 93803, 94221, 94222, 94233, 95350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 5, ["flags"] = 1 } } },
[32641] = { ["id"] = 32641, ["name"] = "Champions of the Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32641 }, ["description"] = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities. If you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them. Find and destroy members of each group to keep them destabilized, and I will make it worth your time.", ["objectivesText"] = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder , and then defeat the powerful opponents that are summoned forth. Progress: Against these ancient enemies, there is no rescourse. We strike first, and they do not strike at all.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94221 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 5, ["flags"] = 1 } } },
[32644] = { ["id"] = 32644, ["name"] = "The Assault on Shaol'mara", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32644 }, ["description"] = "Our scouting efforts along the coast have given us valuable intelligence about the island, <class>. However, we will accomplish nothing if we do not advance forward onto the mainland. I have assembled a team of our most elite aerial units to begin the attack. I would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment. When you are ready to begin the attack, speak to me.", ["objectivesText"] = "Complete the Assault on Shaol'mara. Speak to Jaina Proudmoore to begin the attack. Progress: We must claim a better strategic position on the island itself.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 6, ["flags"] = 0 } } },
[32654] = { ["id"] = 32654, ["name"] = "Tear Down This Wall!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32654 }, ["description"] = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon. I suppose we'll have to make a gate of our own then. Let me know when you're ready, <name>.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore , then break into the lower city and secure it for the Alliance.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 7, ["flags"] = 0 } } },
[32678] = { ["id"] = 32678, ["name"] = "Thunder Calls", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 32678 }, ["series"] = { 32680 }, ["description"] = "The time to attack the Thunder King has come! A small group of Sunreavers awaits you near the Shado-Pan Garrison in Townlong Steppes. Report to Scout Captain Elsia for further instructions.", ["objectivesText"] = "Report to Scout Captain Elsia at the Shado-Pan Garrison in Townlong Steppes.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 0, ["flags"] = 1 } } },
[32679] = { ["id"] = 32679, ["name"] = "Thunder Calls", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 32679 }, ["description"] = "The time to attack the Thunder King has come! A small group of Kirin Tor awaits you near the Shado-Pan Garrison in Townlong Steppes. Report to Vereesa Windrunner for further instructions.", ["objectivesText"] = "Report to Vereesa Windrunner at the Shado-Pan Garrison in Townlong Steppes.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388, ["questLines"] = { { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 0, ["flags"] = 1 } } },
[32681] = { ["id"] = 32681, ["name"] = "The Storm Gathers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["mapID"] = 505, ["storyline"] = { 32681 }, ["description"] = "There is no time to waste, <name>. Every moment we delay here gives the Sunreavers more of a hold on the Isle. Lady Jaina Proudmoore awaits us. We should not make her wait any longer. Speak to me when you are ready to depart. I will escort you there myself.", ["objectivesText"] = "Travel with Vereesa Windrunner to the Isle of Thunder . Progress: The key to our safety lies here, <name>. I feel it to my core that we are meant to be here.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["rewardItems"] = { 95567, 95568 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 505, ["questLines"] = { { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 1, ["flags"] = 0 } } },
[32706] = { ["id"] = 32706, ["name"] = "Allies in the Shadows", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32706 }, ["description"] = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces. I want you to meet with Taran Zhu , the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", ["objectivesText"] = "Speak to Taran Zhu in Bleak Hollow.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 2, ["flags"] = 0 } } },
[32707] = { ["id"] = 32707, ["name"] = "Secrets in the Isle of Thunder", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32707 }, ["description"] = "I do have one thing I would ask of you, <class>. We've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals. If you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.", ["objectivesText"] = "Recover 3 Shan'ze Ritual Stones . These stones are very rare, and may take some time to gather. Progress: Have you found the stones I spoke of?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94130, 94219, 94220, 94221, 94222, 94233, 95350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 }, { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 3, ["flags"] = 0 } } },
[32708] = { ["id"] = 32708, ["name"] = "Setting the Trap", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32708 }, ["description"] = "Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies. You will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants. When your enemy shows itself, show no mercy.", ["objectivesText"] = "Use 3 Shan'ze Ritual Stones to beckon a Champion of the Thunder King, and then kill him. Progress: Did the ambush succeed?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94221, 94222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 }, { ["id"] = 250, ["title"] = "The Thunder King", ["questLineID"] = 5501, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5501, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5501, ["name"] = "Kirin Tor Offensive", ["orderIndex"] = 4, ["flags"] = 0 } } },
[32709] = { ["id"] = 32709, ["name"] = "Allies in the Shadows", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["mapID"] = 504, ["storyline"] = { 32709 }, ["description"] = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces. I want you to meet with Taran Zhu , the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", ["objectivesText"] = "Speak to Taran Zhu in Bleak Hollow.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 251, ["title"] = "The Thunder King", ["questLineID"] = 5500, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5500, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1064, ["db2PoiUiMapID"] = 504, ["questLines"] = { { ["id"] = 5500, ["name"] = "Sunreaver Onslaught", ["orderIndex"] = 2, ["flags"] = 0 } } },
[32806] = { ["id"] = 32806, ["name"] = "The King and the Council", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 390, ["storyline"] = { 32806, 32807, 32816 }, ["series"] = { 32807 }, ["description"] = "I am glad you are here, <name>. I have been using my dream brew to experience events around the world, but the more I learn, the more confused I become. For instance, King Wrynn has asked the dwarves of Ironforge for more troops, but they do not all support him. I will tell you more, but I would also like to hear from your experience firsthand...", ["objectivesText"] = "Complete the \"Blood in the Snow\" scenario. You can queue from the Dungeon Finder or use Lorewalker Cho 's Dream Brew. Progress: It is not my place to make stories. I simply tell them.", ["rewardGold"] = 549600, ["rewardXP"] = 9580, ["rewardItems"] = { 98133, 211279 }, ["starts"] = { { ["mapID"] = 390, ["npcID"] = 61962, ["x"] = 0.832, ["y"] = 0.295 }, { ["mapID"] = 371, ["npcID"] = 63577, ["x"] = 0.468, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 390, ["npcID"] = 61962, ["x"] = 0.832, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 390, ["source"] = "quest_giver", ["x"] = 0.832, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 371, 390 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 252, ["title"] = "Escalation", ["questLineID"] = 5502, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5502, ["questLineOrder"] = 8 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5502, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 5502, ["name"] = "Escalation", ["orderIndex"] = 0, ["flags"] = 0 } } },
[32807] = { ["id"] = 32807, ["name"] = "The Warchief and the Darkness", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 32806, 32807, 32816 }, ["series"] = { 32806 }, ["description"] = "I see now how the Alliance king leads his people. But what is the Horde warchief up to? Just below us, a swarm of goblins are burrowing into the sacred vale on his orders. What does he hope to find there? We must find out!", ["objectivesText"] = "Complete the \"Dark Heart of Pandaria\" scenario. You can queue from the Dungeon Finder or use Lorewalker Cho 's Dream Brew. Progress: It is not my place to make stories. I simply tell them.", ["rewardGold"] = 549600, ["rewardXP"] = 9580, ["rewardItems"] = { 98133, 211279 }, ["starts"] = { { ["mapID"] = 390, ["npcID"] = 61962, ["x"] = 0.832, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 390, ["npcID"] = 61962, ["x"] = 0.832, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 390, ["source"] = "quest_giver", ["x"] = 0.832, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 390 }, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 252, ["title"] = "Escalation", ["questLineID"] = 5502, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5502, ["questLineOrder"] = 8 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5502, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 5502, ["name"] = "Escalation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[32816] = { ["id"] = 32816, ["name"] = "Path of the Last Emperor", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 32806, 32807, 32816 }, ["description"] = "In his time of uncertainty, the last emperor walked a lonely path up this mountain, until he had at last found his answers. I am here to walk the same path, and it seems you have questions of your own to be answered. Perhaps you will join me, and we can both be satisfied? Oh, but I am getting old, and this blizzard is proving too much for my bones. Could you climb ahead and anchor this rope? I can hoist myself along from there. Together we shall walk the path of the last emperor.", ["objectivesText"] = "Attach the climbing rope to each Rope Anchor along the path to help Seer Hao Pham Roo reach Seeker's Point.", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 98137, 98138, 98139, 98140, 98141, 98142, 98143, 98144, 98145, 247858 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 252, ["title"] = "Escalation", ["questLineID"] = 5502, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5502, ["questLineOrder"] = 8 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5502, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 5502, ["name"] = "Escalation", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33156] = { ["id"] = 33156, ["name"] = "Time Keeper Kairoz", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33156, 33161, 33228, 33232, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33161, 33230, 33232 }, ["description"] = "You have found your way to the Timeless Isle , <class>. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help. Midway down this beach, you will find a paved path to the east. It will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with. Kairoz will answer any questions you might have. Be careful: The way may not be safe.", ["objectivesText"] = "Speak with Kairoz on the Timeless Isle .", ["rewardXP"] = 2060, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33160] = { ["id"] = 33160, ["name"] = "Time Keeper Kairoz", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33229, 33231 }, ["description"] = "You have found your way to the Timeless Isle , <class>. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help. Midway up this beach, you will find a paved path to the east. It will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with. Kairoz will answer any questions you might have. Be careful: The way may not be safe.", ["objectivesText"] = "Speak with Kairoz on the Timeless Isle .", ["rewardXP"] = 2060, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[33161] = { ["id"] = 33161, ["name"] = "A Timeless Tour", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33336, 33337, 33338, 33375, 33376, 33377, 33378, 33379 }, ["description"] = "You should first familiarize yourself with the island. Explore. Investigate anything that catches your interest. Return when you're done, and I'll reward you for whatever information you've gathered about this strange place. And do be careful! Monstrous beasts and supernatural creatures abound.", ["objectivesText"] = "Explore the Timeless Isle .", ["rewardXP"] = 4115, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[33228] = { ["id"] = 33228, ["name"] = "Time In Your Hands", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["description"] = "Inhabitants of this strange island barter with a special currency, immune from the fickle fluctuations of time. You would do well to gather as many of these \" timeless coins \" as possible! They can be found hidden away in small caches, or gathered from creatures all around the island. Larger, rarer creatures are a better source of coins - you may find it profitable to venture forth as part of a group. Introduce yourself to Mistweavers Ai and Ku across the Celestial Court, and gather some coins for me.", ["objectivesText"] = "Gather 1000 Timeless Coins and introduce yourself to Mistweaver Ai and Mistweaver Ku . Progress: You're back already? It feels like we spoke only moments ago.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 104009, 104010, 104012, 104013 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[33231] = { ["id"] = 33231, ["name"] = "Journey to the Timeless Isle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33160, 33229 }, ["description"] = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, <class>. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time! It is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries. Here, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Lara . She will guide you to our chief investigator.", ["objectivesText"] = "Speak with Watcher Lara on the Timeless Isle , off the coast of the Jade Forest. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 104113, 211279, 219222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33232] = { ["id"] = 33232, ["name"] = "Journey to the Timeless Isle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 554, ["storyline"] = { 33156, 33161, 33228, 33232, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33156, 33161, 33230 }, ["description"] = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, <class>. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time! It is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries. Here, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Alundra . She will guide you to our chief investigator.", ["objectivesText"] = "Speak with Watcher Alundra on the Timeless Isle , off the coast of the Jade Forest. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 104110, 104113, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[33332] = { ["id"] = 33332, ["name"] = "Hints From The Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33333, 33334 }, ["description"] = "There is much to learn of this place, yet it does not yield its secrets willingly. Something you mentioned the last time that we spoke intrigues me. This Mistweaver Ai, she carries a time-worn journal , if I recall? This may be the answer to many of our questions, or it may simply raise more. I suppose that it all depends on the diligence of the explorer that put pen to paper in this preposterous place. Obtain a time-worn journal and return to me with it. We shall delve into its mysteries together.", ["objectivesText"] = "Purchase a Time-Worn Journal from Mistweaver Ai. Progress: Ah, you have returned. Do you have the journal?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 103977, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 4, ["flags"] = 0 } } },
[33333] = { ["id"] = 33333, ["name"] = "Timeless Treasures", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33332, 33334 }, ["description"] = "The journal indicates that treasures abound across the island, sometimes temptingly out of reach, and other times hidden in dark caves and hollows. What might have been secreted away here, many generations ago? And perhaps more importantly, by whom? Search the island for such treasures, and return to me with your findings. Be warned that all that glitters is not gold, yet the reverse is also true. Sometimes the simple hollowed-out stump is the best hiding place for one's valuables.", ["objectivesText"] = "Find a hidden treasure on the Timeless Isle . Progress: Time flows oddly in this place, I cannot tell if I should be sleeping or eating my mid-day meal.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[33335] = { ["id"] = 33335, ["name"] = "The Last Emperor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33340, 33341, 33342, 33343, 33374 }, ["description"] = "From what I have gathered, this place used to be a tournament ground of sorts, where warriors from throughout Pandaria would show their prowess by following in the footsteps of their last emperor, Shaohao. I have heard that when Shaohao completed his trials, he became one with the land, and enveloped Pandaria in a thick mist, obscuring it from even our abilities to penetrate the passages of time. That sounds quite interesting, perhaps you should speak with him?", ["objectivesText"] = "Speak with Emperor Shaohao . Progress: Greetings, I am Shaohao. Are you here to hear the wisdom of the celestials?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 98137, 98138, 98139, 98140, 98141, 98142, 98143, 98144, 98145, 211279, 247858 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 6, ["flags"] = 0 } } },
[33340] = { ["id"] = 33340, ["name"] = "Timeless Nutriment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33335, 33341, 33342, 33343, 33374 }, ["description"] = "As you have surmised, the flora and fauna of this island are quite unusual. Not all explanations are mysterious, however. Sometimes, we must listen to the land, to hear the tales of the world around us. Have you considered that the creatures of this island grew to such proportions simply from the nutriment of the land you walk upon? You will find nutriment in abundance throughout the island: ripe fruits, eggs, meat, flowers, nuts, and even the stones themselves. Eat, and discover the power of the land.", ["objectivesText"] = "Consume a Ripe Crispfruit, Sand-Covered Egg, Charged Crystal, Huge Yak Roast, Roasted Seed, or Fire Poppy on the Timeless Isle . Progress: Have you enjoyed the abundance of the island?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 7, ["flags"] = 0 } } },
[33341] = { ["id"] = 33341, ["name"] = "Wayshrines Of The Celestials", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33335, 33340, 33342, 33343, 33374 }, ["description"] = "Many years ago, these grounds were a place where my people would come in pilgrimage. Here, they would listen to the words of the celestials, and meditate for many days. In their meditations, they found the fear, anger, despair, doubt, and violence that plagued their spirits. Before them would be a pathway to enlightenment. For each, the pathway would be different. For all of them, the pathway began with wisdom. Travel the island, as they did, and discover one of the lost wayshrines of the celestials.", ["objectivesText"] = "Find an active Time-Lost Shrine and request a blessing from the celestials. Progress: The shrines will not always avail themselves to you. Do not give up, such is the test of patience.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[33342] = { ["id"] = 33342, ["name"] = "Drive Back The Flame", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33335, 33340, 33341, 33343, 33374 }, ["description"] = "The pandaren once existed in harmony with the Ordon yaungol. When the island suddenly disappeared, the Ordon faced certain death. In their desperation, the chief shaman called out for aid to the Fire Lords, and was answered. Ordos was his name. Now, he is a creature of anger and violence. Though his people were saved, he burns endlessly in molten agony. There is harmony no longer. The Ordon seek to take the Celestial Court, and sacrifice us all to Ordos. Drive them back, and restore balance.", ["objectivesText"] = "Earn an Honored Reputation with Shaohao by defeating yaungol forces on the Timeless Isle . Progress: The Ordon are not to be trifled with. They have survived on this island under the protections of their ever-burning demigod, Ordos.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 64399, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 11, ["flags"] = 0 } } },
[33343] = { ["id"] = 33343, ["name"] = "The Archiereus Of Flame", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 33160, 33161, 33228, 33231, 33332, 33333, 33335, 33340, 33341, 33342, 33343 }, ["series"] = { 33335, 33340, 33341, 33342, 33374 }, ["description"] = "Your efforts have driven back the Ordon and brought peace to the Celestial Court, but it will not last. It is time to silence the great emissary of Ordos - the Archiereus of Flame . Speak with Mistweaver Ku and purchase a scroll of challenge, then travel to Three-Breeze Terrace to the north. Issue a challenge at the challenge stone, it will undoubtedly catch the attention of the Ordon, drawing the archiereus out of the Ordon Sanctuary. It is your only chance.", ["objectivesText"] = "Summon and defeat the Archiereus of Flame . Progress: The emissaries of Ordos are powerful, do not underestimate them.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 103684, 103982, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 253, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5503, ["questLineOrder"] = 0 }, { ["id"] = 248, ["title"] = "Mists of Pandaria", ["questLineID"] = 5503, ["questLineOrder"] = 9 }, { ["id"] = 254, ["title"] = "The Siege of Orgrimmar", ["questLineID"] = 5557, ["questLineOrder"] = 0 }, { ["id"] = 247, ["title"] = "Mists of Pandaria", ["questLineID"] = 5557, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5503, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5557, ["name"] = "The Siege of Orgrimmar", ["orderIndex"] = 12, ["flags"] = 0 } } },
